/* ÇEVİRİ ja · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ja","olay",{
"OLAYLAR:1299-01:0":{"b": ["オスマン侯国の成立", "9f0b7c0a"], "d": ["カユ部族出身のオスマン・ガーズィーがソユト＝ドマニチ周辺で独立して行動し始めたことが、オスマン国家成立の伝統的な起点とされる。一部の歴史家は、1302年のバフェウスの勝利を真の転換点とみなす。侯国はビザンツ帝国との境界地帯に位置したため、ガザー（聖戦）の襲撃を通じて急速に力を蓄えた。ルーム・セルジューク朝の遺産が解体していくこの状況の中で、オスマン・ガーズィーの周囲にはアヒー、ガーズィー、遊牧トルクメンが集まった。シェイフ・エデバリとの結びつきは、侯国の精神的な正統性の基礎とされる。同じ日に加わったその他の地：イネギョル、ヤルヒサル。", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["ブルサの征服", "98c727fa"], "d": ["長年封鎖されていたブルサは、包囲の最終段階を指揮したオルハン・ガーズィーに降伏した。この都市は侯国最初の大きな首都となった。征服の知らせは、臨終の床にあったオスマン・ガーズィーに伝えられたと伝えられ、オスマン・ガーズィーは遺言によりブルサに埋葬された。都市は短期間のうちにモスク、イマーレット（慈善施設）、マドラサを備え、初期オスマン都市建設の模範となった。", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["イズニクの征服", "a846a811"], "d": ["ビザンツ帝国のアナトリアにおける最重要拠点の一つであったイズニク（ニカイア）は、1329年のペレカノンの勝利の後、抵抗の望みを失ってオルハン・ガーズィーに降伏した。最初のオスマン朝のマドラサがここに設立され、ダーヴード・イ・カイセリーのような学者が講義を始めた。都市は初期の学問の中心となった。アヤソフィア教会はモスクに転用され、征服の伝統の初期の一例が示された。", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["イズミットの征服", "06a35035"], "d": ["イズミット（ニコメディア）の陥落により、ビザンツ帝国のアナトリア側における最後の重要な城塞もオスマン朝の支配下に入った。イスタンブルの対岸に至るまでのコジャエリ半島全域がオスマン領となった。こうして侯国はマルマラ海の南岸と東岸の全域を掌握し、ルメリアへの進出の基盤を整えた。", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["チンペ城塞 — ルメリアへの渡海", "c2f0a07d"], "d": ["オルハン・ガーズィーの子スレイマン・パシャは、ビザンツ帝国の内戦の中で与えられたチンペ城塞を1352年に拠点とした。1354年3月にゲリボルを破壊した大地震の後、空いた城塞が速やかに強化され、半島は恒久的なオスマン朝の橋頭堡となった。アナトリアから連れてこられたトルクメン人口の入植に支えられたこの一歩は、オスマン朝のヨーロッパ大陸における550年を超える存在の始まりである。", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["エディルネの征服", "2f54ebb0"], "d": ["トラキアの要衝エディルネ（アドリアノープル）の占領は、バルカン征服の主要な拠点と方向を決定した。征服の年代は史料で1361年から1369年の間で議論がある。都市は間もなく首都とされ、国家の重心がルメリアへ移ったことを示した。イスタンブル征服まで約90年間、都であり続けた。", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["ムラト1世の即位", "f8d48a26"], "d": ["オルハン・ガーズィーの死により即位したムラト1世（Hüdavendigâr）は、27年に及ぶ治世のうちに国家を辺境の侯国から帝国の骨格へと押し上げた。ペンチク制によりイェニチェリ軍団の基礎が築かれ、ティマール制が広められ、ルメリア・ベイレルベイリクが設けられ、宰相制度が強化された。バルカン征服は彼の時代に体系的な国家政策となった。", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["第1次コソヴォの戦い — ムラト1世の殉教", "10b8ddc9"], "d": ["クネズ・ラザル率いるバルカン同盟軍はコソヴォの野で決定的な敗北を喫し、セルビアはオスマン朝の宗主権下に入った。戦場を巡っていたムラト1世は、セルビアの貴族ミロシュ・オビリッチに短剣で刺されて殉教した。戦場で死んだ唯一のオスマン朝スルタンである。陣営でイルドゥルム・バヤジトが後継に据えられ、弟ヤクブ・チェレビは絞殺された。これは兄弟殺しの慣行の知られる最初の例の一つとなった。", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["ニコポリスの勝利", "75716e96"], "d": ["ハンガリー王ジギスムントの呼びかけで集結し、フランス・ブルゴーニュの騎士も加わった大十字軍は、ドナウ河畔のニコポリスでイルドゥルム・バヤジトに大敗した。この勝利はブルガリアに対するオスマン朝の支配を確定させ、ヨーロッパでは一世代の間、大規模な十字軍が組織されなかった。", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["アンカラの戦い — 空位時代の始まり", "b4a99d96"], "d": ["ティムールの軍に対しチュブク平原で喫した大敗でイルドゥルム・バヤジトは捕虜となり、数か月後に捕囚の身で没した。ティムールはアナトリアの諸侯国を復活させ、オスマン領はバヤジトの息子たちの間で分割され、11年続く王位争い（空位時代）が始まった。国家の成立以来最も深刻な危機であったこの時期は、中央集権的な体制の重要性をオスマン朝の記憶に刻んだ。同じ日に失われたその他の集落：Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia)。", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["チェレビ・メフメトによる統一の再建", "03413dfd"], "d": ["兄弟間の最後の決着でムーサー・チェレビをチャムルルで破ったメフメト1世は、国土を単一の統治の下に再統合した。そのため「国家の第二の創建者」とみなされる。治世において、傷んだ国家機構が修復され、アナトリアの諸侯国との関係が均衡され、ルメリアでは慎重な平和政策が取られた。", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["シェイフ・ベドレッディンの反乱", "e0a072ca"], "d": ["空位時代にカザスケル（軍司法官）を務めた大法学者・神秘主義者シェイフ・ベドレッディンの周囲に生じた宗教的・社会的運動は、カラブルンでのベルクリュジェ・ムスタファ、マニサでのトルラク・ケマルの蜂起と同時に勃発した。反乱は血なまぐさく鎮圧され、ベドレッディンはデリオルマンで捕らえられ、セレスで処刑された。この出来事は、オスマン史における最初期の大規模な社会的・マフディー主義的蜂起として、文学と歴史叙述に深い痕跡を残した。", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["ヴァルナの勝利", "f739eedc"], "d": ["セゲド条約を破って南下したハンガリー・ポーランドの十字軍は、退位していたが軍の指揮に戻ったムラト2世によってヴァルナで壊滅させられ、若き王ヴワディスワフ3世は戦場で死んだ。この勝利は、バルカンにおけるオスマン朝の存在を一掃しようとする最後の大規模な外部介入の機会を消し去り、イスタンブル征服への道を確実なものにした。", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["第2次コソヴォの戦い", "ebe0b662"], "d": ["ヴァルナの復讐を望んだフニャディ・ヤーノシュの軍は、三日間続いた激戦でムラト2世に決定的な敗北を喫した。これは十字軍がバルカンでオスマン朝に対して挑んだ最後の大規模な会戦である。この勝利により、ドナウ川以南のオスマン朝の支配は覆しがたく定着した。", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["コンスタンティノープルの征服", "583d5e3e"], "d": ["五十四日間（4月6日〜5月29日、1453年）に及んだ包囲の後、5月29日の朝に城壁を越えたオスマン軍が都市に入った。最後の皇帝コンスタンティノス11世は戦闘で死に、1100年続いた東ローマ帝国は歴史に消えた。若いスルタンは「ファーティフ（征服王）」の称号を得、都市を首都とし、アヤソフィアをモスクに転用した。都市は短期間のうちに入植と建設によって再び活気づいた。TDVによれば、シリヴリとヴィゼは1453年になって初めて決定的に征服された。TDVのリムノス項によれば、島は征服の直後にオスマン朝の統治下に入り、貢納を条件にガッティルージオ家に委ねられた。アトラスでは、シリヴリ、ヴィゼ、リムノスはこの日付でビザンツからオスマンへ（リムノスは貢納地として）記されている。巨大な大砲の鋳造、艦船の陸上輸送、城壁前の包囲配置は、当時の軍事工学の頂点とみなされる。この征服は、ヨーロッパの歴史叙述において中世の終わりを象徴する日付の一つに数えられる。", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["トレビゾンドの征服", "15f52403"], "d": ["ファーティフが陸軍と海軍で同時に進めた困難な黒海遠征の末に、トレビゾンド・ギリシア帝国は降伏した。アナトリアにおけるビザンツ世界の最後の残滓が一掃されたことで、黒海南岸は完全にオスマン朝の支配下に入った。コムネノス朝の終焉は、ファーティフの「二つの海と二つの陸の支配者」という主張を強めた。同じ日に加わったその他の地：Giresun, Rize。", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["シリフケの最終的征服 — カラマン朝最後の抵抗の粉砕", "d988bee4"], "d": ["シリフケ城は1472年に一度ゲディク・アフメト・パシャに降伏したが、同じ年にカラマンオウル・カスム・ベイが地中海の十字軍艦隊の支援で城を奪回していた。オトゥルクベリの勝利の後、ファーティフは息子とゲディク・アフメト・パシャにこの地域を最終的に掌握するよう命じた。旧オスマン砲兵の援助により火薬庫に火がつけられ、城は速やかに陥落した。こうしてカラマン朝のタシェリ＝イチェル山地における最後の抵抗は砕かれ、侯国の解体は1474年に完了することになった。", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["オトゥルクベリの戦い", "42c7194e"], "d": ["東方で大きな勢力となりヴェネツィアと同盟したアク・コユンルの君主ウズン・ハサンは、オトゥルクベリで、火器で装備したファーティフの軍に大敗した。この勝利はアナトリアにおけるオスマン朝の優位を確定させ、大砲と銃を用いる中央集権的な軍が在来の軍に対して優位であることの初期の証拠ともなった。TDVのギュミュシュハーネ項によれば、この都市は1467年以来アク・コユンルの支配下にあったが、この支配はオトゥルクベリの敗北で終わり、ギュミュシュハーネは決定的にオスマン朝の支配に移った。", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["クリミアのオスマン朝保護下への編入", "44e3f7c8"], "d": ["ゲディク・アフメト・パシャ指揮下の艦隊は、ジェノヴァ人の手にあったカッファをはじめとするクリミア南岸の諸都市を征服し、これらの沿岸は直接オスマン朝のサンジャクとされた。一方、クリミア・ハン国はメングリ・ギレイとともに、オスマン朝の宗主権を認める特権的な従属国となり、3世紀にわたり北方政策の要となった。黒海は事実上オスマン朝の内海となった。同じ日に加わったその他の地：Bahçesaray, Kerç, Azak。", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["ファーティフの死 — ジェム・スルタン事件", "190ecf01"], "d": ["ファーティフが遠征の途上で急死したため、バヤジト2世が即位した。弟のジェム・スルタンは王位を主張してブルサで自らの名でフトバを読ませ貨幣を鋳造させた。敗れると、まずマムルーク朝に、次いでロードス騎士団のもとに身を寄せた。騎士団と教皇庁の手の中でヨーロッパ外交の取引材料となったジェムは、1495年にナポリで死んだ。この事件は、オスマン朝の外交政策を十五年にわたり慎重な行動へと向かわせた。", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["チャルディランの勝利", "fea64ebb"], "d": ["アナトリアにおけるサファヴィー朝の宣伝が生んだ脅威を根本から解決しようとしたヤヴズ・スルタン・セリムは、シャー・イスマーイールの軍をチャルディラン平原で大砲と銃の優位によって大敗させた。タブリーズに入城し、東アナトリアと南東アナトリア、およびモスル＝ディヤルバクルの線がオスマン朝の統治に加わった。イドリース・ビトリースィーの尽力によるクルドの諸侯のオスマン朝への帰属は、数世紀続く東の国境の枠組みを築いた。", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["マルジュ・ダービクの勝利", "07d254d3"], "d": ["マムルーク軍はアレッポ北方のマルジュ・ダービクで数時間のうちに潰走させられ、年老いたスルタン、カンスー・ガウリーは戦闘中に死んだ。アレッポとダマスクスの門を大きく開いたこの勝利によって、シリア、レバノン、パレスチナはオスマン朝の統治下に入り、マムルーク国家の終焉をもたらすエジプト遠征への道が開かれた。", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["リダーニーヤ — エジプトの征服とカリフ位", "caf378d6"], "d": ["シナイ砂漠を急ぎ越えたオスマン軍は、リダーニーヤでトゥマーン・バイの防衛線を突破してカイロに入った。抵抗を続けたトゥマーン・バイは捕らえられて処刑され、マムルーク国家は歴史から消えた。エジプト、ヒジャーズ、聖地がオスマン朝の統治下に入り、アッバース朝のカリフと聖遺物はイスタンブルに運ばれた。カリフ位がオスマン朝の王家に移ったことで、スルタンたちはイスラーム世界の指導者としての主張を担い、香辛料の道の支配も帝国に大きな収入をもたらした。同じ日に加わったその他の地：Akkâ, Maan, Sayda, Kerak。", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["カーヌーニー・スレイマンの即位", "f6512269"], "d": ["ヤヴズの死により唯一の男子として即位したスレイマン1世の46年に及ぶ治世は、帝国の政治・軍事・法・文化の頂点とみなされる。慣習法を体系化したカーヌーン・ナーメにより「カーヌーニー（立法者）」の称号を得た。西欧では「壮麗王」（Magnificent）と呼ばれた。建築家シナンの作品、ディーワーン文学の黄金期、艦隊の地中海における優位は、この時代の象徴である。", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["ベオグラードの征服", "59ef5cec"], "d": ["ファーティフが1456年に奪えなかった、「中央ヨーロッパの鍵」とされるベオグラードは、カーヌーニーの最初の遠征でドナウ川とサヴァ川の合流点での包囲の末に陥落した。ハンガリーの南の防衛線は崩壊し、五年後のモハーチ、二十年後のブダ併合へと続く中央ヨーロッパ作戦の扉が、この征服で開かれた。", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["ロードスの征服", "807bbb1e"], "d": ["東地中海の海路と巡礼路を脅かしていた聖ヨハネ騎士団の拠点ロードスは、数か月に及ぶ血なまぐさい包囲の末、協定により降伏した。騎士団が島から自由に去ることが許された（のちにマルタに定着した）。アナトリア沿岸の安全が確保され、イスタンブルとエジプトを結ぶ海路は途切れなくオスマン朝の管理下に入った。", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["モハーチの戦い", "f3418b0d"], "d": ["ハンガリー軍は、モハーチ平原でおよそ二時間のうちに砲火と機動の優位によって壊滅させられた。国王ラヨシュ2世は逃走中に沼地で死んだ。オスマン史上最も短時間で勝ち取られた大会戦の一つであるモハーチは、独立したハンガリー王国を事実上終わらせ、中央ヨーロッパにおけるオスマン＝ハプスブルク対立の時代を開いた。", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["第1次ウィーン包囲", "dc49ea4f"], "d": ["ハプスブルク家がハンガリーの王位に手を伸ばしたことへの対抗として行われた遠征で、オスマン軍はウィーンを包囲した。重砲を途中に残したこと、早く訪れた冬、補給の困難のため、三週間後に包囲は解かれた。都市は陥落しなかったが、ハンガリーに対するオスマン朝の影響力は保たれた。ウィーン城下は、帝国の中央ヨーロッパにおける兵站上の到達限界を示した。", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["バグダードの征服 — 二つのイラク遠征", "897092c3"], "d": ["「二つのイラク」（アラブのイラクとアジャムのイラク）に向けた遠征で、まずタブリーズに、次いで戦わずしてバグダードに入った。アッバース朝の旧都の占領は、オスマン朝の君主にイスラーム世界で大きな威信をもたらした。イマーム・アーザム・アブー・ハニーファの廟が再興され、バグダードとバスラの編入によりオスマン領はペルシア湾に達した。同じ日に加わったその他の地：Kerkük, Kerbelâ。", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["プレヴェザ海戦の勝利", "30dc0f97"], "d": ["教皇の主導で組織された十字軍艦隊は、数で優っていたにもかかわらず、風と海岸を巧みに利用したバルバロスの戦術によりプレヴェザ沖で撃破された。アンドレア・ドーリアは戦場を放棄した。この勝利は、地中海でおよそ33年続く議論の余地のないオスマン朝の海上優位を確立した。トルコの海事の伝統における海軍記念日の象徴的な日付である。同じ日に加わったその他の地：Aden, Bender。", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["ブダの併合 — ハンガリーがオスマン朝の州となる", "db53b244"], "d": ["ハプスブルク家によるブダ包囲を受けて出征したカーヌーニーは、都市を解放した後、中部ハンガリーを直接オスマン朝の統治下に置いてブダ・ベイレルベイリクを設けた。トランシルヴァニアはオスマン朝に従属する自治公国とされた。ハンガリーのこの三分割の体制は約150年続き、オスマン朝の中央ヨーロッパにおける恒久的な統治の骨格をなした。", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["アマスヤ条約", "a5afe0d1"], "d": ["長年続いたオスマン＝サファヴィー戦争を終結させた最初の正式な和平条約である。バグダードとイラクはオスマン朝に残り、東アナトリアの国境が初めて相互に承認された。サファヴィー朝はオスマン領内でのシーア派の宣伝を止めることを、オスマン朝はイラン人巡礼者の通行の安全を保証することを引き受けた。この条約は、両国間の関係の法的な枠組みの最初の例となった。", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["シゲトヴァール — カーヌーニーの崩御", "e2917ed2"], "d": ["72歳のカーヌーニーは、十三回目の遠征で包囲していたシゲトヴァール城の陥落の数時間前に、天幕で崩御した。ソコッル・メフメト・パシャは軍が崩れないよう、死を数週間にわたり隠した。城は占領されたが、国家は最も長く在位し最も壮麗であったスルタンを失った。息子のセリム2世が即位し、国政における大宰相たちの比重が増し始めた。", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["キプロスの征服", "e364a2b3"], "d": ["ヴェネツィア統治下のキプロスに1570年に上陸が行われた。ニコシアは速やかに陥落し、マグサ（ファマグスタ）は十一か月の包囲の後、1571年8月になってようやく降伏した。東地中海の通商路と巡礼路の安全にとって重要なこの島は、ベイレルベイリクとして組織され、アナトリアから人口が入植させられた。この征服は、レパントに至る大十字軍同盟の理由にもなった。", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["レパント（İnebahtı）の敗北", "6a1d44a9"], "d": ["キプロス征服を受けて結集した十字軍艦隊は、オスマン艦隊をレパント湾で捕捉してその大部分を壊滅させた。海軍総督ミュエッズィンザーデ・アリ・パシャは戦死し、ウルチ・アリの艦隊だけが逃れた。惨事の後、大宰相ソコッル・メフメト・パシャはウルチ・アリ・パシャを海軍総督に任じて散り散りになった艦隊を集めさせ、イスタンブルからアランヤに至るすべての造船所で新たな艦隊の建造を始めさせた。しかし、地中海における絶対的な優位は心理的に揺らいだ。", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["ハチョヴァの戦い", "da308ec5"], "d": ["長期戦争（1593〜1606年）で最大の会戦において、メフメト3世が自ら率いた軍は、崩壊寸前の瞬間にホジャ・サーデッディン・エフェンディの進言で立て直し、ハプスブルク軍を敗走させた。オスマン朝が勝ち取った最後の大きな古典的会戦とみなされる。しかし、戦争の全体的な流れを変えなかったことは、軍事体制の疲弊の兆候ともみなされた。", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["ジトヴァトロク条約", "39c01142"], "d": ["十三年に及ぶ消耗戦を終結させた条約により、ハプスブルクの君主は初めて「ローマ皇帝」の称号でスルタンと対等とみなされ、年貢が廃止された。領土の喪失はないに等しかった。しかし外交上の言葉づかいのこの変化は、オスマン朝のヨーロッパに対する絶対的優位の主張の終わりの象徴として読まれる。", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["カスレ・シーリーン条約", "c1acf3af"], "d": ["ムラト4世によるバグダード奪回（1638年）の後に調印された条約は、百年を超えるオスマン＝サファヴィー戦争に終止符を打った。バグダードとイラクは決定的にオスマン朝に残り、エレヴァンはサファヴィー朝に譲られた。引かれた線は、小さな変更を伴いながら今日のトルコ＝イランの国境の基礎となり、世界で最も長続きした国境の一つとされる。条約はBedre, Cessân, Mendelî, Derteng, Derneをオスマン朝に譲った。国境のZencir城塞は破壊され、その西側の村はオスマン朝に、東側の村はイランに属すこととされた。シェフリゾル近郊のZalim城塞周辺とKızılca Kaleはオスマン朝に、AvromanとMihribanはイランに残った。Kotur, Mâkû, Mağazberd城塞は両側によって破壊されることとなった。", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["クレタ征服の完了", "e0d85604"], "d": ["1645年に始まったクレタ戦争の最終幕であるカンディア包囲は、ファーズル・アフメト・パシャの三年にわたる断固たる作戦によって決着した。ヴェネツィアの司令官モロジーニは、都市を協定により引き渡した。およそ四半世紀に及んだ闘争は、オスマン史上最長の包囲として記録された。東地中海における最後の大きなラテン人の城塞もオスマン朝の統治下に入った。島の北岸の三つの小さな岩の城塞、すなわちスダ、スピナロンガ、グランボウサは、まだヴェネツィアに残っていた。これらは別個の小島の上に築かれているため、地図上でクレタの残りの部分から分けて示すことはできない。", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["ブチャチ条約 — 最大版図", "b17b6e5a"], "d": ["ポーランド遠征でカームヤネツの征服の後に調印されたブチャチ条約により、ポドリアがオスマン朝に編入され、ウクライナの一部が保護下に置かれた。こうして帝国はヨーロッパにおける最大の版図に達した。この点は、拡張の時代の頂点であると同時に、その最後の環とみなされる。", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["第2次ウィーン包囲の潰走", "7d889252"], "d": ["メルズィフォンル・カラ・ムスタファ・パシャの二か月に及ぶウィーン包囲は、ポーランド王ヤン・ソビエスキがカーレンベルクの丘から繰り出した急襲によって潰走に終わった。軍は輜重を捨てて退き、メルズィフォンルはベオグラードで処刑された。勝利の後に結成された神聖同盟との戦争は16年続いた。この敗走は、オスマン史における大きな衰退の始まりの瞬間として示される。", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["グランボウサ城塞の征服 — クレタに残ったヴェネツィアの岩の城塞の一つ", "3ddf9eeb"], "d": ["1669年のカンディアの降伏によりクレタの征服は大筋で完了したとみなされるが、島の北西端の岩の島の城塞グランボウサは、さらに二十三年間ヴェネツィアの手に残った。1692年の占領により、クレタに残る三つのヴェネツィアの残滓のうち一つが一掃された。スダとスピナロンガは、1715年のモレア遠征を待つことになった。", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["カルロヴィッツ条約 — 最初の大規模な領土喪失", "8f7e2546"], "d": ["十六年に及ぶ神聖同盟戦争を終結させたカルロヴィッツ条約により、ハンガリーとトランシルヴァニアはオーストリアに、ポドリアはポーランドに、モレアとダルマチア沿岸はヴェネツィアに譲られた。オスマン史上初めて、この規模の領土が交渉の席で恒久的に失われた。この条約は、帝国がヨーロッパに対して守勢に回った新しい時代の始まりの文書とされ、オスマン外交史の転換点でもある。同じ日にアトラスで所属が変わった集落：Kostajnica と Jasenovac（オスマン朝からハプスブルクへ。条約文は Castanoviz を皇帝の手に残しており、Jasenovac の引き渡し日は史料になく、条約の日が記された）、および Preveze（ヴェネツィアからオスマン朝へ。TDV karlofca：ヒジュラ暦1110年ラジャブ月24日／1699年1月26日に調印された条項に従い、ヴェネツィアのレパント湾北方の占領地が返還された）。アトラスはさらに Kostayniçe (Kostajnica) と Jasenovaç をハプスブルク側に、右岸ウクライナの Uman と Vinnitsa をオスマン朝からポーランドへ（TDV merzifonlu-kara-mustafa-pasa；IEU Vinnytsia：1672〜99年トルコの支配）、そしてダルマチアの Nadin をヴェネツィアに記す（集落固有の引き渡し日は史料になく、条約の日が記された。Nadin の期間の端は史料で確認されていない — 申告付きの近似）。レパント湾北方の Vonitsa もヴェネツィアからオスマン朝に返還される（TDV karlofca）。ダルマチアの Vrana (Urana) はヴェネツィアに残った地の一つである（期間の端は確認されていない — 申告付き）。", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["プルートの勝利", "2583572f"], "d": ["ポルタヴァの敗北の後にオスマン朝に身を寄せたスウェーデン王の問題から起きた戦争で、ツァーリ・ピョートル1世の軍はプルート河畔で包囲され、降伏を余儀なくされた。結ばれた条約によりアゾフが取り戻された。軍が殲滅されなかったことと、ツァーリが解放されたことは、その日から今日まで議論される決定として歴史に残った。", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["スダ城塞とスピナロンガ城塞の征服 — クレタにおける最後のヴェネツィアの痕跡の消滅", "7261f7ba"], "d": ["グランボウサが1692年に陥落してから二十三年後、モレア遠征の一支隊によって、ヴェネツィアのクレタにおける最後の二つの拠点であるスダ城塞とスピナロンガ城塞も征服された。こうして1645年に始まったクレタの征服は、四十六年を経て、島の最後の一寸に至るまで完了した。", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["パトロナ・ハリルの反乱", "100941a4"], "d": ["イラン戦線での失敗、税、宮廷周辺の贅沢への怒りは、浴場の垢すり職人パトロナ・ハリルの指導のもとで大きな蜂起へと発展した。大宰相イブラヒム・パシャは殺され、アフメト3世は廃位され、チューリップ時代は終わった。反乱者たちが数か月にわたり都市を支配したことは、中央権力の脆弱さを際立たせた。", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["ベオグラード条約 — ベオグラード、スメデレヴォ、北セルビアの奪回", "ba7f8e46"], "d": ["オーストリアとロシアに対する二正面の戦争（1736〜1739年）の末、ベオグラードと北セルビアが取り戻された。ロシアはアゾフの武装解除と黒海に艦隊を置かないことを受け入れた。18世紀のオスマン外交と軍の最後の大きな成功とされるこの条約は、帝国に四半世紀の平和の時代をもたらした。同じ日にアトラスでオーストリアからオスマン朝に戻ったその他の集落：Hisarcık (Grocka)（ベオグラードの兄貴分中心地の連鎖；TDV belgrad）、Krayova (Craiova)、Rimnik (Râmnicu Vâlcea)、Turnu Severin（小ワラキアのオスマン朝への復帰、ワラキアの従属下へ）。サヴァ川沿いの Bosna Brod (Bosanski Brod) と Bosna Dubiçası (Bosanska Dubica) は、アトラスでは1739年9月28日にオスマン朝に戻る（TDV bosna-hersek；TDV mahmud-i--osmanli：1739年9月28日）。小ワラキアの Tırgu Jiu も同じ日にオスマン朝に戻る。", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["チェシュメ襲撃", "840b30bd"], "d": ["イギリスの支援を受けて地中海に出たロシア艦隊は、避難していたチェシュメ港のオスマン艦隊を火船で襲い、ほぼ完全に焼き払った。ロシアは初めて地中海で大きな海軍力として姿を現した。この惨事は、1774年のキュチュク・カイナルジャへと至る戦争の行方を決めた打撃の一つとなり、艦隊の根本的な改革の必要性を明らかにした。", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["キュチュク・カイナルジャ条約", "2776dcdb"], "d": ["1768〜1774年の戦争を終結させ、オスマン史上最も重い条約の一つとされるキュチュク・カイナルジャにより、クリミア・ハン国に「独立」が与えられた — 事実上ロシアの勢力圏が作られたことになる。ロシアは黒海沿岸に足場を築き、商船に海峡の通行権とイスタンブルへの常駐大使を得た。正教徒臣民に対する曖昧な保護条項は、次の世紀の介入の口実への扉を開いた。初めて、住民がムスリムである土地がオスマン朝の支配から切り離された。", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["クリミアのロシアへの併合", "bdf6faa8"], "d": ["キュチュク・カイナルジャが生み出した「独立」クリミアは、最後のハン、シャヒン・ギレイの時代の混乱を口実に、エカチェリーナ2世の宣言によりロシアに併合された。3世紀に及んだオスマン＝クリミアの提携は終わった。北方の草原の喪失はイスタンブルの防衛の縦深を失わせ、数万のクリミア・タタール人がオスマン領へ移住する最初の大きな波を引き起こした。この日、クリミア半島（Aluşta, Kefe, Sudak, Yalta, Balaklava, İnkirman, Mankup, Arabat）はロシアに編入され、Taman と Kuban も同じ併合でロシアに移った（TDV Kırım：1783年4月8日ユリウス暦＝4月19日グレゴリオ暦）。", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["セリム3世とニザーム・ジェディード", "d53aec21"], "d": ["戦争のさなかに即位したセリム3世は、敗北が構造的なものであることを見抜き、「ニザーム・ジェディード」（新秩序）の名で包括的な改革計画を始めた。ヨーロッパ式の訓練を受けた新軍、それを賄う別個の国庫（イラード・ジェディード）、工兵学校の強化、そしてヨーロッパの首都における最初の常駐大使館である。この計画は近代トルコの改革の伝統の始まりとみなされるが、軍団（イェニチェリ）とアーヤーンの抵抗により、1807年に潰えることになった。", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["マルタ騎士団の解体 — フランス艦隊の途上の寄港", "d62f901d"], "d": ["エジプトへ向かうフランス艦隊は途上のマルタに立ち寄り、聖ヨハネ（マルタ）騎士団はさしたる抵抗もなく島を明け渡した。1522年にロードスから追われてこの地に定着した騎士団の最後の拠点は、こうして終わった。マルタは二年後にイギリスの手に渡り、ナポレオンは島から直接アレクサンドリアへ向かうことになった。", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["ナポレオンのエジプト占領", "93fede5f"], "d": ["ボナパルト将軍の軍はアレクサンドリアに上陸してエジプトを占領した。イギリスのインドへの道を狙ったこの遠征は、ヨーロッパの一大国によるオスマン朝の中核領への最初の直接攻撃であった。ネルソンのアブキール襲撃とジェッザール・アフメト・パシャのアッカ防衛がフランスの進軍を砕いた。占領は1801年に終わったが、残された空白の中でカヴァラのメフメト・アリー・パシャの台頭と「東方問題」の時代が始まった。", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["同盟の誓約書（セネディ・イッティファーク）", "cce49ef5"], "d": ["マフムト2世を即位させたルスチュクのアーヤーン、アレムダル・ムスタファ・パシャの主導のもとで、宮廷と地方の有力アーヤーン家の間で調印された文書である。アーヤーンはスルタンへの忠誠と兵力の支援を約し、国家もまた彼らの存在と権利を認めた。スルタンの権威が文書によって制限された最初の例であるため、一部の歴史家によって立憲的な伝統の遠い始まりとみなされるが、事実上は数か月のうちに効力を失った。", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["ギリシア独立戦争の開始", "a7293715"], "d": ["フィリキ・エテリア組織が準備した蜂起は、まずワラキアで、次いで主力をもってモレアで勃発した。テペデレンリ・アリ・パシャの問題に手を取られていた国家は、初動の対応が遅れた。蜂起は、ヨーロッパの世論における強いギリシア贔屓（フィルヘレニズム）のおかげで、短期間のうちに国際的な問題へと発展した。民族主義の時代におけるオスマン領で最初の成功した独立運動の導火線は、このようにして点火された。同じ日に失われたその他の集落：Atina, Balyabadra (Patras), İstefe (Tebai), Livadya, Eleusis (Attika), Missolonghi。", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["モレアでの最初の武装蜂起", "77e6250f"], "d": ["プルートの渡河の後、蜂起はモレアに波及した。カラヴリタ（ユリウス暦3月21日）で始まった武装行動にパトラ、カラマタ、マニの運動が続き、モレアは短期間のうちに全面的な蜂起となり、オスマン朝の統治は半島の大部分を失った。同じ日に失われたその他の集落：Atina, Balyabadra (Patras), İstefe (Tebai), Livadya, Eleusis (Attika), Missolonghi。", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["ヴァカ・イ・ハイリイェ — イェニチェリ軍団の廃止", "08c9372a"], "d": ["新設のエシュキンジ軍団の訓練に反発して釜をひっくり返して反乱したイェニチェリは、マフムト2世があらかじめ整えていた忠実な部隊の砲火によって、エトメイダヌの兵営で壊滅させられた。軍団はすべての支部と関連するベクタシー教団のテッケとともに廃止された。「吉兆の出来事」を意味する名で歴史に残るこの作戦は、4世紀続いた制度を一掃することで、ムハンマド常勝軍の創設とその後のあらゆる中央集権化改革の道を開いた。", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["ナヴァリノ襲撃", "ee579e7f"], "d": ["ギリシアの蜂起を鎮圧していたオスマン＝エジプト艦隊は、宣戦布告なしに港に入った英仏露の連合艦隊によってナヴァリノで焼き払われた。六十隻近い艦船と数千人の船員が失われた。ヨーロッパ外交で「不幸な出来事」として片づけられた襲撃は、ギリシアの独立を事実上保証し、1828〜29年のオスマン＝ロシア戦争への道を開いた。", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["タンジマート勅令", "5042ce7b"], "d": ["ギュルハーネで読み上げられたハット・イ・ヒュマーユーンにより、宗教の区別なくすべての臣民の生命、財産、名誉の安全が国家の保障下に置かれた。課税における公正、兵役における秩序、裁判なしに刑を科さないことの原則が宣言された。ムスタファ・レシト・パシャの作であるこの勅令は、オスマン近代化の憲法的性格を持つ最初の大きな文書とみなされ、「タンジマート時代」（1839〜1876年）は改革の時代にその名を与えた。行政、法、教育、財政における根本的な再編がこの枠組みの中で進められた。", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["クリミア戦争の開始", "3b9ca3c8"], "d": ["聖地問題とロシアの正教徒臣民に対する保護の主張から始まった危機は、オスマン朝の宣戦布告により公然たる戦闘に発展した。シノプ襲撃の後、イギリスとフランス（のちにピエモンテ）がオスマン朝の側で参戦した。連合軍がクリミアに上陸してセヴァストポリを占領したことで、戦争は1856年のパリ条約によって勝利に終わった。しかし、戦争の年に受けた最初の対外債務（1854年）は、帝国を半世紀続く財政的従属の悪循環に陥れた。", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["改革勅令（イスラハート勅令）", "78ff234d"], "d": ["パリ講和会議の前に発布された勅令は、タンジマートの原則を拡張し、非ムスリム臣民に官吏への登用、兵役、学校設立を含む広い平等の権利を認めた。共同体の組織も再編された。続いて調印されたパリ条約により、オスマン国家は正式にヨーロッパの国際法の仲間に受け入れられ、その領土保全は列強の共同保証の下に置かれた。この保証は、実際には介入の新たな扉となった。", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["カーヌーン・エサースィー — 第一次立憲政", "0fe052c1"], "d": ["バルカン危機を協議するためイスタンブルで開かれた国際会議の開会日に、礼砲とともに最初のオスマン憲法が公布された。ミドハト・パシャを筆頭とする「新オスマン人」運動の作であるカーヌーン・エサースィーにより、二院制の議会が設けられた。議会（メクリス・イ・メブスーン）は1877年3月に開かれたが、アブデュルハミト2世は93年戦争を口実に1878年2月に議会を無期限に停会し、憲法は三十年間棚上げとなった。", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["93年戦争（1877〜78年のオスマン＝ロシア戦争）", "5bd96af7"], "d": ["ルーミー暦1293年にあたるため「93年戦争」と呼ばれる戦争で、ロシア軍は二方面から攻撃した。ガーズィー・オスマン・パシャのプレヴェン防衛とアフメト・ムフタル・パシャのカフカース戦線の戦いは叙事詩となったが、戦線は崩壊し、ロシア軍はイェシルキョイ（アヤステファノス）まで進んだ。戦争は、バルカンとカフカースからイスタンブルへ向かう、影響が今日にまで及ぶ大規模なムスリムの移住の波を引き起こした。帝国の人口構造と財政構造は二度と元には戻らなかった。", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["ベルリン条約", "47f76a49"], "d": ["アヤステファノスが生んだ「大ブルガリア」を列強の均衡の名の下に修正したベルリン会議は、それでも重い結果を残した。セルビア、モンテネグロ、ルーマニアが独立し、自治のブルガリア公国が設けられ、ボスニア・ヘルツェゴヴィナはオーストリアの占領に、キプロスはイギリスの統治に、カルス・アルダハン・バトゥミはロシアに委ねられた。ルメリアにおける五百年のオスマン朝の秩序は大きく解体され、「東方問題」はヨーロッパ外交の恒常的な議題となった。同じ日に失われたその他の集落：Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence。ルーマニアは、ベッサラビアをロシアに譲る代償としてトゥルチャ（Tulcea）とドブルジャを得た。北ドブルジャのトゥルチャ、Babadağı (Babadag)、Maçin、İshakçı (Isaccea)、Hırsova (Hârșova)、Mangalya (Mangalia) はルーマニアに移った。", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["チュニジアの占領とデュユーン・ウムーミイェ", "c7e25598"], "d": ["フランスはアルジェリア国境での事件を口実にチュニジアを占領し、バルドー条約によってその保護下に置いた。オスマン朝の北アフリカにおける存在はトリポリタニアにまで後退した。同年に出されたムハッレム勅令により、破産した対外債務の管理のために債権者が代表されるデュユーン・ウムーミイェ管理局が設立された。塩、煙草、絹などの基幹収入が直接この外国の機関に結びつけられ、財政主権は著しく制限された。同じ日に失われたその他の集落：Kayrevan, Gabes, Sfaks, Cerbe (Djerba)。", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["エジプトのイギリスによる占領", "f1269768"], "d": ["エジプトで財政破綻と外国の管理に抗して高まったウラービー・パシャの運動は、アレクサンドリアの砲撃の後に上陸したイギリス軍のテル・エル・ケビールの勝利で粉砕され、カイロは占領された。エジプトは法的にはオスマン朝に属し続けたが、事実上イギリスの統治下に入った。スエズ運河の管理は、ブリテン帝国の戦略の中心に据えられた。", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["第二次立憲政の宣言", "95ee2fd2"], "d": ["統一と進歩委員会に属する将校たちがマケドニアで山に入ったことで広がった運動を前に、アブデュルハミト2世はカーヌーン・エサースィーを再び施行した。「自由の宣言」は熱狂をもって迎えられ、選挙が行われた。しかし安定は訪れなかった。3月31日事件（1909年4月）が鎮圧された後、アブデュルハミトは廃位された。ブルガリアの独立、ボスニアの併合、クレタのギリシアへの志向も、この動揺の数か月の間に起きた。", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["トリポリタニア戦争（伊土戦争）", "ed441994"], "d": ["植民地を求めるイタリアは、オスマン朝の北アフリカにおける最後の領土トリポリタニアに宣戦し、沿岸を占領した。艦隊を持たない国家が正規軍を送れなかったため、ムスタファ・ケマルやエンヴェル・ベイのような若い将校たちが密かに現地に渡り、セヌーシー部族とともに効果的な抵抗を組織した。バルカン戦争の勃発を受けて調印されたウシー条約（1912年10月18日）によりリビアはイタリアに譲られた。イタリアはさらにロードスとドデカネス諸島を占領した。", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["ロンドン条約 — ルメリアの喪失", "f3f976df"], "d": ["第1次バルカン戦争を終結させたロンドン条約により、ミディエ＝エネス線の西側の全領土とエーゲ海の島々が失われ、アルバニアは独立した。五百年を超える間、帝国の人口・経済・文化の重心であったルメリアから残るのは東トラキアだけとなった（エディルネは第2次バルカン戦争で取り戻された）。この喪失は、統一派政権の戦争と入植の政策を根本的に硬化させた。ミディエ＝エネス線の西側に残った次の地が失われた：Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştine, Peç (Pejë), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje)；Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo)；クレタではHanya, Kandiye, Girit (Resmo), Sitiye (Sitia), İsfakiye (Sfakia)。", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["第一次世界大戦への参戦", "05a0252e"], "d": ["イギリスから逃れてきた戦艦ゲーベンとブレスラウを購入したと見せかけて海峡に入れたことが、国家を一歩ずつドイツの側に引き寄せた。スーション提督指揮下の艦隊がロシアの港を砲撃したこと（10月29日）で戦争は事実上始まり、相互の宣戦布告は11月初めに行われた。ジハード・エクベル（大ジハード）の宣言にもかかわらず期待された効果は生じなかった。帝国は四年間にわたり、カフカースからパレスチナまで五つの戦線で存亡をかけた戦争に入った。", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["チャナッカレの勝利", "95d888e8"], "d": ["イスタンブルを陥落させてロシアに到達することを目指した連合軍の大艦隊は、3月18日に機雷線と砲台の砲火によって海峡から撃退された。ヌスレト機雷敷設艦が敷いた線が戦いの行方を決めた。4月に始まったゲリボル半島上陸作戦も、アナファルタラルとコンクバユルで食い止められ、連合軍は1916年1月に半島から完全に撤退した。中佐ムスタファ・ケマルの名はこの戦線で知られるようになった。約二十五万の戦死者・損失をもって勝ち取られた勝利は、民族闘争の人材と精神が生まれた場所とみなされる。", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["シャリーフ・フサインの反乱", "75f7c58c"], "d": ["メッカの太守シャリーフ・フサインは、イギリスと行った秘密の書簡交換の後、独立したアラブ王国の約束を得て蜂起した。ヒジャーズ鉄道は襲撃の標的となった。休戦の後まで続いたファフレッディン・パシャのメディナ防衛は、抵抗の象徴として語り継がれたが、反乱はパレスチナ戦線におけるイギリス軍の進撃と結びついて、アラブ諸州におけるオスマン朝の支配の解体を加速させた。同じ日に失われたその他の集落：Tâif。", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["ムドロス休戦協定", "9e87c767"], "d": ["ブルガリアの崩壊により諸戦線が互いに分断されたオスマン国家は、戦艦アガメムノン号上で調印された休戦協定によって戦争から撤退した。海峡の開放と、特に安全が脅かされた地の占領を可能にする第7条は、短期間のうちに事実上の分割の法的な口実とされた。モスル、イスケンデルン、続いてイズミルとイスタンブルが占領された。休戦協定は、帝国の事実上の終焉の文書とみなされる。同じ日に失われたその他の集落：Hama, Şam, Humus。", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["ムスタファ・ケマルのサムスン上陸 — 民族闘争", "09a8f784"], "d": ["イズミル占領が生んだ憤激の中、第9軍監察官の資格でサムスンに上陸したムスタファ・ケマル・パシャは、公式の任務をアナトリアの抵抗の組織化へと転じた。アマスヤ通達とエルズルム会議、シヴァス会議はこの出立の続きである。「民族の独立は、ただ民族の決意と決断によって救われる」という原則は、民族闘争の政治綱領の核となった。", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["トルコ大国民議会の開会とセーヴル", "2008feec"], "d": ["イスタンブルの公式な占領とメクリス・イ・メブスーンの解散を受けて、1920年4月23日にアンカラで大国民議会が開かれた。非常の権限を自らに集めた議会は、国民の意思に基づく新国家の核となった。8月にイスタンブル政府が調印したセーヴル条約はアナトリアを分割するものであった。大国民議会は条約に署名した者たちを祖国への裏切り者と宣言し、セーヴルは一度も実施されなかった。", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["サカリヤの戦い", "f2f970a6"], "d": ["アンカラまで50キロメートルに迫ったギリシア軍の攻勢は、総司令官の権限を担ったムスタファ・ケマル・パシャの「防衛線はない、防衛面がある」との命令のもと、22日22夜にわたる戦闘で挫かれた。ギリシア軍は初めて戦略的防御に転じた。勝利はムスタファ・ケマルにガーズィーの称号と元帥の位をもたらし、フランスとのアンカラ協定と対外的承認への扉を開いた。", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["大攻勢とイズミルの解放", "172a50c4"], "d": ["8月26日の朝にコジャテペから開始された攻勢は、8月30日にドゥムルプナルで総司令官会戦によってギリシア軍主力の殲滅に達した。「諸軍よ、諸君の第一の目標は地中海である、前進せよ」の命令で続いた追撃により、9月9日にイズミルが解放された。ムダニヤ休戦協定（10月11日）により東トラキアは戦わずして取り戻された。軍事的勝利は、ローザンヌで築かれる新国家の交渉の場での力を決定づけた。", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["スルタン制の廃止", "9f36a9f6"], "d": ["ローザンヌ会議にイスタンブル政府も招かれたことを受け、大国民議会は1922年11月1日にスルタン制とカリフ制を分離してスルタン制を廃止した。623年続いたオスマン朝の王朝支配は法的に終わった。メフメト6世ヴァヒデッディンは11月17日にイギリスの戦艦で国を去った。カリフ位には大国民議会の決定によりアブデュルメジト・エフェンディが就けられ、この地位も1924年3月3日に廃止されることになった。", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["ローザンヌ条約", "38c27f7d"], "d": ["八か月に及ぶ困難な交渉の末に調印されたローザンヌ講和条約により、新トルコ国家の国境、完全な独立と主権が国際的に承認された。カピチュレーションは廃止され、デュユーン・ウムーミイェは清算の手続きに入り、住民交換が定められた。セーヴルを事実上無効としたローザンヌは、民族闘争の外交的勝利であり、共和国の創設的な対外文書とみなされる。", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["共和国の宣言", "d5bfcdfb"], "d": ["大国民議会が憲法の改正により「トルコ国家の政体は共和制である」との規定を採択したことで共和国が宣言され、ムスタファ・ケマル・パシャが初代大統領に選ばれた。1299年に辺境の侯国として始まった624年のオスマンの歩みはこうして閉じ、主権が無条件に国民に属する新国家が、帝国の遺産の上に築かれた。", "f5cabb8c"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["サヌーシー教団の砂漠の中心Cağbûbのオスマン体制への編入——アブデュルメジトの免税勅令", "039fce6d"], "d": ["長年メッカに滞在したムハンマド・ブン・アリー・サヌーシーは、トリポリタニアに戻った後、エジプト国境のCağbûbオアシスに居を定め、見晴らしのよい岩場に大きなザーウィヤを建てさせた。数軒の小屋にすぎなかった地は、短期間で都市に変わった。1856年、スルタン・アブデュルメジトの勅令により、教団員に属する財産は課税を免除され、信徒からザカートを集める権限が与えられた。この勅令は、西アフリカとスーダンをカイロに結ぶ隊商路上のオアシスを、オスマンの財政・行政制度の一部とし、Cağbûbを交易の中心として強化した。地域の人々のカリフへの忠誠は、1884年と1893年にここを訪れた大佐Sâdık el-Müeyyedの旅行記によっても裏づけられる。", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["スエズ運河の掘削開始とポートサイドの建設", "cef0be8d"], "d": ["Bâbıâliが1856年1月5日に承認したレセップスの計画の掘削作業は、1859年4月25日に始まった。運河は10年後の1869年11月16日に完成することになる。掘削の地中海側の端で、メンザラ湖と海の間の海岸砂州に労働者のために設けられた5軒の小屋の村が、ポートサイドの核となった。市には、運河会社の関係者により、当時のエジプト総督サイード・パシャに捧げて、1860年に「サイードの港」を意味するこの名が与えられた。こうしてオスマンの地図上に、それまで集落がまったくなかった海岸の細長い土地に新しい港が生まれた。", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["スルタン・アブデュルアズィズのエジプト訪問とスエズ地峡におけるイスマイリアの建設", "bcfacf38"], "d": ["スルタン・アブデュルアズィズは、大宰相Yûsuf Kâmil Paşaの勧めにより1863年4月3日にエジプトに赴き、盛大な歓迎を受けた。目的は、カヴァラのメフメト・アリー・パシャの反乱以来、事実上別個の国家の状態になりつつあった州の、中央への帰属を強めることにあった。同年、地峡のティムサーフ湖畔のTilâlülcisr丘陵に運河会社の管理拠点が設けられた。まず技術者のためにKaryetüttimsah、次いで労働者のためにKaryetülarab村が置かれた。副王イスマーイール・パシャが淡水運河に強い関心を寄せ、この丘に自らの別荘を建てさせたことから、集落は彼の名にちなんでイスマイリアと呼ばれるようになった。市の創設は1863年とされ、正確な日は不明である。", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Midhat Paşaのバグダード総督在任と部族の定住化——ラマーディーとナーシリーヤの建設", "0fa98f06"], "d": ["Şûrâ-yı Devlet議長の職から外され、イスタンブルから遠ざけられたMidhat Paşaは、モスルとバスラをも含むバグダード州を、1869-1872年のあいだ、第六軍司令官の職を兼ねる広範な権限をもって統治した。彼は土地法令と新しい州法をここで適用し、土地を地券(tapu)により分配し、遊牧部族を定住生活と国家の権威に結びつけた。この定住化政策の産物として、1869年にユーフラテス川のほとりにDülaym部族のためにラマーディーが、南部ではMüntefik県知事Nâsır Paşa es-Sa'dûnの手によってナーシリーヤが建設された。いずれもそれまで集落のなかった地点に生まれ、地図にはこの日付で初めて登場した。", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["アンカラの敗北の後、ワラキア公ミルチャがドブルジャを再び奪う——シリストラ、コンスタンツァ、バーバダグ、イサクチャ", "5eaefc68"], "d": ["ユルドゥルム・バヤジトがアンカラでティムールに敗れたことは、ドナウ沿いのオスマンの支配を揺るがした。ワラキア公ミルチャはこの空白を利用してドブルジャに再び入った。シリストラ、コンスタンツァ、バーバダグ周辺、ドナウ岸のイサクチャは、空位時代(フェトレト)の年月を通じて彼の手に残った。ミルチャはチェレビ・メフメトに対してムーサー・チェレビを支持した。シリストラを1418年の死まで保った。", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["バーバダグとその周辺のオスマンへの移行——ミルチャと息子ミハイルが敗れる", "bfda2c60"], "d": ["チェレビ・メフメトは、ワラキア公ミルチャと息子ミハイルを破った後、北ドブルジャのバーバダグとその周辺をオスマンの支配下に置いた。バーバダグは、サルトゥク・ババの名を冠し、13世紀のトルクメンの入植で築かれた町であった。周辺のシリストラ、コンスタンツァ、その他のドブルジャの要塞は1419年までワラキアに残った。つまりバーバダグは3年間、オスマン領から切り離された飛び地として現れる。", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["シリストラとドブルジャの奪回——ミルチャの死の後", "73eb6ae9"], "d": ["ワラキア公ミルチャが1418年に没した後のワラキアの混乱は、チェレビ・スルタン・メフメトにシリストラとドブルジャを取り戻す機会を与えた。1419年の春にシリストラ、コンスタンツァ、ドブルジャの大部分が再びオスマンの統治下に入った。エニサラ(Yenisale)とイサクチャの要塞は修復されて国境要塞(serhat)とされ、ドブルジャはその後1878年までオスマンに残った。", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["下ドナウの閉鎖——イェルギョギュ、トゥルヌ、オルショヴァの併合", "331a0b68"], "d": ["空位時代が終わった後、チェレビ・メフメトのドナウ線を整える動きは、1420年に実を結んだ。ワラキア公Koca Mirceaが自領の上に、費用を塩の販売で賄って築かせたイェルギョギュ(ジュルジュ)要塞は、この年オスマンの手に渡った(ドブルジャは1年前の1419年春に奪回されていた——TDV `silistre`)。ドナウ右岸のトゥルヌ(Kule/Holovnik)とオルショヴァ——のちの名でフェトヒュルイスラーム——が併合された。こうして川の両岸が同時に管理下に置かれた。イェルギョギュの重要性はその地理にある。ドナウの左、つまりワラキア側に築かれたオスマンの要塞であり、対岸のルセと同じ渡河点の両端を押さえる。オスマンの文書はこの二重性をはっきり記す——ルセについては「イェルギョギュの手前の岸」、ジュルジュについては「イェルギョギュの向こう岸」と言う。要塞は1427年にワラキア人に奪い返され、1449年に再びオスマンの管理下に入り、イェルギョギュのカザーはニグボル・サンジャクに属して、公領内で直接統治される飛び地となった。地図でワラキアのドナウ沿いがなぜ濃い色なのかの答えは、ここから始まる。", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["トプリツァ地方(Kurşunlu、Ürküp)がオスマンの支配下に入る", "e22e690d"], "d": ["ムラト2世がマラ・ブランコヴィチと婚約した際に、ドゥボチツァとトプリツァの地方(Leskofça、Kurşunlu、Ürküp周辺)がオスマンの支配に移った可能性が高いとみられる。1445-1447年の検地台帳は、地方がオスマンのスィパーヒーにティマールとして与えられたことを示している。地図ではKurşunluとÜrküpはこの年からオスマンの統治下にある。", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["サライ平野の編入——ボスニア内部のオスマンの先端の確立", "be5c0f00"], "d": ["ボスニア王が1428-1429年に貢納に結ばれた後、オスマンは王国の内部に向けて恒久的に居を定め始めた。1428-1435年のあいだにホディジェド(Hodidjed)の町が奪われた。ヒジュラ暦852年(1448年)にホディジェドのヴィライェトがサライ平野とともに完全にオスマンの統治下に入った。これは、ボスニア征服の15年前に王国の中央に築かれた辺境地であり、ヴォイヴォダの称号をもつスコピエのベイ、イーサー・ベイにより統治された——周囲にはなおオスマンに従属するボスニアの貴族がいたため、地方は二重の管理下にあった。市そのものもこの時期に生まれた。1462年以前にイスハーク・ベイあるいはその子イーサー・ベイが最初のムスリム街区を築き、862年(1458年)にファーティヒの名でHünkâr Camiiが建てられ、Brodec村の耕地が整備されてサライの町が現れた。1463年の征服はボスニア王国を消滅させた。サライ平野はその時点で既に15年間オスマンの領土であった。", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["ポドゴリツァのオスマン領への編入——ゼタ平野の掌握", "46e401c5"], "d": ["シュコドラ湖の20キロ北、モラチャ川とリブニツァ川が合流する平野に築かれた町は、史料に初めて1216年にリブニツァ、1326年にポドゴリツァの名で現れる。1457年にオスマン領に編入され、ゼタ平野の管理はこうしてバルシッチ-ツルノイェヴィチ両王朝の手を離れた。ファーティヒ・スルタン・メフメトは1474-1478年のあいだに、二つの川の合流点にある険しい岩場に要塞とモスクを建てさせた。1479年のシュコドラの征服後、地方は新設のシュコドラ・サンジャクに属した。1485年の検地台帳で40戸のキリスト教徒の町であったポドゴリツァは、1529-30年に800人と、要塞内で城主の下にある32人の守備隊に、1582年に322戸に達した。エヴリヤ・チェレビは1662年にファーティヒ要塞に300軒の家、倉庫、武器庫、700人の守備兵を数えた。これらの記録はゼタの平野と山地の違いも示している。平野は数えられ、課税され、守備隊のいるオスマンのカザーである——だが18世紀には、市はモンテネグロの山地の部族の襲撃を防ぐため、6つの堡塁と3つの門を持つ城壁で要塞化せざるを得なくなる。ポドゴリツァは1876-1878年の戦争の終わり頃にモンテネグロの手に渡り、ベルリン条約でそこに留まった。", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["フォチャの奪取——ヘルツェゴヴィナ公領への最初の入口の開放", "f098a9e6"], "d": ["ボスニア王国が1463年に消滅した後、次の番は、王国から分かれて自らの公領を築いたステパン・ヴクチッチ・コサチャの土地に回ってきた。ドリナ渓谷で、イスタンブルをドゥブロヴニクに結ぶ交易路の結節点にあったフォチャは、1465年にオスマンの統治下に入った。市の重要性はすぐに理解された。1470年に新設されたヘルツェゴヴィナ・サンジャクの中心とされた——つまりヘルツェゴヴィナの行政の核は、公領そのものがまだ滅びないうちにフォチャに築かれた。公領全体の併合は1483年まで続くことになる。フォチャはその後、好適な気候と道の結節点という位置のおかげで、商業と行政の中心として発展した。地図上でこの日付は、ボスニアの征服後に南への第二の波が始まった日である。", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["リヴノと西ボスニアの最終的な併合——ヴェネツィアとの国境の確立", "c14d4283"], "d": ["リヴノ平野を見下ろす台地上の要塞は、1448-1454年にヘルツェゴヴィナ公領の創設者ステパン・ヴクチッチ・コサチャの手にあった。1463年のボスニア遠征で短期間オスマン軍に占領されたが、同年に奪い返された。1466年に市の支配者はイヴァニシュ・ヴラトコヴィチである。TDVの表現では、最終的なオスマンの支配はおそらく1468-1469年に実現し、1485年の検地台帳はリヴノをもはやオスマン領として記録している。これは、ボスニア征服の西端が閉じたことである。リヴノは、平らな平野に沿って36キロしか離れていないヴェネツィア領に接する危険な国境の町となり、この位置を、1521-1522年にボスニア総督Gazi Hüsrev Beyがヴェネツィアの要塞を奪うまで保った。", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Böğürdelenのハンガリーへの喪失——サヴァ線の最初の綻び", "129fe8f2"], "d": ["ファーティヒ・スルタン・メフメトの時代にオスマンの手に渡り、以前はザスロンの名で知られていた地点に、1471年に木と土の砦が築かれていた。ベオグラードを脅かす地点にあり、ここからハンガリーとオーストリアの南部に容易に襲撃できたため、要塞は名もこの機能に由来していた——Böğürdelenは「側面から打つ砦」を意味する。ハンガリー王マーチャーシュ・コルヴィヌスは1475年の終わり頃に要塞を包囲し、1476年2月に奪った。包囲を語るハンガリーの叙事詩『Szabács viadala』は、15世紀のハンガリー歴史詩のうち現存する最長の例の一つである。ハンガリー人は地方にバンの領を設け、要塞を石で再び要塞化して、国境の砦の鎖の一環とした。オスマンは1492年に取り戻そうと試みて成功しなかった。要塞は45年間ハンガリーの手に残った。", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["イオニア諸島の征服——トッコ公領の終わり:アヤマヴラ、ケファロニア、ザキントス、イタキ", "07b27251"], "d": ["同年1月にヴェネツィアと調印されたイスタンブル条約は、シュコドラとアルバニア沿岸をオスマンに残した。しかしイオニア諸島はヴェネツィアではなく、ケファロニア・ザキントス伯領を保持していたトッコ家の統治下にあり、別個の作戦で奪われた。TDVのAyamavra項によれば、最後の公Leonardo Toccoは、まずファーティヒの親族ミリツァ・ブランコヴィチと結婚して忠誠を保ち、1464年に妻が死ぬと、1477年にナポリ王家のフランチェスカ・マルツァーノと結婚してスルタンの不興を買った。2年後、アヴロニア(ヴロラ)のベイGedik Ahmed Paşaが指揮する艦隊はアヤマヴラを南のケファロニアとともに奪取し、レオナルドとフランチェスカはイタリアに逃れた。Gedik Ahmed Paşa項は同じ作戦でザキントス(ザンテ)も奪われたと記す。ケファロニア伯領に属するイタキもこの時期にオスマンの統治下に入った。こうしてアドリア海の入口からモレアに至る海路は完全に管理下に置かれた。島々のうちザキントスは3年後にヴェネツィアに譲られ、ケファロニアとイタキは1500年に失われ、アヤマヴラだけが200年間オスマンに残ることになる。", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["ツルノイェヴィチのゼタの臣従とツェティニェの中心化", "59d20267"], "d": ["シュコドラが1479年にオスマンに残ったことで、その後背地であるゼタの山岳地帯も帝国の境界内に入った。地域を保持していたツルノイェヴィチ家は、ファーティヒの死後に即位したバヤジト2世の統治を認めて貢納に結ばれ、内政では自由を保った。イヴァン・ツルノイェヴィチは中心を平野から引き上げ、ロヴチェン山の麓のツェティニェに移して町を築いた。2年後にここに建てさせた修道院は地域の宗教の中心となった。こうしてモンテネグロは、地図上では直接のオスマン領としてではなく、淡い色の臣従地域として現れる。TDVのKaradağ項は王朝とツェティニェの主教区に触れ、支配が1514年にスカンデル・ベイ(ツルノイェヴィチの血筋で、オスマンの宮廷で育った)の手により別個のサンジャクに変わったと記す。1482年はTDVには出てこず、モンテネグロの歴史叙述が与える日付である。地理の厳しさのために、ここでの統治は平野のように厳密に働くことはなかった。", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["キリヤ要塞の征服——ドナウ河口の鍵", "ef4eca73"], "d": ["モルダヴィアは1455年9月から毎年2000金を貢納する臣従のヴォイヴォダ領であったが、黒海に開く二つの港はなおヴォイヴォダの手にあり、ドナウからの交易はそこを通っていた。バヤジト2世は治世最初の大遠征をこの二つの港に向けた。10日間、昼夜を問わず砲撃されたキリヤ要塞の司令官は降伏せざるを得なかった。要塞は直接オスマンの統治下に置かれてサンジャク・ベイ領とされ、16世紀後半にはコサックの脅威のためにカザーとされてルメリア・ベイレルベイ領に属するアッケルマン(アクケルマン)・サンジャクに編入された。ここからモルダヴィアは地図上で二段階に現れる。内陸のヴォイヴォダ領は淡い色の臣従地として残り、沿岸の二つの港は濃い色の直接のオスマン・サンジャクである。TDVのBoğdan項はこの二つを「モルダヴィアの鍵と門」と呼び、地域がバヤジト2世の時代に最終的にオスマンに結ばれたと記す。", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["アッケルマン(アクケルマン)の征服——ドニエストル河口とモルダヴィアの黒海への門の閉鎖", "7cb20feb"], "d": ["キリヤの降伏から20日後、軍はドニエストル河口のアッケルマンの前に至り、要塞は8月4日に奪取された。市はモルダヴィアで最も活発な港であった。ファーティヒの時代、ヴォイヴォダのペトル3世が1455年にオスマンの支配を認めたときに、アッケルマンの商人に交易の許可が与えられていたが、今や港は直接国家のものとなった。征服後にルメリア・ベイレルベイ領に属するサンジャクとされたアッケルマンは、1593年に新設のオジュ州に併合された。こうして、モルダヴィアの北からホティン、南からキリヤとアッケルマンに囲まれた外殻は、オスマンの直接の管理下に入り始めた。ヴォイヴォダ領は内政では自由を保ったが、海への出口を失った。地図上に間の空白地帯はない——濃い色の港のサンジャクと淡い色のヴォイヴォダ領の土地が互いに接する。その間のブジャク草原は1538年まで依然としてヴォイヴォダ領の一部である。", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["レパントの降伏——コリントス湾の入口がヴェネツィアから奪われる", "2cfe0777"], "d": ["レパント(İnebahtı)は1407年からヴェネツィアの手にあり、コリントス湾の入口を押さえていた。湾内の沿岸のすべてがこの要塞の射程に結びついていた。1499年の遠征で要塞は陸から包囲され、レパント沖でヴェネツィア艦隊と交戦したオスマン艦隊は、海から包囲部隊を助けた。要塞のヴェネツィア人たちは8月26日に町をオスマンに引き渡した。市はその後188年オスマンに残り、1687年のモレアの喪失で再びヴェネツィアに移り、1715年に奪回された。同じ夏の海戦とこの降伏は二つの別個の出来事である。艦隊の戦闘はモレアの西端、サピエンツァ-ゾンキオの海域で起こり、レパントはコリントス湾の入口で陸上包囲により陥落した。", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["スレブレニク・バナト領の併合——北ボスニアにおけるハンガリー線の最初の崩れ", "6d98c725"], "d": ["ボスニア王国が1463年に滅んだ後、マーチャーシュ・コルヴィヌスは反攻に転じ、王国の北にオスマンの進出を止める二つのバナト領を設けていた。西のヤイツェと北東のスレブレニクである。これらはハンガリーのボスニアにおける前進防衛線であり、サヴァ川とボスニアの間の回廊を塞いでいた。スレブレニク・バナト領は1512年に奪われた。こうして線の東翼が崩れ、イズヴォルニク・サンジャクは北に向けて拡大できるようになった。西翼のヤイツェはさらに16年持ちこたえるが、モハーチの後の1528年にようやく奪われることになる。", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Böğürdelenの征服——スレイマン1世が奪った最初の要塞、ベオグラード決定が下された地", "85177a90"], "d": ["スレイマン1世の第一次ハンガリー遠征で地方に派遣されたルメリア・ベイレルベイAhmed Paşaの部隊は、激しい包囲の後、要塞を1521年7月7日に奪った。Böğürdelenは、スレイマン1世の治世に征服された最初の要塞である。スルタンは征服の後に自ら要塞に入り、町の整備を命じた。ベオグラードの征服に関する決定もここで下された——つまり1521年8月29日に陥落するベオグラードの計画は、Böğürdelenで立てられた。要塞はその後200年近くオスマンの手にあった。最初はルメリア、1580年からボスニア州に、次いで短期間セメンドレ(スメデレヴォ)に、最終的にイズヴォルニク・サンジャクに属した。地図上でこの日付は、サヴァ線がオスマンに有利に閉じた日である。", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["三公国の蜂起が始まる——トランシルヴァニアが神聖同盟に移り、親オスマンの貴族が逮捕される", "68a33800"], "d": ["長期戦争の2年目に、オスマンの中欧における従属国の帯は一挙に解けた。教皇クレメンス8世の庇護のもとに結成された神聖同盟に、夏の終わりにモルダヴィアとトランシルヴァニアが移った。モルダヴィア公アロン・ヴォダは1594年8月16日にキリスト教側に加わったことを文書で公式化し、トランシルヴァニア公ジグモンド・バートリも1594年8月28日に戦争に反対する親オスマンの貴族を粛清して国内の反対派を砕いた。ワラキア公ミハイ勇敢公は同年の秋に同盟に加わった。こうしてオスマンのドナウ以北の三つの従属公国——150年にわたり貢納を納め、公がイスタンブルに承認されてきた三公国——は、同じ秋に一挙に敵側に移った。決定は1595年1月28日にプラハで調印された条約で正式化された。これは、オスマンのバルカン北部における間接統治体制が受けた最も重い動揺であった。蜂起は鎮圧されるが、三公国の忠誠は1526-1593年のような堅固さには二度と戻らなかった。", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["ブカレストの蜂起とドナウ要塞への攻撃", "18971100"], "d": ["神聖同盟の決定は1か月後に血をもって実行された。ミハイ勇敢公はブカレストでオスマンの守備隊と市内のレヴァント人債権者を剣にかけた。蜂起は同じ冬にドナウ線に広がった。ワラキア軍はイェルギョギュ(ジュルジュ)、イブライル、ヒルショヴァ、シリストラを攻撃し、モルダヴィア側ではアロン・ヴォダがベンデルのオスマン守備隊に同様の襲撃を行った。襲われた場所の選択は偶然ではない。それらはいずれも公領の土地ではなく、ドナウ沿いで直接オスマンの統治下にある要塞とカザーであった。イェルギョギュのカザーはニグボル・サンジャクに、イブライルは1538年から直接国家に、ベンデルも1538年からブジャク・サンジャクに属していた。つまり反乱は、従属する内部地域ではなく、その地域を取り囲む直接のオスマンの殻に打撃を与えた。この殻に穴を開けなければ、トランシルヴァニア-ワラキア-モルダヴィアの三角地帯をハプスブルクの戦線に結びつけることはできなかった。", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["カルゲレニの戦い——Koca Sinan Paşaのワラキア遠征", "201210a1"], "d": ["三公国が一挙に失われたことを受けて、大宰相Koca Sinan Paşaは大軍でドナウを渡り、ワラキアを再び服従させるために進軍した。ミハイ勇敢公は野戦では抵抗できないと知っていたので、軍をネアイロヴ川の湿地の渡河点であるカルゲレニで待ち受け、狭い地形に押し込められた部隊に奇襲を加えた。奇襲の後、数に勝るオスマン軍に対抗できず北の山地に退いた。Sinan Paşaはブカレストとトゥルゴヴィシュテを占領し、ワラキアを直接統治に結びつけようとした。このためカルゲレニはオスマンにとって敗北ではなく、遠征の完遂を遅らせた奇襲であった。しかしミハイが軍を保つことができたことは、数週間後にトランシルヴァニアからの援助で反攻に転じることを可能にした。", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["ワラキアからの撤退とイェルギョギュの奇襲——鎮圧遠征の不成功", "118806e1"], "d": ["トランシルヴァニア公の軍と合流したミハイ勇敢公の反攻により、Sinan Paşaはトゥルゴヴィシュテとブカレストを放棄してドナウに退いた。撤退の最も高くついた瞬間は渡河点で訪れた。1595年10月、ワラキアから戻る軍を追ったアクンジュ(軽騎兵)は、イェルギョギュでミハイの奇襲を受けた。遠征はこうして、ワラキアを直接統治に結びつけるという目標に達せぬまま終わり、公領は事実上失われたままとなった。この三角地帯におけるオスマンの権威は、何年もかけて少しずつしか修復されなかった。トランシルヴァニアの服従への復帰は1604年のボチカイ蜂起を待つことになり、戦線の完全な収束は1606年のジトヴァトロク条約を待つことになる。", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["ホティンのモルダヴィアからの切り離し——公領の中央にある直接のオスマン・サンジャク", "947517cb"], "d": ["プルト遠征でモルダヴィア公ディミトリエ・カンテミルがロシア側に移ったことは、公領の北の国境をもはや公に委ねておけないことを示した。そこでホティンは1711年以後にモルダヴィアから取られ、直接のオスマン統治に入れられた。まずナーヒエ、次にサンジャクの地位が与えられた。1713年の一時的なロシアの占領の後、要塞はイスタンブルから派遣されたオスマンとフランスの技術者団の監督のもとで再び修復・拡張され、ドナウ以北で最も強固なオスマンの要塞となった。地図でこの日付以後、ホティンが従属公領の色から出て直接のオスマンの色に戻り、従属するモルダヴィアの真ん中に飛び地のように立っていることは、この行政上の分離に対応するものであり、作図の誤りではない。同じ構造はブジャクで1538年から、キリヤとアッケルマンで1484年から既にあった。公領は内政で自由であり、国境の要塞は国家のものである。", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Böğürdelenの2度目のオーストリア占領——サヴァ戦線の開放", "063b3ad0"], "d": ["オーストリアが1788年2月9日にロシア側について参戦した後、サヴァ線は再び戦線となり、Böğürdelenは1788年4月24日にオーストリアの支配に移った。要塞は以前、1717年8月17日に戦わずしてオーストリアに放棄され、ベオグラード条約(1739年)まで保持されていた。その時期には人口がきわめて減り、市にはキリスト教徒の家が34軒残るのみで、ムスリムは一人もいなかった。1739-1788年のオスマン期に人口は再び1500-2000人に増えていた。2度目の占領は、ズィシュトヴィ条約(1791年8月4日)で終わり、要塞はオスマンに返還されることになる。", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Böğürdelenのカラジョルジェへの引き渡し——第一次セルビア蜂起で最初の要塞", "5c913eb4"], "d": ["1804年にベオグラードのダイ(Dayı)とヤマクの圧迫への反発として始まり、のちに民族主義的な性格を帯びた最初のセルビア革命の間、Böğürdelen要塞は1806年1月26日にカラジョルジェに引き渡された。サヴァ川沿いのこの要塞は、反乱者が奪った最初の大きなオスマンの要塞であり、ベオグラードの陥落を予告する。蜂起は1813年に鎮圧されてベオグラードが奪い返されると、要塞もオスマンの統治に戻った。しかし1830年の勅令の守備隊条項により、Böğürdelenは、ベオグラード、セメンドレ、フェトヒュルイスラームとともに、自治セルビアの内部にオスマン兵が残る4つの要塞の一つと定められ、1867年に守備隊が撤収するまでこの地位にあった。", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["イズディン(ラミア)がギリシア領内に残る——アルタ-ヴォロス線", "930f63b8"], "d": ["独立ギリシア国家の北の国境は1832年に、アルタ湾からヴォロス湾に延びる線に引かれた。オスマン期(1424-1832年)にエーリボズ(エヴィア)サンジャクに属するカザーの中心であったイズディンは、この線の南に残ったためギリシアに移った。テッサリアの残り(Yenişehir、Tırhala)は1881年までオスマンに残った。", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["ロシアの宣戦布告——93年戦争(露土戦争)の開始", "ac548ab8"], "d": ["1876年のブルガリア蜂起の鎮圧はヨーロッパの世論に大きな憤激を呼び、ロシアはBâbıâliを孤立させるためこれを徹底的に利用した。イスタンブル(造船所)会議のブルガリアを二つの自治州に分割する提案、続いて1877年3月31日付のロンドン議定書がオスマン帝国に拒否されると、ロシアは1877年4月24日に宣戦布告し、軍は自陣営に引き込んだルーマニア公国の領土に入った(地図は、ワラキア-モルダヴィアをこの時点からエディルネ休戦までロシアの進軍の斜線の覆いで示す)。ルーミー暦の1293年にあたるため、この戦争は93年戦争の名で知られる。作戦はドナウと東アナトリアの二つの戦線で進められた。ドナウでは18万人のオスマン軍が川の左岸を第一防衛線、バルカン山脈を第二防衛線としていた。東では、Ahmed Muhtar Paşaの5万5000人の兵がアルダハン-ドゥバヤジト間に陣取っていた。この戦争は地図上でオスマンのルメリアの崩壊を始めた出来事である——ブルガリア、セルビア、モンテネグロ、ルーマニアの今日の国境はすべてこの15か月の産物である。", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["ルーマニアの独立宣言——ワラキア-モルダヴィアの従属の終わり", "bdd164b3"], "d": ["93年戦争の宣戦布告から2週間後、ルーマニア公国は独立を宣言し、ロシアの側に立って参戦した。プレヴェン包囲におけるその役割はオスマンの敗北において決定的となった。400年を超えるワラキアとモルダヴィアの従属はこうして事実上終わり、独立はベルリン会議(1878年)で国際的承認を得た。地図はこの日付以後、ルーマニアを従属ではなく独自の色の独立国として示す。独立宣言により、ワラキアとモルダヴィアの全域(ヤシ、ガラツィ、イブライル、イェルギョギュ、カラファト、ボトシャニなど)が独立ルーマニアとなった。", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["ロシア軍のドナウ渡河——ズィシュトヴィとタルノヴォの陥落", "811367b1"], "d": ["戦争の開始とともにルーマニアの領土に入り、この公国を自陣営に引き込んだロシア軍は、一つはドブルジャ、もう一つはブカレストの方向の二つの縦隊で進んだ。ドナウはルセ(Rusçuk)とニグボルの間で渡られ、6月27日にズィシュトヴィ、7月1日に旧ブルガリア首都のタルノヴォが奪われた。撤退が命じられていたにもかかわらずこの点に注意が払われなかったため、ニグボルもしばらく抵抗した後に降伏した。第一防衛線が1週間で破られたことはイスタンブルに大きなパニックを引き起こした。スルタンの都をブルサに移すという噂まで流れ、戦争の指導は首都に設けられた軍事評議会に委ねられた。", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["シプカ峠の撤収——バルカン線の突破", "1f45e50a"], "d": ["バルカン山脈を越える峠の中で最も戦略的なシプカのオスマン軍はロシアの攻撃に激しく抵抗した。しかし敗北は避けられないと判断して、7月19日に峠を密かに撤収した。こうして第二防衛線も開かれ、グールコ将軍は7月22日にエスキ・ザーラ(スタラ・ザゴラ)を奪った。モンテネグロ方面から到着したSüleyman Paşaはグールコを破ってバルカン山脈の南の占領された地を取り戻したが、8月21日から数か月に及ぶ攻勢にもかかわらずシプカを奪い返せなかった。地図上でこれは、バルカン山脈の北と南の間の防衛の一体性が二度と築けなかったことである。ドナウ戦線での戦いはその後、プレヴェンに絞られていく。", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["ロヴェチがロシア軍に占領される", "70e54611"], "d": ["93年戦争でロヴェチは1877年6月5日にロシア人に占領され、Rifat Paşa指揮のオスマン軍が6月15日にロシア軍を撃退していた。市は8月23日にオスマンに放棄されて再びロシアの占領下に入った。地図はロヴェチを、この日からベルリン条約までロシアの占領下(斜線)として示す。法的にはオスマン領であり続ける。", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["カルスの陥落——東部戦線の崩壊とアズィーズィイェ堡塁", "53fc3bf5"], "d": ["東アナトリアでカルス、ドゥバヤジト、アルダハンに向けて三つの縦隊で進んだロシア軍は、4月30日にドゥバヤジトを奪い、アルダハンに入ったが、エルズルムに向かう途中の7月15日に敗れて国境外に追い出された。Ahmed Muhtar Paşaに「ガーズィー」の称号をもたらしたこの成功は、8月にラザレフ将軍が再び攻勢に転じたことで逆転し、11月18日にカルスは陥落した。より有利な防衛のためにエルズルムに退いたオスマン軍は、アズィーズィイェ堡塁で、Nene Hatunが住民を鼓舞したこともあって大きな抵抗を示した。カルス、アルダハン、バトゥミは8か月後にベルリンで、戦争賠償金の一部と引き換えにロシアに譲られることになる。", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["第一次バルカン戦争の開始——モンテネグロの宣戦布告", "c0c2697e"], "d": ["バルカン諸国は、統一と進歩委員会が1911年7月3日付の法律で教会問題を解決したことで、互いの間の最大の障害を取り除き、ロシアの扇動によって1912年を通じて互いに同盟条約を結んでいた(3月13日にセルビア-ブルガリア、5月29日にブルガリア-ギリシア、8月にモンテネグロ-ブルガリア、10月6日にモンテネグロ-セルビア)。Bâbıâliはこれに気づかず、それどころかロシアの保証を信じてルメリアの120個の訓練大隊を除隊させた。四つの国は10月3日に共同の覚書を出してマケドニア、アルバニア、クレタの自治を求め、返答を得られないまま、10月8日のモンテネグロの宣戦布告で作戦が始まった。10月13日にセルビアとブルガリアの大使にパスポートが渡され、翌日にこの二国が、続いてギリシアが宣戦した。戦争中、軍内部の政治的見解の相違が敗北に大きな役割を果たした。", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["ロドピ山脈でクルジャリ支隊が崩壊、クルジャリが陥落", "8cf59b7f"], "d": ["ブルガリアの宣戦布告の後、ロドピ山脈から下ったブルガリア軍は、Mehmed Yaver Paşaのクルジャリ支隊を破ってクルジャリに入った。敗れた支隊はギュミュルジネ(コモティニ)の方向に退いた。ロドピの東部は戦争の最初の週に失われた。", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["東軍の敗走とチャタルジャ線への後退——クマノヴォとテッサロニキの喪失", "cf95591a"], "d": ["オスマンの東軍は1912年10月23日に、自軍の3倍の兵力のブルガリア軍に敗れ、イスタンブルの30キロ西のチャタルジャ線まで後退した。首都は戦争の最初の月に直接の脅威にさらされた。同じ頃、西軍は10月23日から24日にクマノヴォでセルビア軍に敗れ、Tahsin Paşaは3万5000人の軍とともにテッサロニキでギリシア軍に降伏した。これらの敗北により、10月29日にGazi Ahmed Muhtar Paşa内閣は総辞職した。テッサロニキで流刑生活を送っていたアブデュルハミト2世は、11月1日にイスタンブルへ移された。チャタルジャ線は戦争の終わりまで保持された——ルメリアの500年にわたるオスマンの地理は、数週間のうちにこの狭い帯に縮んだ。", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["ノヴィ・パザル・サンジャクの中心にアレクサンダル王子が入る", "326d0616"], "d": ["セルビア軍は戦争の最初の週にノヴィ・パザル(Yenipazar)を奪い、西から来たモンテネグロ軍と合流した。100年間セルビアとモンテネグロを隔てていたノヴィ・パザル・サンジャクは、こうして両同盟国をつなぐ橋となった。", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["キルクキリセの戦いの後、クルクラレリが失われる", "eda4c759"], "d": ["東トラキアで東軍がキルクキリセの戦いに敗れたことを受け、Kölemen Abdullah Paşaが守っていた市はブルガリア軍に委ねられた。市は9か月に及んだ占領から、第二次バルカン戦争の1913年7月21日にようやく解放された。", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["コソヴォ州の中心スコピエが無抵抗で明け渡される", "455d9b71"], "d": ["クマノヴォの敗北(10月23日から24日)の後、コソヴォ州の中心スコピエは無防備になった。住民が市の周辺での戦闘を望まなかったため、領事たちを通じて招かれたアレクサンダル王子指揮のセルビア軍は、10月26日の夕方に無抵抗で市に入った。", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["ヴァルダル川沿いのキョプリュリュ(ヴェレス)が失われる", "73d20b7d"], "d": ["スコピエの陥落から2日後、ヴァルダル川沿いに南下したセルビア軍はキョプリュリュを奪った。テッサロニキに開くヴァルダル渓谷の門は、こうしてセルビア軍の手に渡った。", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["ブレガルニツァ盆地:ステファノヴィチ将軍がイシュティプに入る", "70a84256"], "d": ["ステファノヴィチ将軍指揮のセルビア軍は、抵抗に遭わずにイシュティプ(シュティプ)を奪った。市にはまず不正規の武装集団が入った。クマノヴォの後、東マケドニアのブレガルニツァ盆地はセルビアの管理下に移った。", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["サランタポロ峠の後、カラフェリエ(ヴェリア)がギリシアの支配に移る", "02a68e02"], "d": ["テッサリアから北進したギリシア軍は、サランタポロ(Kırkgeçit)峠を越えた後、カラフェリエを掌握した。市のムスリム住民の一部はこのときに地方を離れた。", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["テッサロニキ-マナスティル鉄道上のヴォディナ(エデッサ)が失われる", "fc15b917"], "d": ["テッサロニキ-マナスティル(ビトラ)鉄道上のヴォディナがギリシア軍の手に渡った。スラヴ人とトルコ人の人口が強制的に引き離されたことで、市の人口は短期間のうちに深刻に減少した。", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["イェニジェの戦い——イェニジェ・イ・ヴァルダルのギリシアへの移行", "8f6cb76e"], "d": ["Hasan Tahsin Paşaの第8混成軍団は、テッサロニキの西のイェニジェ(ギャニツァ)でギリシア軍に敗れ、テッサロニキ地区に退いた。戦闘中に町の大部分が焼けた。テッサロニキへの道はギリシア軍に開かれた。", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["コソヴォ南西のプリズレンが降伏", "bae6b1b9"], "d": ["コソヴォの南西にあるプリズレンはセルビア軍に降伏した。市に入った部隊のムスリム住民に対する態度は、戦争のコソヴォにおける最も重い頁の一つとして記録された。", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["ミトフ大佐がウストルムジャで戒厳令を宣言", "bcad75cc"], "d": ["ブルガリアのミトフ大佐はウストルムジャ(Ustrumca)に入って戒厳令を宣言し、翌日出発する際に町をブルガリアの郡長とセルビアの指揮官に委ねた。ウストルムジャは戦争を通じて同盟国のあいだで手を移り、1913年にブルガリアに編入された。", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Paşaがテッサロニキをギリシアに明け渡す", "1738933c"], "d": ["イェニジェの敗北の後テッサロニキに退いたHasan Tahsin Paşaは、ブルガリア軍が北から近づくなかで市をギリシアに明け渡した。ギリシア軍は11月8日の正午ごろ市に入った。オスマンのルメリアで最大の港湾都市であり、統一と進歩委員会が生まれたテッサロニキは、こうして失われた。", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["西トラキアの中心ギュミュルジネがブルガリアに開かれる", "96eec25f"], "d": ["クルジャリから退いたYaver Paşa支隊がフェレ(フェレス)方面に後退したことで、ギュミュルジネはブルガリア軍に降伏した。西トラキアの中心は、戦争の終わりにブルガリアに譲られる土地の筆頭にあった。", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["エルバサンに達したセルビア軍、同日ディブラに入る", "16720246"], "d": ["マナスティルから西へ進んだセルビア軍は、エルバサンに達した日にディブラ(Debre)にも入り、アドリア海に向けて下った。同じ日、ヴロラ(アヴロニア)でアルバニアの独立が宣言されていた。", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["ティムール、バグダードを2度目に占領——市のアッバース朝以来の街区が破壊される", "04b68a24"], "d": ["ティムールはバグダードを8年を隔てて2度奪った。1393年の最初の占領では市はあまり被害を受けなかった。1401年の2度目は、バグダードの文化生活に加えられた2度目の重い打撃とされる——住民は剣にかけられ、アッバース朝期から残る街区と建物の大半が破壊された。ジャライル朝の君主アフマドは1405年に市に戻り、壊れた城壁と市場を修復しようとしたが、時間がなかった。バグダードは1410年にカラ・コユンルのトルクメンの手に渡った。この二度の占領は、アンカラの戦いへの道で、ティムールがオスマンとマムルークの国境にどれほど近づいていたかを示す最も具体的な歩みの一つである。", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Cüneyd Bey、アイドゥン地方の首領に返り咲く——アイドゥン朝が再び独立", "63281658"], "d": ["チェレビ・メフメトは1414-15年にイズミルを奪い、Cüneyd Beyをニグボル・サンジャク・ベイに派遣して、アイドゥン地方をオスマンの統治に結びつけていた。Cüneydは、チェレビ・メフメトの死の後、ビザンツが王位請求者として擁立したムスタファ・チェレビのもとで再び表舞台に出て、彼のために宰相職まで務めた。ムラト2世は、旧侯国を返すという約束で彼をこの同盟から引き離した。Cüneydはイズミルに戻ってアヤスルク(エフェソス)を奪い、アイドゥン朝のムスタファ・ベイを殺して侯国の首領となった。こうしてアイドゥン地方は、偽ムスタファの危機のなかから、オスマンの統治を離れたかたちで生まれた。", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Cüneyd Beyとその家族の処刑——アイドゥン侯国の終わり", "efa684ba"], "d": ["アイドゥン地方を再び掌握したCüneyd Beyがアナトリアの諸侯をそそのかし、ヴェネツィアと接触を求めたことを受け、ムラト2世はアナトリア・ベイレルベイのHamza Beyを彼に差し向けた。息子Kurd Hasanがアクヒサル近郊で敗れて捕虜となると、サモス島の対岸のİpsiliに退いたCüneydは、カラマン朝から期待した援助が来ず、オスマンとともに動いたジェノヴァ人たちに海から封鎖されたため、降伏せざるを得なくなった。一族とともに排除された。アイドゥン朝の領土はこうして完全にオスマンの統治下に入った。", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["エルズルムとヴァン盆地がサファヴィー朝に移る——アク・コユンルの北翼が崩れる", "b418875f"], "d": ["シャルール(Şerûr)でアルワンド・ベイを破り、1501年夏にタブリーズに入ったシャー・イスマーイールは、翌年北西に向けて進み、エルズルムからヴァン湖盆地に延びる線を支配下に置いた。アク・コユンル朝は、ウズン・ハサンの死の後、すでに王位争いで二つに割れていた。アルワンド・ベイがアゼルバイジャンとディヤルバクルを、従兄弟のムラードがイラク・アジャミーとファールスを握っていた。この分裂はサファヴィー朝の進出を容易にした。地方は10件の記録として1年のうちに手を移った。エルズルムはその後16年サファヴィー朝の手にあり、オスマンの支配には、チャルディランの後の1518-19年にようやく入った。この年(1502年)に、アシュカレ(Aşkale)とパシンレル(Hasankale)が、エルズルム地方とともにアク・コユンルからサファヴィー朝に移った(日付は未確認)。", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["ムラード・ベイのハマダーンでの敗北:イラク・アジャミーとファールスがサファヴィー朝に移る", "8de07a31"], "d": ["アク・コユンルの王位の第二の請求者スルタン・ムラードは、シャー・イスマーイールに対するハマダーン近郊の戦いで大敗を喫し、バグダードに逃れた。この一度の戦いで、イラク・アジャミー、ファールス、ケルマーンの諸地方はサファヴィー朝の統治下に入った。地図上でこれらの地方は同時に手を移る。アク・コユンル朝の崩壊における最大の一歩である——タブリーズの喪失が王朝を首都なしにし、ハマダーンの敗北は領土なしにした。", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["シャー・イスマーイール、ヤズドに入る:アク・コユンルの残党の中央イランにおける最後の拠点が陥落", "6f9835df"], "d": ["1503年のハマダーンの敗北の後、イラク・アジャミーとファールスがサファヴィー朝に移ったにもかかわらず、ヤズドはアク・コユンル王家のバインドゥル朝のムラード・ベイの手に、別個に残っていた。市は1か月の包囲で陥落し、中央イランにおける最後のアク・コユンルの島が閉じた。TDVの記録:「シャー・イスマーイールは、ヒジュラ暦910年ジュマーダー・アーヒラ月28日(1504年12月6日)に、1か月の包囲の後に市に入った。」", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["シャー・イスマーイールのディヤルバクル遠征:アク・コユンルの最後の中心地が陥落", "b6d8504e"], "d": ["アゼルバイジャンとイラン高原を手にしたシャー・イスマーイールは、1507年に西へ、アク・コユンル王家が生まれたディヤルバクル地方に向かった。アーミド(ディヤルバクル)からマルディン、ウルファからハルプトに延びる線が二度の攻勢でサファヴィー朝の統治に入り、アク・コユンルは事実上消滅した。この遠征はまた、サファヴィー朝の国境を初めてオスマンとマムルークの国境に接させた。チャルディランへの緊張の地理的な基盤はこうして築かれた。", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["バグダードのサファヴィー朝への移行——イラク・アラビーが手を移る", "39730186"], "d": ["ハマダーンの敗北の後にバグダードに逃れたアク・コユンルのスルタン・ムラードを追って、シャー・イスマーイールは1508年にイラク・アラビーに入り、バグダードを奪った。カルバラーとナジャフの廟がサファヴィー朝の統治に移ったことは、運動の宗派的主張の観点からタブリーズの奪取に劣らず重要であった。地図上でイラク・アラビーは同日に手を移る。これは、解体の最後で最も広い地理的な歩みである。バグダードは、1534年にスレイマン1世のイラクエイン遠征まで、サファヴィー朝の手に残った。", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["メルヴの戦い:ウズベクが大敗、メルヴとヘラートが奪われる", "f8e45aaf"], "d": ["西でアク・コユンルの遺産を完成させたシャー・イスマーイールは東のホラーサーンへ進み、メルヴの前でウズベクを大敗させた。シャイバーニー・ハンは戦場で死んだ。メルヴとヘラートはサファヴィーの支配下に入り、サファヴィー朝はユーフラテスからアムダリヤに至る国境を手にした。こうして1501年夏のタブリーズ入城に始まった過程は9年で完成した。アク・コユンルの遺産は完全にサファヴィーの統治に移り、オスマン帝国は東に、自らと同じ大きさの第二の国家と隣り合うことになった。", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["ザビードの最終的なオスマンの支配への編入", "ddd971c7"], "d": ["1538年11月5日にディウ包囲を解いた艦隊は、帰路でイエメンの沿岸に立ち寄り、ザビードは最終的にオスマンの統治に結ばれた。Hadım Süleyman Paşaは市を1539年3月10日に離れ、4月1日にジッダに着いた。市は1517年から旧マムルークの諸侯の手で、オスマンの名のもとに統治されていた。この日付で直接統治に移った。", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["イベリア連合:ポルトガルの王冠がスペイン王に移る", "1cc6dfdc"], "d": ["枢機卿王エンリケが後継者を残さず死んだことで開いた継承争いは、アルカンタラの戦い(1580年8月25日)でスペインに有利に決着した。トマールで開かれたポルトガルのコルテスは、1581年4月16日にフェリペ2世をポルトガル王と認めた。トマールの条件によれば、ポルトガルは自らの制度、貨幣、言語を保ち、統治には本国のポルトガル人のみが任命され、マドリードに別個のポルトガル評議会が置かれることになった——つまり合邦は人的な連合であり、併合ではなかった。", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["レスタウラサン:ポルトガルが独立を取り戻す", "64ec0738"], "d": ["カタルーニャの反乱がスペインを忙殺していたころ、リスボンで一団の貴族が宮殿を急襲してスペインの統治を倒し、ブラガンサ公をジョアン4世の名で国王と宣言した。60年にわたるイベリア連合はこうして終わった。ただしセウタはスペインに残ることを選び、これは1668年のリスボン条約で認められた。ポルトガルがハプスブルクの戦争に組み込まれたこの時期は、アジアにおけるその喪失の枠組みでもある。ホルムズは1622年に、マラッカは1641年に、コロンボは1656年に失われた。タンジールとボンベイは独立の代価としてイギリスに与えられた。出典:ブリタニカ、ポルトガルの歴史——復古。", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["タンジールがイギリスに譲渡される", "1f7cad6d"], "d": ["ポルトガルの独立戦争におけるイギリスの支援を確保するために結ばれた婚姻条約(1661年6月23日)の第2条は、タンジールをカタリナ・デ・ブラガンサの持参金としてイギリスに譲っていた。サンドウィッチ伯の艦隊は1662年1月29日に投錨し、翌日ピーターバラ伯の儀式により正式な譲渡が行われた。イギリス人は1684年に市を放棄することになる。", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["ナーディル・シャーの殺害——アフシャール朝の支配の解体", "19c218c0"], "d": ["サファヴィー朝の王座を終わらせ、1736年に自らの名で即位し、インド遠征でデリーまで進み、オスマンと3度戦って1746年のケルデン条約で和平を結んだナーディル・シャーは、自らの親衛兵により天幕で殺された。その後、イランは単独の手で統治できなくなった。ホラーサーンのアフシャール朝の残党、南のザンド朝、北に台頭するカージャール朝が、49年間にわたり国を分け合った。オスマンの東の国境は、この分散のおかげで長く平穏であった。ナーディル・シャーは1747年6月20日に殺された。TDVによれば、エレヴァン・ハン国は同年(1747年)に建てられた(日は未確認)。", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["カージャール朝のイラン支配", "744b48c5"], "d": ["カージャール部族の長アーガー・ムハンマド・ハンは、ザンド朝の支配を倒し、ホラーサーンにおける最後のアフシャール朝の抵抗をも砕いて、イランを再び一手に集め、テヘランを首都とした。49年にわたる分裂の時代はこうして閉じた。その後オスマンの東の隣国は1923年までカージャール朝のイランとなる。TDV『イスラーム百科事典』によれば、マシュハドは1796年にアーガー・ムハンマド・シャーの前でアフシャール朝の君主シャールフに迎えられ、カージャール朝の支配に入った(日は史料にない)。", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["フェルディナンドがブダを奪取——サポヤイが首都から追われる", "99f77c29"], "d": ["モハーチの後、ハンガリーの王位には二人の王が立っていた。貴族の一部はヤーノシュ・サポヤイを、一部はハプスブルクのフェルディナントを選んだ。フェルディナントは1527年にブダを奪ってサポヤイを首都から追い、サポヤイはスルタン・スレイマンに援助を求めた。これが、1529年のウィーン遠征の最初の目標がブダであった理由である。", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["バルバロスのエーゲ海諸島遠征——ナクソス公国がオスマンの管理下に入る", "722b2fea"], "d": ["1207年からヴェネツィアの後見のもとにラテン人の公により治められていたナクソス公国は、Barbaros Hayreddin Paşaの島々への遠征によりオスマンの管理下に入った。島の地位には手がつけられなかった。公国はオスマンに従属するかたちで続き、1540年のオスマン-ヴェネツィア条約により、支配権は正式にオスマンに移された。", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["十字軍艦隊がジェルバ島を占領——Turgut Paşaの基地が失われる", "f41b3f2a"], "d": ["スペイン、教皇庁、マルタ、ジェノヴァ、フィレンツェの艦船からなる十字軍艦隊は、Turgut Reisが1551年から襲撃基地として用いていたジェルバ島を標的とした。嵐と疫病のため島の前にたどり着けたのは1560年の初めになってからで、1560年3月12日に島を占領して要塞を築いた。知らせを受けたPiyâle Paşaは3月28日に120隻のガレー船の艦隊でイスタンブルを出発した。占領は長く続かなかった。オスマン艦隊は5月にジェルバの前で同盟軍を破り、要塞も7月末に奪い返された。この遠征は、プレヴェザの後に地中海におけるオスマンの優位を固めた第二の大きな海上作戦の始まりである。", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["ジェルバ要塞の陥落——島のオスマン統治への移行", "f1efc0df"], "d": ["Piyâle Paşaの1560年5月14日の海戦での勝利の後、十字軍の部隊は島に築いた要塞に立てこもった。トリポリのベイレルベイTurgut Paşaの部隊が陸から包囲した。2か月に及んだ包囲は、1560年7月30日の要塞の陥落で終わり、島はトリポリ・ベイレルベイ領に属した。海上での勝利と要塞の征服の間には77日がある。島は5月14日ではなく7月30日に実際に手を移った。", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["ダンツィヒにおける露・プロイセンの二重権力が終わる——ナポレオンの自由市がプロイセンに戻る", "1ccda4d2"], "d": ["ティルジット和約(1807年7月9日)でプロイセンから切り離されフランスの保護下の自由市とされたダンツィヒを、ナポレオンの軍は1813年の包囲の後に放棄した。1814年1月2日から2月4日まで市では露・プロイセンの二重権力が続いた。ツァーリ・アレクサンドルがダンツィヒとヴィスワ河口を取る計画を放棄したことで、市はプロイセンの統治に移った。", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["ウィーンでクラクフが自由・独立・中立の都市と宣言される", "19eea839"], "d": ["ウィーン会議でロシア、オーストリア、プロイセンは、クラクフ市をその周辺とともに三国の保護下の自由国とした。ウィーン最終議定書がこの体制を確認した。", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["クラクフ自由市が廃止され、オーストリアに編入", "15548a14"], "d": ["1846年2月のクラクフ蜂起を口実としたロシア、オーストリア、プロイセンは、ウィーンの会議で自由市を廃止してオーストリア領に編入することを決めた。イギリスとフランスの異議は実を結ばなかった。", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["ボルヌがラービフ・ブン・ズバイルの支配下に入る", "8be4ca96"], "d": ["バギルミとワダイを揺るがしたスーダン出身の軍閥ラービフ・ブン・ズバイルはボルヌを奪った。1896年までに国のすべてを奪い、ディケオを中心とした。", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["ラービフ・ブン・ズバイルがフランス軍に敗れて死亡——ボルヌにおける支配の解体", "fb5a3ace"], "d": ["フランスの植民地軍に敗れたラービフは殺された。息子は支配を続けようとしたが維持できず、ボルヌは1902年にフランス、イギリス、ドイツの間で分割された。", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["ギュミュルジネを中心とする西トラキア臨時政府が宣言される", "974b2e28"], "d": ["ブカレスト条約(1913年8月10日)が西トラキアをブルガリアに譲ると、地方のトルコ人住民はギュミュルジネを中心とする臨時政府を宣言した。デデアーチの奪取の後、政府は独立を「西トラキア独立政府」の名で発表した。列強の介入によりオスマン政府はこれを支持しなかった。1913年9月29日のイスタンブル条約は西トラキアをブルガリアに譲り、政府は1913年10月25日まで57日しか生きなかった。", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["ダンツィヒ自由市が国際連盟の保護下に設立", "bd148fe8"], "d": ["ヴェルサイユ条約でドイツから切り離されたダンツィヒは、1920年1月10日から連合国の大国の暫定統治下にあった。1920年11月15日に国際連盟の保護のもと、ポーランドとの関税同盟内の自由市として設立された。", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["オルハン・ガーズィーの死——侯国から国家への40年の終わり", "62c59cfd"], "d": ["1324年のオスマン・ガーズィーの死により侯国の首領となったオルハン・ガーズィーは、38年の統治のなかで、オスマンを辺境の侯国からマルマラ海の両岸に根を下ろした国家に変えた。ブルサ(1326年)、イズニク(1331年)、イズミト(1337年)が奪われ、カレスィ侯国が併合され、最初のアクチェが鋳造され(1327年)、最初のメドレセがイズニクに設けられ(1331年)、ルメリアへの渡りはチンペ(1352年)とゲリボル(1354年)を通じて恒久的になった。ルメリア征服を担った長男Süleyman Paşaを1357年の狩猟事故で失い、自らは1362年3月にブルサで没し、後を息子のムラト1世が継いだ。", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["バーレーン諸島がジャブル朝の手に渡る", "6a242b16"], "d": ["TDVのBahreyn項は、島が「順にウユーン朝、サルグル朝、タービー朝、ジャブル朝の統治下にあり、ジャブル朝の時代に住民の多数派がシーア派からスンナ派に移った」と記し、いずれにも日付を与えていない。一般の文献では、ジャブル朝は15世紀の初めに、カティーフの最後のジャルワーニー朝の君主を倒して成立し、最盛期(アジュワード・ブン・ザーミル、1496年没)にはペルシア湾のアラブ側沿岸の全体、ハサー、カティーフ、バーレーン諸島を管理した。アジュワードの後、アヴァール(Evâl)諸島はムクリン・ブン・ザーミルに移った——1521年にポルトガル人に敗れることになる君主である。", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["アルジラのポルトガルによる奪取——モロッコ沿岸の第二の橋頭堡", "83444a11"], "d": ["アフォンソ5世は3万人の部隊と400隻の艦隊で自らモロッコ沿岸に上陸し、ワッタース朝の統治下にあったアルジラを1471年8月24日に奪った。市の陥落はタンジールの抵抗を砕いた。タンジールは4日後の8月28日に戦わずして降伏した。ポルトガルはこうして、セウタ(1415年)とクサル・エス=セギール(1458年)に続いて、モロッコの大西洋岸に3つ目と4つ目の拠点を築いた。王はこの遠征の後、称号に「アフリカの主」の語を加えさせた。", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["サフィがポルトガルの影響下に入る", "765e703e"], "d": ["大西洋岸で最も活発な穀物と漁業の港サフィは、1488年にポルトガルの影響下に入った。市はしばらく現地の統治者の手でポルトガルの庇護下に統治され、1508年に直接占領された。史料はこの二つの段階に異なる重みを置くため、開始日は1488年と1508年のあいだで揺れる。どちらも同じ過程の両端である。サフィは53年間ポルトガルの手に残り、1541年のアガディールの陥落の後に撤収された。", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["サンタ・クルス・ド・カボ・デ・ゲの建設——アガディールにおけるポルトガルの要塞", "cc22c433"], "d": ["スース沿岸の、それまでポルトガルの達していなかった地点に、私的な企てによって築かれたサンタ・クルス・ド・カボ・デ・ゲ要塞は、1505年に建設され、1513年にポルトガル王室に譲渡された。要塞は、スース渓谷の砂糖と金の交易を管理し、マラケシュの南西の出口を塞いでいた。このためサアド朝の運動の最初の大きな標的となった。1533年の包囲は撃退され、1541年のものは成功し、ポルトガルのモロッコにおける崩壊を始めた。", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["アゼンムールの奪取——ウンム・アル=ラビーウ河口の管理", "232acd4b"], "d": ["ブラガンサ公ジャイメ指揮のポルトガル軍は、ウンム・アル=ラビーウ川の河口のアゼンムールに1513年9月3日に抵抗を受けずに入った。市の奪取は、河口と内陸に開く穀物の道の両方の管理をもたらし、翌年その12キロ南西にマザガン要塞が築かれる道を開いた。アゼンムールは28年間ポルトガルの手に残った。", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["マザガン要塞の建設——モロッコで最も長く残ったポルトガルの拠点", "786cdb40"], "d": ["アゼンムールの奪取の翌年、1514年の夏に、沿岸にマザガンの砦が築かれた。1541年の全面的な崩壊の後、ポルトガルはモロッコのすべての拠点を放棄したが、マザガンは手放さなかった。逆に要塞をイタリア式の稜堡で最初から作り直させ、市は255年間保持された。1562年の大包囲も撃退された。マザガンは、ポルトガルのモロッコにおける最後の拠点として1769年に撤収されることになる。", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["マルディン要塞の降伏——ディヤルバクルの南におけるサファヴィーの抵抗の終わり", "e6226de5"], "d": ["チャルディランの後にディヤルバクル地方に進軍したBıyıklı Mehmed Paşaがマルディンを包囲したとき、サファヴィー軍は1515年10月に要塞に退いた。市はオスマンの手に渡ったが、要塞は抵抗した。サファヴィーの総督カラ・ハンが援軍を得て反攻に出たことは、1516年5月のコチヒサル(クズルテペ)の戦いに帰結した——Dede Garkın平原での一日中続いた戦いで、カラ・ハンの首が斬られ、軍は四散した。要塞は、TDVの表現では「9か月後にようやく」降伏した。", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["ポルトガルのバーレーン奪取——ジャブル朝の支配の終わり", "315a435a"], "d": ["ジャブル朝の君主ムクリン・ブン・ザーミルがホルムズへの納税を拒否したことを受け、ポルトガル艦隊とポルトガルに従属するホルムズ王国の部隊が島に上陸した。ムクリンは戦いで敗れ、バーレーンは1521年にポルトガルの統治に入った。島はその後80年間、ホルムズを通じて、多くはスンナ派のイラン人総督の手で統治された。バーレーンの真珠と戦略的な位置は、島を、湾におけるオスマン-ポルトガルの争いの直接の標的とすることになる。", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["アガディールの陥落——サアド朝のポルトガルのモロッコからの排除が始まる", "bb1568f6"], "d": ["サアド朝のスルタン、ムハンマド・アッ=シャイフは、1541年2月16日にサンタ・クルス要塞を包囲し、3月12日に攻略した。総督ゲテール・デ・モンロイをはじめ約600人のポルトガル人が捕虜となった。", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["サフィとアゼンムールの撤収——ポルトガルが大西洋岸から退く", "4cb6099a"], "d": ["アガディールが1541年3月12日に陥落し、モロッコのスルタンとの期待された同盟が成立しなかったことを受け、ジョアン3世は大西洋岸の二つの大きな拠点の撤収を命じた。サフィとアゼンムールの撤収は1541年の秋、9月から10月に完了した。こうして1年で三つの拠点が失われ、ポルトガルのモロッコ沿岸における50年にわたる拡大は逆転した。残ったのはセウタ、タンジール、アルジラ、クサル・エス=セギール、新たに要塞化されたマザガンであった。", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["アルジラの撤収——ポルトガルが北岸を縮める", "b5d18373"], "d": ["財政危機とサアド朝の圧力が重なって、ジョアン3世は1471年から保持していたアルジラを撤収した。ポルトガルのモロッコにおける存在はこうしてセウタ、タンジール、マザガンに縮んだ。アルジラは1577年に短期間再占領され、1589年に最終的に放棄されることになる。", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["オスマンのバーレーン遠征——湾でポルトガルに対する最後の大きな一手", "14501df3"], "d": ["1546年のバスラの併合とハサー州の設立により湾のアラブ側沿岸に定着したオスマン帝国は、島の真珠交易とポルトガルのホルムズ線を標的に、ハサーのベイレルベイMustafa Paşaの指揮でバーレーンに進軍した。遠征の結果は史料で分かれる。TDV『イスラーム百科事典』は、オスマンが「1559年にバーレーンを奪い、そこに基地」を築いたが、島々は「その後再びポルトガルの統治に」移ったと記す。西洋の文献は、包囲が失敗し、ホルムズから海路で来たポルトガルの援軍がオスマン軍を撃退し、両軍を打ちのめした疫病の後にオスマンが降伏条件を求めたと記す。二つの叙述は結果そのもので分かれる。共通するのは、バーレーンがオスマンの手に恒久的には残らなかったことである。", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Uluç Ali Paşaのチュニス奪取——ハフス朝・スペイン体制の終わり", "d4498698"], "d": ["カール5世が1535年にチュニスを奪ったとき、市を自ら統治せず、ハフス朝のスルタン、ムーレイ・ハサンを王座に戻していた。TDVの表現では、チュニス市は「1569年のオスマンの2度目の介入まで、スペインの庇護のもと、ムーレイ・アフメト3世の統治下」にあった。1568年6月27日にアルジェのベイレルベイに任じられたUluç Aliは陸路でチュニスに進軍し、ベージャでハフス朝のスルタンを破って市に入った。ムーレイ・アフメトはスペインの駐屯地ハルクルワードに逃れた。こうして湾は二つに分かれ——市はオスマン、港の要塞はスペイン——この分割は4年続いた。", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["ドン・フアン・デ・アウストリアのチュニス奪回——レパントの陸上における唯一の対応", "a6f044ee"], "d": ["レパント(1571年)の後、神聖同盟が解体したにもかかわらず、スペインは単独で北アフリカに向かった。TDVの表現では「1573年10月10日、スペイン人はチュニスの支配を握る目的で新たな作戦に着手した。チュニスを取り、そこに8000人の兵を残した」。ドン・フアン・デ・アウストリアが指揮したこの作戦は、レパントの勝利が陸上で対応を得た唯一の場所であるが、恒久的ではなく、市は11か月後に奪い返された。占領が覆したのは、確立していたオスマンの統治であった。ヒジュラ暦980年ズー・アル=ヒッジャ月2日(1573年4月5日)に、チュニスの司令官はKılıç Ali Paşa、代理はRamazan Paşa、ベイレルベイはHaydar Paşaであった。", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["サファヴィー朝のバーレーンのポルトガルからの奪取", "c37d982c"], "d": ["シャー・アッバース1世が送った部隊は島の反乱者と合流してポルトガルの守備隊を要塞から追い出した。TDVの表現では、島々は「1602年にイランに属する部隊により」ポルトガルの手から奪われた。バーレーンはこうして81年のポルトガルの統治を離れてサファヴィーの支配に入り、115年間イランに属した。これは、ポルトガルの湾における崩壊の最初の環である。20年後にホルムズ自体も英・イランの共同作戦で陥落することになる。", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["オマーンのバーレーン侵攻——サファヴィーの支配の終わり", "c9be5820"], "d": ["サファヴィー朝の最後の年の解体のさなか、ヤアルブ朝の統治下のオマーン艦隊が島に侵攻し、サファヴィーの支配は終わった。続く35年は湾で最も混乱した時期である。島はオマーン、イラン、現地のアラブ勢力の間で何度か手を移った。", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["バーレーンがブーシェフルのアール・ミズクール統治に移る", "610e2f9d"], "d": ["もとオマーンから来てブーシェフルに居を定め、フワーラ(Huvele)とみなされるアール・ミズクール家は、1753年にブーシェフルの拠点からバーレーンを統治下に置いた。家はイランのペルシア湾岸のアラブ人の共同体を率い、島をイランの名で治めていた。最後の代表ナスル・アール・ミズクールは、ザンド朝の統治によりバーレーン総督に任じられた。これは、アール・ハリーファ以前の島の最後の統治である。", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["マザガンの撤収——ポルトガルのモロッコにおける最後の拠点が陥落", "f9e9749d"], "d": ["アラウィー朝のスルタン、ムハンマド3世・ブン・アブドゥッラーが1769年初頭に始めた包囲に対し、592人の守備隊は持ちこたえられなかった。2月1日にリスボンを出た撤収艦隊は、1769年3月11日に最後の兵を乗船させ、市を最後に離れたのは総督ディニス・グレゴリオであった。こうして1415年のセウタの奪取に始まったポルトガルのモロッコにおける存在は、3世紀半の後に終わった。マザガンは、1541年の全面的崩壊の後に保持された唯一の大西洋岸の拠点であり、255年でポルトガルがモロッコで最も長く保った地となった。", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["アール・ハリーファのバーレーン征服——今日まで続く王朝の成立", "8773b011"], "d": ["ザンド朝統治下のバーレーン総督ナスル・アール・ミズクールは、カタール半島のズバーラを包囲した。アフマド・ブン・ムハンマド・ブン・ハリーファの指揮するウトゥーブの部隊は包囲を破り、反攻に転じて同年バーレーンを奪った。TDVの記録は簡潔である:「バーレーンは1783年にウトゥーブ部族のアール・ハリーファの支配に入った。」アフマド・ブン・ムハンマドはこの勝利の後「アル=ファーティフ(征服者)」の称号で呼ばれ、彼が築いた王朝は島で今日まで統治している。", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["バーレーンとイギリスの条約——湾における保護体制への参入", "576796b2"], "d": ["TDVの記録によれば、「1861年5月21日、イギリスと、バーレーンを代表するシェイフ・ムハンマドの兄弟アリーは、地域における奴隷交易と海賊行為を禁じる協定に署名した」。イギリスの文書では、同じ条約(Perpetual Truce of Friendship and Peace)は1861年5月31日の日付を持つ。条約は、バーレーンの外交をイギリスに結ぶ保護体制の最初の環であり、島は、オスマンが1871年にハサーとカティーフに再び定着した後も、この体制の外にとどまった。", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ahî Evran——アヒー組織の創始の守護聖者", "3392e100"], "d": ["Ahî Evranは、アナトリアにおけるアヒー組織の創設者の一人であり、皮なめし職人(debbağ)の守護聖者とされる。クルシェヒルにある彼のザーウィヤは、オスマン期に職人・ギルド組織の精神的な中心として20世紀初頭まで続いた。国家はこの地位を1780年、1782年、1822-23年、1842年に正式に確認した。", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["シェイフ・エデバーリ——アヒー組織とオスマン王家の創業の結びつき", "c1186059"], "d": ["ビレジクにザーウィヤを設け、アヒー組織のシェイフでもあったエデバーリは、伝承によればオスマン・ガーズィーの有名な夢を解釈した。その後、オスマン・ガーズィーはエデバーリの娘マルフン・ハトゥンと結婚した。エデバーリは同時に最初のオスマンのカーディー兼ムフティーとされる。", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["オルハン・ガーズィー、ブルサ征服後にジリット競技のための場所を寄進", "da1becbd"], "d": ["TDVのCirit項によれば、オルハン・ガーズィーは、ブルサの征服の後、周辺の一帯を競馬とジリット(投げ槍)競技のために寄進した——ジリット競技がオスマンで制度化された最初の記録の例の一つである。", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["クルクプナル・レスリングの伝承上の始まり", "2d93fa65"], "d": ["伝承によれば、クルクプナルのレスリングの伝統は、ルメリア征服者Süleyman Paşaとともに渡った40人のガーズィーの間で行われたレスリングの試合から始まったとされる。TDVのGüreşとKırkpınar項はこの伝承を伝えるが、確実な創設の日付は与えない。", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["イェニチェリ軍団の創設", "f4206dce"], "d": ["Çandarlı Kara HalilとMolla Rüstemの主導で、ペンチク法に基づき戦争捕虜から取られた非ムスリムの若者を教育することで始まった制度は、ゲリボルに設けられたアジェミ軍団を通じて、ムラト1世の時代に制度的な性格を得た。", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["エディルネのエスキ・モスク(大モスク)の建設の開始", "da7a22ac"], "d": ["民間ではウル・ジャーミィ(Câmi-i Atîk)の名でも知られるエスキ・モスクの建設は、アミール・スレイマン・チェレビにより1402-1403年に始められた。", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["ブルサのイェシル・モスク複合施設の建設の開始", "280b8a21"], "d": ["空位時代の後に王座を再び統一したメフメト1世は、複合施設の建設を1414年に始めさせ、ブルサの中心的な地点に、祖父と父の複合施設とは区別されるかたちで位置づけた。主任建築家はHacı İvaz Paşaである。", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["ブルサのイェシル・モスク複合施設の完成", "bc82821f"], "d": ["タブリーズの職人たちも寄与したタイルと装飾の計画で知られるイェシル・モスク複合施設は、1419年12月に完成した。複合施設はモスク、廟(Yeşil Türbe)、メドレセ、イマーレット、ハンマームからなり、初期オスマン建築の最も豊かな例の一つである。", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["デヴシルメ制の実際の適用の開始", "fa835172"], "d": ["それ以前のイスラーム国家には見られなかったデヴシルメの方式は、まずペンチク法に基づき、非ムスリムの戦争捕虜の若者を用いるかたちで始まった。TDVによれば、「チェレビ・メフメトの時代に適用されたが、その息子ムラト2世の時代に法典化されたことがわかる」。", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["シェイヒュルイスラーム職の創設——Molla Fenârîのブルサのムフティー職", "2a8ee2b9"], "d": ["長年ブルサのカーディーを務めた学者Molla Fenârîの1425年のブルサのムフティー職への任命は、TDVの表現では「オスマンにおけるムフティー職とシェイヒュルイスラーム職の始まり」とされる。ただしTDVは、これが16世紀にウラマー組織の全体を代表する完全に制度化されたシェイヒュルイスラーム職と同一ではないと述べている。", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["ティマール制の制度化", "dc267780"], "d": ["文書に基づくティマールへの最初の言及はオルハン・ベイの時代にさかのぼる。体系的な法典化はムラト2世の時代に行われた。この時期に作成されたティマールの概要台帳は、制度のすべての基本原則が形づくられていたことを示す。1432年ごろの文書は、法が完全に施行されていたことを裏づける。", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["ユチ・シェレフェリ・モスクと複合施設の完成", "cde6993e"], "d": ["ムラト2世により、Muslihuddinと Şehâbeddinという名の職人に10年間(1437-1447年)で建てさせたユチ・シェレフェリ・モスク(三つのバルコニーのモスク)は、オスマン建築における中央平面のモスクの最初の例とみなされ、古典期以前の移行期の建築の転換点の一つである。", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["ファーティヒの法によるディーワーン・ヒュマーユーンの制度化", "e8443e77"], "d": ["ディーワーンは、ムラト2世の時代にエディルネで定期的な規則に結ばれ、「ディーワーン・ヒュマーユーン」の性格を得始めた。本当の転換はファーティヒ・スルタン・メフメトの法によりもたらされた。最大の革新は、スルタンのディーワーン議長職が完全に廃止されて大宰相に委ねられたことである。", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["ファーティヒ・スルタン・メフメト、オクメイダヌを弓術家に割り当てる", "342a9fd5"], "d": ["コンスタンティノープルの征服の際にカスムパシャの丘に本営を置いたファーティヒ・スルタン・メフメトは、そこを同時に弓術家の訓練場としても用いていた。市を奪った後、この地を恒久的に弓術家に割り当てた。この割り当ては、オクメイダヌが何世紀も続くオスマンの弓術の伝統の中心となる始まりである。", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["ブルサのイラン絹交易が頂点に達する", "f1324cdf"], "d": ["タブリーズから来た隊商はギーラーン、アスタラーバード、サーリーの絹をブルサに運び、ここでジェノヴァ、ヴェネツィア、フィレンツェ、ユダヤの商人が競って買っていた。1479年にイランから輸入された絹の価値は15万ヴェネツィア金貨に達した。1502年には市で1000台を超える織機が稼働していた。", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["バヤジト2世、クルクプナルの力士に大賞を与える", "d745b882"], "d": ["TDVのGüreş項によれば、バヤジト2世は1504年に力士たちに3000と1500クルシュの賞を与えた。これはオスマン宮廷がレスリングという競技に与えた庇護の、記録に残る早い例の一つである。", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["バヤズィト・モスクと複合施設の完成", "eb9ab65b"], "d": ["バヤジト2世のために建てさせたバヤズィト・モスクと複合施設の建設は、ある公文書によればヒジュラ暦906年(1500年)に始まり、ヒジュラ暦911年ジュマーダー・アル=ウーラー月14日(1505年10月13日)に完成した。建築家には議論がある。Ayvansarâyîの記録に基づいて長くミマール・ハイレッディンの作とされ、のちにミマール・ケマーレッディンに結びつけられ、両者が共に働いたとする者もいる。一方、同じ文書は職人がYâkub Şah b. Sultan Şahであることを示している。モスクは、古典期以前のオスマン建築から古典期への移行の重要な記念建造物とされる。", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Tersâne-i Âmire(帝国造船所)のイスタンブル(カスムパシャ/金角湾)への移転", "f36e3675"], "d": ["セリム1世(ヤヴズ)の時代に、ガラタの城壁の西の入り江で建設が始まった新しい造船所は、1515年に160のドック(göz)で完成した。こうしてゲリボルを中心とした造船活動はイスタンブルに移った。機関はその後、Barbaros Hayreddin Paşaの時代に正式に「Tersâne-i Âmire」の名を得た。", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["シェイフ・ハムドゥッラーの死と書道流派の遺産", "f5ed4d09"], "d": ["アマスヤ出身のシェイフ・ハムドゥッラーは、バヤジト2世の書道の師として、アクラーム・スィッタ(6種の書体)の流派を成熟期に導き、イスラーム世界全体で優勢となるオスマンの書風の創始者となった。1520年に没したとき、後に多くの弟子の輪を残した。", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["ピーリー・レイス、『Kitâb-ı Bahriye』の最初の版を完成", "fd6cc1ff"], "d": ["地中海の沿岸、港、航海の情報を集めた『Kitâb-ı Bahriye』の最初の(散文の)版を、ピーリー・レイスは1521年に完成した。この最初の版はまだスルタンに献上されておらず、その後の年に拡充される草稿の性格のものであった。", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["ピーリー・レイス、『Kitâb-ı Bahriye』を拡充してスレイマン1世に献上", "d4abf0b7"], "d": ["ピーリー・レイスは、『Kitâb-ı Bahriye』を一部韻文のかたちで拡充し、1526年にスレイマン1世に献上した。作品はこの形で、オスマン航海術で最も包括的な航海案内書として広まった。", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Matrakçı Nasuh、イラケイン遠征の経路を『Beyân-ı Menâzil』に描く", "aa012278"], "d": ["スレイマン1世が1534年に出た最初のイラン(イラケイン)遠征に従ったMatrakçı Nasuhは、軍がイスタンブルからタブリーズへ、そこからバグダードへ向かう経路の各宿営地を、細密画と地図の技法で描いた。この作業は『Beyân-ı Menâzil-i Sefer-i Irâkeyn』という作品にまとめられ、オスマンにおける宿駅記(menzilname)の類型の最も独創的な例である。", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["フズーリー、バグダード征服後にスレイマン1世にカスィーデを献上", "1ef0653f"], "d": ["スレイマン1世が1534年にバグダードを征服した後、フズーリーは、オスマンのスルタンに、「Geldi burc-ı evliyâya pâdişâh-ı nâmdâr」の一句で始まる有名なカスィーデを含む5篇のカスィーデを献上した。こうしてサファヴィーの庇護を離れ、オスマンの国家要人の庇護を求めた。", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["フズーリー、『ライラーとマジュヌーン』のマスナヴィーを完成", "e3ef4085"], "d": ["古典トルコ文学で最も美しいマスナヴィー(叙事詩)の一つとされる『ライラーとマジュヌーン(Leylâ vü Mecnûn)』は、フズーリーにより1535年に、スレイマン1世のバグダード遠征に従ったイスタンブルの詩人たちの求めに応じて書かれ、完成した。", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["ミマール・スィナンが宮廷建築長に任命される", "7a753f0e"], "d": ["TDV『イスラーム百科事典』のSinan項によれば、宮廷建築長Acem Alisiが1537年に死去したため、モルダヴィア遠征でプルト川に架けた橋で注目されたスィナンが、大宰相Lutfi Paşaの評価によりこの職に就けられた。こうしてスィナンの、50年を超えて続く建築長の時代が始まった。", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["シェフザーデ・モスクと複合施設の建設の開始", "1a70ddfd"], "d": ["スレイマン1世は、1543年に疫病で失った息子シェフザーデ・メフメトのために複合施設の建設を命じた。工事は1543年6月に始まり、まず廟が完成し、続いてモスクの建設に移った。この建物はミマール・スィナン自身の言葉で「私の見習いの作品」である。", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["ウスキュダル・イスケレ(ミフリマー・スルタン)複合施設の完成", "3769007f"], "d": ["ウスキュダルのイスケレ広場にある複合施設の工事は1540年代の最初の数年に始まり、1547年に完成した。ミフリマー・スルタンがミマール・スィナンに建てさせた二つの大モスクのうち、年代順で最初のものである。2番目(エディルネカプ)は約20年後に完成することになる。", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["ヴェネツィアがアレッポに領事館を開設", "3aad8b9e"], "d": ["16世紀に、ヨーロッパ人の商業の重心はダマスクスからアレッポに移った。この変化の具体的な指標として、ヴェネツィアは1548年にアレッポに領事館を開き、1557年にフランス、1586年にイギリスが続いた。市は、ヨーロッパの毛織物と銀とインドの香辛料、世紀末にはイランの絹が交換される主要な市場となった。", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["シェフザーデ・モスクが礼拝に開かれる", "2bb3f4b2"], "d": ["約5年続いた工事の後、シェフザーデ・モスクは1548年8月に礼拝に開かれた。二本のミナレットと中央のドームという平面構成により、ミマール・スィナンのその後の大作の先触れとされる。複合施設はモスク、廟、メドレセ、イマーレット(給食施設)、タブハーネ(宿泊施設)、隊商宿からなる。", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["クルクチェシュメ水道の送水線の建設の開始", "14124b59"], "d": ["ミマール・スィナンは、スレイマン1世の命でベオグラードの森からイスタンブルへ水を引くことを調査し、可能であると報告した。大規模な水道施設の工事は1554年に始まり、1563年以前に完成した。TDVはこの建造物を、スィナンの「工学の面で最も重要で、規模の面でも最大の作品」と評している。", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["イスタンブルで最初のコーヒーハウスの開店", "85c12f9f"], "d": ["コーヒーのオスマンの都市生活への導入は、タフタカレでアレッポの商人Hakemとダマスクスの人Şemsという名の人物が開いたコーヒーハウスから始まった。短期間のうちに社会のあらゆる層の人々が集まる新たな公共の場が生まれた。スレイマン1世の最後の時期にはイスタンブルに50軒のコーヒーハウスがあった。", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Ebüssuûd Efendi、gedik(職人の独占権)の問題を法的に検討", "5d4e2930"], "d": ["職人の世界で一定数の者に認められた独占と特権の権利である「gedik」の問題は、スレイマン1世の時代に再び浮上した。シェイヒュルイスラームEbüssuûd Efendiは1555-56年に問題を深く調べ、慣行の正当性をスルタンに示した。", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Seydi Ali Reis、『Mir'âtü'l-Memâlik』をイスタンブルで完成", "ee8640e1"], "d": ["バグダードから始まる帰路の旅の間に書いた旅行記『Mir'âtü'l-Memâlik』を、Seydi Ali Reisは1557年1月にイスタンブルで完成した。作品は、オスマンの海の男がインド洋から中央アジア経由の陸路で故国に戻る旅を語る、一次史料である。", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Rüstem Paşa複合施設(モスク)の建設", "02e30725"], "d": ["スレイマン1世の婿で大宰相のRüstem Paşaがミマール・スィナンに建てさせた複合施設は、1555-1561年のあいだに建設された。建物は、下にアーチ状の店を備えた高い基壇の上に築かれた独特の建築と、豊かなイズニクのタイルで知られる。", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["モスタル橋の完成", "e7f434af"], "d": ["ネレトヴァ川に架かる有名なモスタル橋は、1566-67年ごろにミマール・ハイレッディンにより築かれた。1568年付の公式文書に橋が言及されていることは、完成していたことを裏づける。建造物は、単一の尖頭アーチをもつ古典オスマン橋梁建築の最も知られた例の一つである。", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["エディルネカプ(ミフリマー・スルタン)モスクの完成", "f2d21a82"], "d": ["スレイマン1世の娘ミフリマー・スルタンのために1563年に確認された建設許可の後に始まったモスクの建設は、1566年に完成した。複合施設の寄進文書は1570-71年に作成された。建物は、ミマール・スィナンの作品のうちイスタンブルの城壁に最も近い大きなものの一つである。", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Bâkî、スレイマン1世のために哀悼詩を書く", "7aa6665f"], "d": ["スレイマン1世のシゲトヴァールでの死の知らせが届いたとき、当時の「詩人の王(sultânü'ş-şuarâ)」Bâkîは、オスマン文学で最も有名な哀悼詩の一つを書いた。", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Bâkî、セリム2世に即位賛歌を献上", "6027f034"], "d": ["セリム2世の即位の直後、Bâkîは新スルタンに「cülûsiye」(即位の詩)を献上した——TDVによれば、スレイマン1世の死に際して書いた哀悼詩の直後である。", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["ビュユクチェクメジェ橋の完成", "5f49b3c5"], "d": ["スレイマン1世の命で始められた橋は、スルタンがシゲトヴァール遠征中に死去したため、息子のセリム2世により1567-68年に完成させられた。ミマール・スィナンは、ビュユクチェクメジェ湖が海に出る地点に築いた橋の、洪水で損傷した部分も自ら修復した。", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["セリミエ・モスク(エディルネ)の工事の開始", "07e18c9e"], "d": ["ミマール・スィナンが「私の熟練の作品」と呼んだセリミエの工事は、セリム2世のために1568年に始まり、6年続いて1574年に完成した(完成は年表に既に記録されている)。アラスタ(商店街)の西の店と小学校は、セリム2世の死後、ムラト3世の時代にDâvud Ağaにより完成された。", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Kınalızâde Ali Çelebiの死去——オスマン倫理哲学の古典『Ahlâk-ı Alâî』の著者", "dd921873"], "d": ["オスマン倫理哲学の最も知られた古典『Ahlâk-ı Alâî』の著者Kınalızâde Ali Çelebiは、アナトリアのカザスケルであった1572年1月22日に没した。作品は、イスタンブルの図書館に70を超える写本がある。", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Piyâle Paşa複合施設の建立", "75411278"], "d": ["セリム2世の婿の一人である海軍提督Piyâle Paşaは、複合施設の敷地を1573年に購入し、ミマール・スィナンに建てさせた。複合施設は、モスク、メドレセ、テッケ、廟、墓地、小学校、泉、市場、ハンマームからなる広大な複合体として設計された。", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["ドリナ(ソコルル・メフメト・パシャ)橋の完成", "1d668c73"], "d": ["大宰相ソコルル・メフメト・パシャの庇護のもとミマール・スィナンにより築かれた橋は、碑文の日付によれば1577-78年に完成した。一部の研究者は工事が1571-72年に始まったと主張する。橋は、ソコルルが生まれたヴィシェグラードへの愛着の象徴である。", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["アザプカプ(ソコルル・メフメト・パシャ)モスクの建立", "f7b57feb"], "d": ["ウンカパヌ橋のシシュハーネ側の橋脚の脇にあるモスクは、大宰相ソコルル・メフメト・パシャによりミマール・スィナンに建てさせた。建物は、ソコルルの名で建てられた二つのスィナンのモスクの一つである(もう一つはカドゥルガのモスク)。", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["ムラト3世が『Hünernâme』の執筆の勅令を出す", "b125710d"], "d": ["ムラト3世は、1578年1月2日付の勅令でSeyyid Lokmanに、オスマン・ガーズィーから自らの時代までのスルタンの生涯を主題とする『Hünernâme』の執筆を命じた。作品の細密画はNakkaş Osmanとその一団により準備された。", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Zal Mahmud Paşaモスクの完成", "732f75bc"], "d": ["Zal Mahmud PaşaとŞah Sultanの1574年の結婚の後に始まった複合施設の工事で、モスクの建設は1580年に完成した。メドレセは1582年まで、泉は1590年まで続いた。複合施設は、エユプの丘に二つの対称的なミナレットを持つ独特の平面で注目される。", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["『Hünernâme』第2巻の完成", "70a1e741"], "d": ["『Hünernâme』の第2巻は1588年1月に完成した。65枚の細密画をもち、オスマンの歴史叙述の文書としての価値が最も高い作品の一つとなった。両巻ともNakkaş Osmanの工房で絵が描かれた。", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Dâvud Ağaが宮廷建築長となる", "8cdc7f53"], "d": ["ミマール・スィナンの1588年の死の後の短い間隔を経て、Dâvud Ağaは1592年から公文書で宮廷建築長と呼ばれ始めた。セリミエ複合施設のいくつかの補完的な要素とイェニ・モスクの最初の建設を担ったDâvud Ağaは、当時の最も重要な建築家の一人である。", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["イェニ・モスク(エミノニュ)の礎石が置かれる", "d3cddc01"], "d": ["メフメト3世の母サフィエ・スルタンの後援のもとで、モスクの礎は、地盤を杭で固め、石のブロックで据えられた。TDVの二つの別々の項目がこの出来事に異なる日付を与えている(Yenicami Külliyesi項は1598年4月9日、Dâvud Ağa項は1597年8月23日)。ここでは、建物自身の個別の項目の日付を基準とした。", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Dâvud Ağaのペストによる死とイェニ・モスク工事の中断", "81f2cd04"], "d": ["イェニ・モスクをまだ地面から1ズィラー(約75センチ)ほどしか立ち上げていなかった1598年9月にペストの流行で没したDâvud Ağaの後任として、Dalgıç Ahmed Çavuşが建築長に任命された。TDVは、死亡の日付が、年代詩に基づく別の伝承では1599-1600年とも伝えられ、正確な日付は確定できないと述べている。", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["アンカラのソフ(毛織物)のヨーロッパへの大規模な輸出", "3f37018d"], "d": ["アンカラで織られたソフとシャーリーは、イスタンブル、ブルサ、ダマスクス、アレッポといった国内市場のほか、ヴェネツィア、ポーランド、イギリス、フランスに輸出された。TDVの挙げる例では、1599年に18人の商人が570万アクチェ相当のソフ162荷を買い、アレッポとヴェネツィアに送った。", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["メフメト3世の死によりイェニ・モスクの工事が中断", "5acef053"], "d": ["施主であるサフィエ・スルタンの息子メフメト3世が1603年に死去した後、サフィエ・スルタンは旧宮殿に送られ、イェニ・モスクの工事は中断した。建物はこの状態で約60年間、未完成のまま待つことになった。", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Kâtib Çelebi、『Keşfü'z-Zünûn』のためアレッポで調査を開始", "094e6870"], "d": ["Kâtib Çelebiは、のちに書誌学の傑作となる『Keşfü'z-Zünûn』の資料を集めることを1633年にアレッポで始めた。20年続くこの作業の間、訪れた都市の図書館と書店を一つずつ調べた。", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Nef'î、風刺のため処刑される", "5e459c60"], "d": ["風刺で知られるディーヴァーン詩人Nef'îは、風刺集『Sihâm-ı Kazâ』のため、1635年にムラト4世の命により処刑された。大宰相Bayram Paşaが彼を引き渡した。Nef'îは宮殿の薪置き場で絞殺され、遺体は海に捨てられた。", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["エヴリヤ・チェレビの最初の旅——『旅行記』の始まり", "ca3ce3f9"], "d": ["エヴリヤ・チェレビは、イスタンブル以外への最初の旅を1640年にブルサに行い、10巻の『旅行記(Seyahatnâme)』の基礎をなす40年の旅の生活を始めた。作品は、著者が1684年ごろに没したため、完成することなく第10巻で突然終わる。", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["包括的なnarh(公定価格)台帳の作成", "6c1e231b"], "d": ["narh(価格の上限)の実施はオスマンでは非常に古くからあるが、今日に伝わる最も包括的なnarh台帳は1640年のものである。食料、衣服、サービス、規格、衛生の条件を含むこの台帳は、TDVの表現では「完全な市場規制法のように機能した」。", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Kâtib Çelebi、『Cihannümâ』を初めて書き始める", "554c6734"], "d": ["Kâtib Çelebiは、西洋の地理上の発見に対するオスマンの地理学の知識の空白を埋める目的で、『Cihannümâ』の最初の執筆を1648年に始めた。この最初の版は、一部のヨーロッパ諸国について十分な史料が見つからなかったため、未完に終わった。", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["イルティザーム制が軍人層の独占に入って成熟", "2c587934"], "d": ["イルティザーム(税の徴収を代価と引き換えに私人に請け負わせる方式)は15世紀後半から実施されていたが、16世紀の初めから急速に広まっていた。TDVによれば、部門が完全に軍人層の構成員の独占に入る過程は1650年に完了した。イルティザームはこうして、ティマール制に取って代わる主要な財政の方法となった。", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Kâtib Çelebi、『Cihannümâ』を最初から書き直し始める", "e9c68110"], "d": ["最初の執筆を中断したKâtib Çelebiは、『Cihannümâ』を1654年の末に最初から書き直し始めた。この第二の版も完成しなかった。作品はヴァンまで来たところで、著者の1657年の死により未完となり、1732年にİbrahim Müteferrikaによりこの形でようやく印刷された。", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["イェニ・モスクが完成し礼拝に開かれる", "d6d86c82"], "d": ["60年以上中断していたイェニ・モスクの工事は、ハティジェ・トゥルハン・ヴァーリデ・スルタンが1661年に就任させた建築長Meremetçi Mustafa Ağaの指揮のもとで完成し、1665年10月30日に行われた金曜礼拝により礼拝に開かれた。", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["メフメト4世、エディルネの割礼祝宴で何日もジリットを行わせる", "3638a5b6"], "d": ["メフメト4世は、1675年にエディルネで開いた王子たちの割礼祝宴で、何日も続くジリットの競技を催した。これは、オスマン宮廷がジリット競技に与えた支援の最も華やかな例の一つとして、TDVのCirit項で特に言及される。", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Hâfız Osmanが独自の書風を発展させる", "93081cb3"], "d": ["シェイフ・ハムドゥッラーの系譜に連なるHâfız Osmanは、1679年にアクラーム・スィッタにおいて、のちに「Hâfız Osmanの流派」と呼ばれる独自の新しい書風を発展させた。この書風は二つの別々の流れとして今日まで続いている。", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Hâfız Osman、ムスタファ2世の書道の師に任命", "d976cda4"], "d": ["当時最も熟練した書家とされたHâfız Osmanは、1695年に即位したばかりのムスタファ2世の書道の師に任命された。生涯で約50人の書家を育て、25部のクルアーンを書写した。", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Itrîの死去", "62750526"], "d": ["トルコ音楽の最大の作曲家の一人Buhûrîzâde Mustafa Itrî Efendiは、当時に近い史料によれば1711年に没した。セガーフのテクビールとラストのナアトなどの作品で、モスクとテッケの音楽の傑作を残した。", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Nedîm、チューリップ時代の詩の先駆者として頭角を現す", "d3c40dbb"], "d": ["1718-1730年のチューリップ時代を通じて、Nedîmは、表現の完璧さ、素朴さの追求、機知に富む文体で際立つ新しい詩風を発展させた。Nevşehirli Damad İbrahim Paşaの周囲で発展したこの書風は、ディーヴァーン詩における土着化の潮流の最大の代表とされる。", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levnîが『Surnâme-i Vehbî』に挿絵を描く", "8c127866"], "d": ["宮廷の絵師Levnîは、アフメト3世の王子たちの1720年の割礼祝宴を語る『Surnâme-i Vehbî』に、137枚の細密画で挿絵を描いた。従来の例と異なり、祝祭をアトメイダヌ(競馬場広場)にのみ閉じ込めず、市の様々な場所で描いたことで、オスマン細密画の芸術に新しい理解を始めた。", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["gedik制度が独占を基礎とする職人制度として正式に定着", "cd0f79a7"], "d": ["TDVによれば、gedikの権利が「独占、特権、一種の特許」の意味を得る体系的な転換は1727年から追跡される。職人の世界で一定数の者に働く権利を認めるこの制度は、多くが寄進財産の店で「gedik権」の名で定着した。", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Sâdâbâdがパトロナ・ハリル反乱で破壊される", "8a30f9a0"], "d": ["1730年9月25日に勃発したパトロナ・ハリル反乱のさなか、Sâdâbâdの数百のあずまやや建物が破壊された。チューリップ時代の象徴であるこの複合施設は、二度と往時の壮麗さを取り戻さなかった。", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Nedîm、パトロナ・ハリル反乱のさなかに死去", "06bf909e"], "d": ["パトロナ・ハリル反乱が勃発したとき、Sekban Ali Paşa メドレセの教授であったNedîmは、反乱に続く日々のうちに死んだ。死んだ日は不明だが、遺産に関する分割証書がヒジュラ暦1143年ラビーウ・アーヒル月15日(1730年10月28日)に作成されたことから、この日付より前に死んだことになる。死因については様々な伝承がある。史料の一部は、彼が恐怖の病(illet-i vehîme)か、酒とアヘンのせいによる震えの病で死んだと述べ、Müstakimzâdeは、騒乱のさなかに恐怖から家の屋根に上り、そこから落ちて死んだと記す。その死により、チューリップ時代の文化的な輝きも事実上終わった。", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Levnîの死去", "dd48b56e"], "d": ["オスマン細密画芸術の最後の大きな代表者とされるLevnîは、1732年に没した。作品の大部分は今日トプカプ宮殿博物館にある。", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["ヌルオスマニエ・モスクと複合施設の礎石が置かれる", "397ec798"], "d": ["ヌルオスマニエ複合施設の礎石は、マフムト1世により1749年1月19日に置かれた。この建物は、オスマン建築におけるヨーロッパのバロック様式の最初の大きな適用とみなされ、古典的な複合施設の構成から明確に離れている。", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["ヌルオスマニエ・モスクと複合施設の開館", "15d83731"], "d": ["マフムト1世が始め、完成を見ることのなかった複合施設の開館は、弟オスマン3世の時代の1755年12月5日に行われた。モスクは、開館を行ったオスマン3世にちなんで、「オスマンの光」を意味する名を得た。", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Mühendishâne-i Bahrî-i Hümâyun(海軍工学校)の開校", "a2fab1cd"], "d": ["オスマン最初の近代的な海軍工学校Mühendishâne-i Bahrî-i Hümâyunは、フランスの文書館の史料によれば、1775年4月29日にアブデュルハミト1世の時代、大宰相Derviş Mehmed Paşaの在任中に開校した。", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["esham制度の創設", "eabd8ece"], "d": ["キュチュク・カイナルジャ条約がもたらした750万クルシュの賠償金の負担を前に、1775年にesham制度が創設された。マーリカーネ(終身徴税権)の限界を超えるために設計されたこの方式では、ムカータア(徴税請負地)の収入が持分に分けられ、マーリカーネとは異なり、女性、非ムスリム、一般の人々も持分の所有者となることができた。", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Hammâmîzâde İsmail Dede Efendiの誕生", "c033f039"], "d": ["トルコ音楽で最も多作な作曲家の一人Hammâmîzâde İsmail Dede Efendiは、1778年1月9日にイスタンブルのシェフザーデバシュ地区に生まれた。生涯に500を超える作品を作曲し、そのうち約294が今日に伝わる。", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Mühendishâne-i Berrî-i Hümâyun(陸軍工学校)の建設の開始", "4f5d521a"], "d": ["セリム3世のニザーム・ジェディード改革で最も重要な機関の一つであるMühendishâne-i Berrî-i Hümâyunの建設が1793年7月14日に始まった。建物は1795年9月に完成して教育に開かれた。この機関は、ヨーロッパの軍事アカデミーを手本としたオスマンの二番目の軍事工学校であった。", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["セリム3世が一部の職人ギルドの独占を廃止し始める", "008f4a7d"], "d": ["TDVのEsnaf項によれば、成立以来アヒー組織と入り混じっていたオスマンのギルド制度では、「アヒー・ババ」や「シェイフ」といった役職者が19世紀初頭までギルドの指導を務めた。18世紀に、ギルドが独占により価格を公定価格(narh)の上に引き上げたことが経済的な圧迫を生むと、セリム3世は1794年から基本的な食料のギルドの独占を廃止し始めた。", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Dede Efendi、musâhib-i şehriyârîとして宮廷に迎えられる", "0cb99ac3"], "d": ["セリム3世の時代にブセリクの曲でスルタンの注意を引いたDede Efendiは、1812年にマフムト2世により「musâhib-i şehriyârî」(スルタンの側近の話し相手)の中に迎えられ、まもなくムアッズィン長に昇進した。", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["オスマンにおける最初の定期的な人口調査の実施", "4f004c6c"], "d": ["マフムト2世は、徴兵される人口を確定する目的で、初めて1830年の終わりに定期的な調査を行わせた。男性人口のみが記録され、アナトリア-ルメリアで約750万人が確定された。エルズルムとヴァンなど一部の地方では、調査は1836年にようやく完了できた。", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Feshâne-i Âmire(フェズ工場)の創設", "971ab85a"], "d": ["イェニチェリ軍団が1826年に廃止された後に設けられたAsâkir-i Mansûre-i Muhammediyye軍のフェズの需要を満たすため、150万クルシュの資本で1833年にカドゥルガのCündî Meydanıでフェズの生産が始まった。施設は1839年にエユプのハティジェ・スルタン宮殿に移された。Feshâneは、オスマンの繊維産業の基礎を形づくった。", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["医学校がMekteb-i Tıbbiyye-i Adliyye-i Şâhâneの名を得る", "187d60f3"], "d": ["ガラタサライのエンデルン・アー学校の建物に移った医学校は、1839年5月14日のマフムト2世の訪問により「Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne」の名を得た。機関はこうして軍事・行政の学校としての性格を正式に認められた。", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Dede Efendi、巡礼の際にミナーで死去", "c3e613a2"], "d": ["ハッジの義務を果たすために赴いたミナーでコレラに罹ったHammâmîzâde İsmail Dede Efendiは、1846年11月29日に没した。1824-1839年のあいだに7つの別々のメヴレヴィー儀礼曲を作曲した芸術家の死により、古典オスマン音楽の一時代が閉じた。", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["1850年商法典の採択", "8ac085fd"], "d": ["タンジマート期の法改革の枠組みのなかで、西洋諸国から翻訳と借用により新しい法が取り入れられた。刑法は1840年に、商法は1850年に、土地法は1857年に施行された。商法典(Ticaret Kanunnâmesi)は、オスマン商法の最初の近代的な法典化であった。", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["クリミア・タタール人とカフカスの諸民族のオスマン領への大規模な移住の波の開始", "8832c06d"], "d": ["シャミールが1859年にロシアの捕虜となった後、クリミア・タタール人とともに、カフカスから多数のチェルケス人とノガイ人の移民がオスマン領に移住し始めた。この移住の波は、1877-78年の露土戦争の後まで、様々な強さで続いた。", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["移民委員会(Muhâcirîn Komisyonu)の設置", "9717e77e"], "d": ["カフカスからの増大する移住の波を管理するため、オスマン政府は1860年1月16日に移民委員会を設けた。委員会は、アナトリア、バルカン、シリアにおける定住の作業を調整し、1875年まで活動した。", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Bank-ı Osmanîの Bank-ı Osmanî-i Şâhâne(オスマン銀行)としての再編", "c3530456"], "d": ["1856年にクリミア戦争の後、対外債務の支払いを管理するために、ロンドンを本拠とするイギリス資本のBank-ı Osmanîが設立されていた。1863年にフランス・イギリス合同のグループに、Bank-ı Osmanî-i Şâhâne(オスマン銀行)の名で新しい銀行を設立する許可が与えられた。機関はのちに銀行券を発行する権限も得た。", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyyeの設立", "77ad553a"], "d": ["貧しいムスリムの徒弟の教育を担う目的で、1864年3月30日にCem'iyyet-i Tedrîsiyye-i İslâmiyyeが設立された。この民間団体の試みは、慈善機関の伝統が近代的な学校の企画に変わる先駆的な例である。団体は9年後にダルシュシャファカ(Darüşşafaka)を開くことになる。", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["1864年州規則によるムフタール職と長老会議制度の整備", "1a2e8cf2"], "d": ["1864年の州規則(Vilâyet Nizamnâmesi)により、村の統治が再編された。ムスリムと非ムスリムが共に住む村では、各共同体が自らのムフタールと長老会議(ihtiyar meclisi)を選ぶことが認められた。長老会議はこうして初めて、村・街区の統治に正式な位置を得た。", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["大チェルケス人追放のピーク", "b2ab1874"], "d": ["ロシアによる1858-1878年のカフカス占領、とりわけ最も激しかった1861-1864年に、120万から150万のチェルケス人がオスマン領に強制的に移住させられた。TDVによれば、多数の研究者がこの出来事を「近代史における最初の民族浄化の動き」と性格づけている。", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["1869年一般教育規則(Maârif-i Umûmiyye Nizamnâmesi)の公布", "787f6022"], "d": ["1869年9月1日に公布された一般教育規則は、地方と中央における一般教育を定めた最初の包括的な文書となった。規則により大教育評議会(Meclis-i Kebîr-i Maârif)が設けられた。小学校(sıbyan mektepleri)を単なる宗教教育の段階から外し、読み書きの教育に向けて再構成することが、この規定により始まった。", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["ダルシュシャファカ学校が教育を開始", "525c457c"], "d": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyyeが設立したダルシュシャファカは、1873年6月28日に、孤児と貧しいムスリムの子どもを無償の寄宿で教育するため、実際に授業を始めた。入学年齢は最大10歳と定められた。", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["1894年のイスタンブル地震", "7ae7f648"], "d": ["1894年7月10日にイズミト湾沖で起きた地震は、イスタンブルを激しく襲った。イスタンブルの城壁を含む多くのモスクと歴史的建造物が被害を受けた。TDVのzelzele項は、この地震を1509年、1719年、1766年の地震とともに、マルマラ地方に多大な人的・物的損害をもたらした地震に数える。", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["ダールラージェゼ(Dârülaceze)の開設", "a30baf31"], "d": ["アブデュルハミト2世が1890年から出した命令に基づいて準備されたダールラージェゼは、1896年2月2日に大宰相Halil Rifat Paşaにより開かれた。身寄りのない子ども、高齢者、困窮者を収容した機関は、200床の病院、工房、モスク・教会・シナゴーグなど別々の礼拝所を備え、当時最大の社会福祉の複合体であった。", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Dârülfünûn-ı Şâhâneが恒久的機関として再設立", "7d6d8fc4"], "d": ["ダーリュルフュヌーン(Darülfünun)は、それ以前の二つの失敗した試み(1863年と1870年)の後、1900年8月31日にDârülfünûn-ı Şâhâneの名で恒久的な機関として再設立された。TDVはこの日付を、今日のトルコの大学制度の直接の基礎と位置づけている。", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["サルバダール朝がサブザヴァールを奪取——ホラーサーンにおけるイル・ハン国以後の最初の国家", "af997fec"], "d": ["アブー・サイードの死(1335年11月30日)によりイル・ハン国の中央の権威が崩れると、ホラーサーンで徴税官に対して蓄積した反発がバーシュティーンで爆発した。アブドゥッラッザークは1337年3月13日に蜂起し、1337年9月9日(ヒジュラ暦738年サファル月12日)にサブザヴァールを奪った。「サルバダール(Serbedâr)」——「首が絞首台にある者」——の名は、敗れれば絞首刑を覚悟するという彼ら自身の言葉である。", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["マルアシー家のサイイドがアーモルを奪取——マーザンダラーンにおけるサイイドの支配", "c0e03266"], "d": ["サイイド・キワームッディーン・マルアシーは、サルバダール朝がホラーサーンで開いた道を行き、ヒジュラ暦760年(1359年)にアーモルを奪って、カスピ海の南岸にサイイドの国家を築いた。王朝はサーリー、バールフルーシュと周辺に広がり、ティムールの遠征で揺らぎ、サファヴィー朝のシャー・アッバース1世の時代に解体された。", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["カールキヤー朝がギーラーンに成立——カスピ海沿岸の最後の独立の支配者", "6e5f9db7"], "d": ["アリー・キヤーは家族とともにギーラーンに戻り、ヒジュラ暦773年(1371-72年)にラーヒージャーンを中心とするカールキヤー朝の支配を築いた。王朝はカスピ海の南西岸を2世紀以上保持し、サファヴィー朝のシャー・アッバース1世が1592年に地方を併合するまで続いた。", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["ダルフールにおけるダージュー(Dâcû)の支配のトゥンジュール(Tuncûr)への移行", "6eb22a2a"], "d": ["TDV『イスラーム百科事典』のDârfûr項によれば、地域に最初に定住し、最初の国家を築いたのはダージュー部族である。13世紀と14世紀を通じてここを支配したダージュー人は、商業上の支配をトゥンジュール人に奪われ、15世紀には、とりわけ中部の状況が完全にトゥンジュール人に有利に転じた。", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["スペインによるバーディス(Peñón de Vélez)の岩礁の奪回", "0dc52728"], "d": ["TDVのSa'dîler項は、スペイン人がバーディスを奪ったことがマグリブの航海に重い打撃であったと記す(1564年)。北モロッコの沿岸にあるこの岩礁の拠点は、西地中海における海賊行為とオスマン・スペインの争いの拠り所となっていた。", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["アル=アラーイシュ(ララシュ)のスペインへの譲渡", "7b8f6e27"], "d": ["サアド朝が分裂した内戦の年に、大西洋岸のアル=アラーイシュ港はスペインに譲られた。TDVのSa'dîler項は、この時期に国がマラケシュ(南)とフェズ(北)の首長国に二分され、王位争いの当事者が外からの援助を求めたと記す。港は80年近くスペインの手にあり、1689年にムーレイ・イスマーイールが奪い返すことになる。", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["マモーラ(マフディーヤ)のスペイン人の手への移行", "c8fd494e"], "d": ["セブー川の河口のマモーラ(Ma'mûre / Mehdiye)港は、1614年にスペイン人に奪われ、サン・ミゲル・デ・ウルトラマールの名で要塞化された。TDVのMevlây İsmâil項は、港がヒジュラ暦1092年(1681年)に急襲でスペイン人の手から奪い返されたと記す——つまりスペインの支配は67年続いた。", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["サアド朝の終わり——モロッコにおけるアラウィー(フィラーリー)朝時代の始まり", "b1afa579"], "d": ["TDV『イスラーム百科事典』はSa’dîler項を「モロッコで統治したイスラーム王朝(1511-1659年)」と定義している。1549年にワッタース朝の支配を終わらせてモロッコ全体を統一し、1578年にワーディー・アル=マハーズィンでポルトガル軍を壊滅させ、いかなる時期もオスマンに従わなかった王朝は、長い王位争いの末に1659年に終わった。その座を、ターフィーラルトから来たアラウィー(フィラーリー)のシャリーフたちが占めた。ムーレイ・ラシードは1666年にフェズ市に入って新王朝を固め、弟のムーレイ・イスマーイールが大西洋岸のヨーロッパの拠点を一掃した。", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["スペインによるアル=フサイマ(アルウセマス)諸島の占領", "954ca998"], "d": ["地中海沿岸のアル=フサイマ諸島は、1673年にスペイン艦隊に占領された。バーディスとセウタとともに、スペインが北モロッコの沿岸に保持し、今日まで手にある拠点の一つである。同年にムーレイ・イスマーイールの兄ムーレイ・ラシードがマラケシュに入って住民から忠誠を受け、フィラーリー朝の支配が南で固まっていた——沿岸でのこの喪失は、内部の統合が対外戦線にはまだ対応していないことを示す。", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["ムーレイ・イスマーイール、アル=アラーイシュをスペインから奪回", "a54bc6ee"], "d": ["TDVのMevlây İsmâil項は明確である:「ヒジュラ暦1100年(1689年)にアラーイシュをスペイン人から取り返して200門の大砲を得、2年後にはアスィーラも取り戻した。」これは、フィラーリー朝のスルタンの沿岸掃討の環の一つである——タンジールは1678年にイギリスから、マモーラは1681年に、アル=アラーイシュは1689年に、アスィーラは1691年に取り戻された。80年前にサアド朝内戦で放棄された港は、こうしてモロッコに戻った。", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["ダルフール・スルタン国の成立——ケイラ朝とSüleyman Solonc", "0fc1c112"], "d": ["TDVによれば、ダルフール・スルタン国の成立は、17世紀末にBumû el-Kasîrが地域に侵入した後に続いた混乱の後にあたる。フール人は、Süleyman Solonc率いるキーラー(ケイラ)家の指導のもと、支配をダージュー人とトゥンジュール人の手から奪い、堅固な統治を築いた。Süleyman Soloncは1695-1715年に統治した。ダルフールのスルタンたちはその後の世紀に、Bâbıâliと文通した。アブデュルメジトとアブデュルアズィズは彼らの統治を承認した。", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["フランスで第一共和政が宣言される——王政の終わり", "d53d49b0"], "d": ["国民公会の最初の会期で王政が廃止され、翌日に第一共和政が宣言された。新しい暦の第1年はこの日から始められた。オスマンにとって相手は変わらなかったが、相手の性格が変わった。セリム3世のニザーム・ジェディードの年に、フランスはもはや王朝ではなく体制であり、1798年にエジプトに上陸することになるのもその体制の軍であった。", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["大カビリアの陥落——ラッラ・ファトマ・ンスメルの捕縛", "0f61ff08"], "d": ["TDVのCezayir項は、山岳のカビリア(Bilâdü'l-kabâil)地方が1853年、1854年、1857年の遠征の末に占領されたことで、フランスのアルジェリア占領の動きが大部分完成したと記す。1857年の遠征はティズィ・ウゾウとアクブーの線を破り、抵抗の象徴ラッラ・ファトマ・ンスメルが捕虜となった。アミール・アブドゥルカーディルが1847年に降伏した後も残っていた最後の大きな抵抗の拠点は、こうして消えた。", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["アイン・サーリフ(ティディケルト)のフランスによる占領", "1e28d1d0"], "d": ["サハラの中央のティディケルトのオアシス群の中心アイン・サーリフは、1899年12月29日にフランス軍に奪われた。これは、アルジェリアの沿岸から南に下るフランスの拡大が砂漠に及んだ最初の大きな一歩である。2年のうちにトゥワートとグーララも同じ道をたどることになる。", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["トゥワート・グーララ・ティディケルトのオアシスのフランスへの併合", "d412838b"], "d": ["アルジェリアの南西にあるトゥワート、グーララ、ティディケルトのオアシス帯は、1901年2月21日に正式にフランスに結ばれた。モロッコのスルタンが名目上の権利を主張したこの隊商路の結節点——アドラール、ティミムーン、レッガーン、ベニ・アッバースを含む——は、こうしてアルジェリアに編入された。モロッコとフランス領アルジェリアの間の国境紛争の始まりはこれである。", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["ベシャール(コロンブ=ベシャール)にフランスの哨所の設置", "4d44d252"], "d": ["モロッコ国境のベシャールのオアシスは、1903年11月11日にフランス軍に奪われ、コロンブ=ベシャールの名で前進哨所とされた。トゥワート帯の併合の2年後にあたるこの一歩は、フランスのアルジェリアからモロッコへの進出の最後の環の一つであり、モロッコが1912年に保護下に置かれる道を開く。", "bd1a7ae2"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["カレスィ侯国とハミド侯国の成立", "3905da93"], "d": ["TDVのKaresioğulları項によれば、カレスィ・ベイは、父カレム・ベイの死で解体したセルジューク朝の辺境組織のなかで独立を宣言し、696年(1296-97年)からバルケシルを中心とし、短期間でエルデク、ビガ、エドレミト、ベルガマを含むミシアの全体をビザンツから奪った。同年(1297年)にハミド・ベイは、ウルボルルを政庁の所在地としてハミド侯国を築いた。イスパルタ、ブルドゥル、エイルディル、ヤルヴァチは、解体したセルジュークの辺境地域から侯国の最初の国境に加わった。二つの侯国とも、西アナトリアにおける同じ崩壊——セルジューク朝の中央権力の解体——の産物である。", "7d297343"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["アイドゥン侯国の成立——イズミル、アヤスルク、ティレの奪取", "69a021ae"], "d": ["TDVのAydınoğulları項によれば、ムバーリズッディーン・ガーズィー・メフメト・ベイは、ゲルミヤン朝の辺境ベイSâsâ Beyからこの地方を奪い、1308年にアイドゥン地方で支配権を握った。イズミルのムスリムの区域を、アヤスルク(セルチュク)、ティレ、ボデミヤとともに征服した。アヤスルクを海軍基地とし、奪った土地を5人の息子で分けた——侯国はその後の数十年に、とりわけ息子ウムル・ベイの時代に、エーゲ海の航海における決定的な勢力となることになる。", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["ルーム・セルジューク朝の事実上の終焉——イル・ハン国の直接統治", "00f85ecb"], "d": ["TDVのMesud II項によれば、長い病気の末に708年(1308年)にカイセリで死んだギヤースッディーン・マスウード2世は、通説ではルーム・セルジューク朝の最後の君主である——彼の死の後に即位した候補者は、国内の官職からもイル・ハン国からも承認を得られなかった。地方は、マスウードの治世を通じて既に事実上イル・ハン国の官吏により統治されていた。彼の死により、この直接統治は、コンヤ、ニーデ、アクサライなどの中心地で形式上の覆いをも失った。", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["チャンダル侯国のカスタモヌ-チャンクル-バルトゥン-サフランボルへの拡大", "64e39ad0"], "d": ["TDVのCandaroğulları項によれば、侯国は、イル・ハン国の君主ガイハトゥがエフラニとその周辺をイクターとして与えたシェムセッディーン・ヤマン・チャンダルにより、14世紀の初めにカスタモヌ-シノプの周辺に築かれた。史料の不足のため、創設の正確な日付は知られていない。チャンダルの後継Süleyman Beyは、チョバン朝侯国に取って代わった君主として語られる——つまりカスタモヌとチャンクル周辺はチョバン朝から、バルトゥン-サフランボル-エフラニ線はイル・ハン国の直接統治からチャンダル侯国に移ったのである。", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["ロドスとドデカネス諸島の聖ヨハネ(ホスピタル)騎士団による征服", "67885b4b"], "d": ["TDVのRodos項は、島が1309年に聖ヨハネ騎士団(Hospitalier/İsbitâriyye)の手に渡ったと記す。標準的なホスピタル騎士団史(J. Riley-Smith, The Knights Hospitaller参照)は、包囲が1306年の夏に始まり、ビザンツの増援で長く抵抗したロドス市が、総長フルク・ド・ヴィラレの部隊により1310年8月15日にようやく陥落したと詳述する。島はこの日付から1522年のオスマンの征服まで騎士団の中心となり、周辺のドデカネス諸島も同じ過程でビザンツからホスピタル騎士団の支配に移った。", "c1422e2c"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["コス島(İstanköy)の聖ヨハネ騎士団による奪取", "445666f7"], "d": ["TDVのİstanköy項によれば、聖ヨハネ騎士団はロドスに居を定めた後、コス島も奪って(1315年)新たな要塞を築いた。島はこうして1523年まで続く騎士団の支配に入った。1310年のロドス市の陥落の後、コスがどの統治下にあったかは、TDVでは詳しく述べられていない。", "145d1bad"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["エレトナ侯国の成立——イル・ハン国以後の中央アナトリア", "a67bacd9"], "d": ["TDVのEretnaoğulları項によれば、ウイグル出身のイル・ハン国の官吏アラーウッディーン・エレトナは、イル・ハン国の君主アブー・サイード・バハードゥル・ハンの1335年の死の後、アナトリアにおけるイル・ハン国の代官職を事実上独立した統治に変えた。まずマムルーク朝スルタンの代理として現れ、1340年にフトバからマムルークの名を外し、1341年ごろ完全な独立を宣言した。中心がまずスィヴァス、次いでカイセリであった侯国は、彼の死(1352年)まで、アマスヤ、トカット、チョルム、ニーデ、アクサライ、エルズィンジャンを含む広い中央アナトリアの支配を築き、1381年にカーディー・ブルハーンッディーンにより終わらされた。", "04978a80"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["ジャライル朝の成立——イル・ハン国以後のアゼルバイジャン", "a13ada90"], "d": ["TDVのCelâyirliler項によれば、イル・ハン国のアミール・ノヤンの孫ハサン・ブズルグは、イル・ハン国の君主アブー・サイード・バハードゥル・ハンの死とともに勃発した王位争いを利用して、1340年にタブリーズを中心とする独立国家を築いた。ジャライル朝はこうして、アゼルバイジャンとその周辺でイル・ハン国以後の空白を埋めた最初の大きな王朝となった。後継者ウワイス(Üveys)の時代(1356-1374年)に領土はモスルとディヤルバクルまで拡大することになる。", "224cbb81"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["バグダードのカラ・コユンルの手への移行——ジャライル朝スルタン・アフマドの敗北", "a42ebe92"], "d": ["TDVのKarakoyunlular項によれば、カラ・ユースフは、ヒジュラ暦813年ラビーウ・アーヒル月28日(1410年8月30日)にタブリーズ近郊でジャライル朝のスルタン・アフマドに大敗を与えた。スルタン・アフマドの死の後の814年(1411年)に息子ピール・ブダクをタブリーズでスルタンと宣言し、同年に長男シャー・メフメトがバグダードを征服した。こうして1世紀近くジャライル朝の首都であったバグダードは、周辺のバスラ-モスル-キルクーク線とともにカラ・コユンルの支配に入った。", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["エルズィンジャンとケマがアク・コユンルに移る——カラユリュク・オスマン・ベイ", "122460d4"], "d": ["カラ・ユースフの死の後、エルズィンジャンの住民の求めで、Mutahhartenの孫Yâr Aliが市の総督となっていた。その時代にアク・コユンルのベイ、カラユリュク・オスマンがエルズィンジャンを奪ってアク・コユンルの領土に加えた。この日付以後、エルズィンジャンは、あるときはアク・コユンルとカラ・コユンルの間で、またあるときはアク・コユンルの王子たちの間で手を移る場所となった。", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["カザン・ハン国の成立——ウルグ・ムハンマド・ハンのジョチ・ウルスからの離脱", "335a7408"], "d": ["TDVのKazan Hanlığı項によれば、ジョチ・ウルスの首都サライで王座を失ったウルグ・ムハンマド・ハンは、家族と約3000人の兵とともにまずベレフに退き、1437-1438年にロシアの公ヴァシーリー2世と争い、その後カザン市に居を定めた。地元住民の支持を得てここに新しいハン国の礎を築いた。TDVは、成立の過程が1437-1445年のあいだに完成し、ハン国が1445年から完全に独立の地位を得たと述べている——地図はこの過程の始まりを、ウルグ・ムハンマドがカザンに居を定めた1438年に基準を置いている。", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["クリム・ハン国の成立——ハーッジー・ギレイのジョチ・ウルスからの独立", "5728223e"], "d": ["TDVのKırım項によれば、クリム・ハン国は、14世紀後半のジョチ・ウルスが王位争いで分裂した産物として現れた。ハン国の真の創設者ハーッジー・ギレイが鋳造した最古の貨幣はヒジュラ暦845年(1441-42年)の日付を持ち、これがハン国の公式の成立の日付とされる。同年ハーッジー・ギレイは、モスクワと友好を結ぶことでクリミアでの地位を固め、シリン部族をはじめとする現地のベイの家々が彼の側についた。", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["ジャハーン・シャー、エルズィンジャンを奪取——カラ・コユンルの支配", "0c928cc4"], "d": ["カラ・コユンルの君主ジャハーン・シャーは、854年(1450年)にエルズィンジャンに軍を送り、市をアク・コユンルから奪った。この喪失は、アク・コユンルのベイ、ジャハーンギール・ミールザーと弟ハサン・ベイ(ウズン・ハサン)の仲が裂ける原因となった。", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["カラ・コユンルのジャハーン・シャー、ティムール朝イラン(レイ、イスファハーン、ファールス、ケルマーン)を奪取", "c6fbb3f5"], "d": ["TDVのKarakoyunlular項によれば、カラ・コユンルの君主ジャハーン・シャーは、ティムール朝の王子たちの間の王位争いを利用して、856-857年(1452-1453年)にレイ、イスファハーン、ファールス、ケルマーンの諸州を統治下に置いた。これは、シャールフ・ミールザーの1447年の死の後に始まり、スルターニーヤ-カズヴィーンの併合で開いた拡大の過程の頂点である。ティムール朝の南・中部イランの領土はこうしてカラ・コユンルに移った。ジャハーン・シャーの支配は1466年に、アゼルバイジャン、アッラーン、イラク・アジャミー、イラク・アラビー、ファールス、ケルマーン、東アナトリアを含む広さに達することになる。", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["ボルドーのイギリスによる奪回——ジョン・タルボットの最後のギュイエンヌ遠征", "01b2b7be"], "d": ["1451年にフランス人に失われたボルドーは、住民がフランスの守備隊に対して蜂起して門を開いたことで、年老いた司令官ジョン・タルボット率いるイギリス軍に、1452年10月22日から23日の夜に降伏した。これは、百年戦争においてイギリスがギュイエンヌで得た最後の、そして短命の勝利であった。ボルドーは1年後、カスティヨンの戦いの後に恒久的にフランスに戻ることになる。", "f6945d27"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["ウズン・ハサン、エルズィンジャンを奪回——再びアク・コユンルに", "550d010a"], "d": ["ウズン・ハサンはカラ・コユンルを破って、エルズィンジャンを再びアク・コユンルの支配下に置いた。市は1473年のオトゥルクベリの戦いの後もアク・コユンルの国境内に残った。", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["第二次トルン条約——ダンツィヒ(グダンスク)と西プロイセンがポーランドに結ばれる", "e2152dae"], "d": ["プロイセン同盟が1454年にドイツ騎士団(Teutonic Order)の統治に対して蜂起したことで始まった十三年戦争を終わらせた第二次トルン(Toruń)条約は、1466年10月19日に調印された。騎士団は、ダンツィヒ(グダンスク)を含む東ポモージェ、エルビング(エルブロンク)を含むヴィスワ川の河口、およびクルム地方をポーランド王国に譲った——これらの土地は「王領プロイセン」の名を得た。東プロイセンは1525年まで騎士団に残ることになる。", "831685a9"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["カテリーナ・コルナーロ女王がキプロスをヴェネツィアに譲渡——十字軍国家の終わり", "e24d3f3a"], "d": ["夫のジャック2世王の1473年の死の後、女王摂政としてキプロスを治めていたヴェネツィア出身のカテリーナ・コルナーロは、継承者がいなかったため、ヴェネツィア政府の圧力で1489年2月26日に退位し、島における君主の権利を総督(ドージェ)とヴェネツィア共和国に譲渡した。見返りに女王の称号を保ち、テッラフェルマのアゾロ伯領を得た。この譲渡により、1192年から続いたリュジニャン家の支配と最後の十字軍国家は終わり、島は1570-71年のオスマンの征服までヴェネツィアの統治下に残った。", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["グラナダの陥落——イベリア半島における最後のムスリム国家の終わり", "46e5201b"], "d": ["10年続いた段階的な包囲と内部の分裂で弱体化したグラナダのナスル朝首長国の最後の君主アブー・アブドゥッラー(ボアブディル)は、1491年11月に調印された寛大な降伏条件(グラナダ降伏協定)に従い、1492年1月2日に市の鍵をカトリック両王フェルナンドとイサベルに引き渡した。アルハンブラを去ったボアブディルの後、イベリア半島における最後のムスリム国家は終わり、レコンキスタは完成した。同じ年のうちに、ユダヤ人の追放(3月)とクリストファー・コロンブスの航海(8月)が続くことになる。", "5dc28ef8"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["モスクワ・リトアニア休戦——チェルニゴフ・セヴェルスク地方がモスクワに移る", "8e4c56f9"], "d": ["1500-1503年のモスクワ・リトアニア戦争は、ハンガリー-ボヘミア王ウラースロー2世の仲介による6年間の休戦で終わった。リトアニア大公国は、チェルニゴフ・セヴェルスク地方(チェルニゴフ、ノヴゴロド・セヴェルスキー、スタロドゥーブ、ブリャンスク周辺)とスモレンスクおよびポロツク周辺の一部の土地を含む、大公国のおよそ3分の1を占める広大な土地を、モスクワ大公国に譲らざるを得なかった。これは、モスクワがロシアの土地を「集める」過程で最大の単独の獲得の一つであった。", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["シャイバーニー・ハン、ヘラートとホラーサーンをティムール朝から奪取", "a81d8575"], "d": ["TDVのŞeybânî Han項によれば、ウズベクの君主シャイバーニー・ハンは、1503-1505年にアンディジャン、フェルガナ、ヒサール、クンドゥズ、バルフを奪った後、913年(1507年)にティムール朝の首都ヘラートをも攻略した。『イラン百科事典(Encyclopaedia Iranica)』のホラーサーン項はこの征服の正確な日付を与えている——市はヒジュラ暦913年ムハッラム月8日(1507年5月20日)に陥落し、1週間後のムハッラム月15日(5月27日)にフトバがシャイバーニー・ハンの名で読まれて征服が正式化した。マシュハドを含むホラーサーンの全体が同年のうちにティムール朝からシャイバーニー朝に移った。これは、ティムール朝がマーワラーアンナフルの後にイランにおける最後の大きな拠点をも失ったことを意味した。", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["オランのスペインへの陥落——枢機卿シスネロスの北アフリカ遠征", "86ed8ac1"], "d": ["西地中海の海路を管理し、トレムセンの港であったワフラーン(オラン)は、1492年にグラナダから逃れたアンダルスのムスリムとユダヤ人が避難したことで成長していた。16世紀の初めにマグリブ沿岸の港町を一つずつ奪っていたカスティーリャ王国は、1509年5月17日にワフラーンを占領した。住民の大半が殺され、残りは捕虜となり、市にはムスリムとユダヤ人の住民は残らなかった。スペイン人は城壁と要塞を拡張した。ワフラーンは1708年までスペインの手に残った。", "be7b3b1b"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["低地諸国のスペイン王冠への結びつけ——フェルナンドの死、カール5世の即位", "fbe0dbd2"], "d": ["アラゴン王フェルナンド2世が1516年1月23日に死ぬと、1506年からブルゴーニュ公の資格で既に低地諸国(今日のベルギー・オランダ・ルクセンブルクと北フランスの一部)を統治していた孫のカール5世(カルロス)は、カスティーリャとアラゴンの王位の相続人ともなり、1516年3月14日にブリュッセルでスペイン王と宣言された。こうしてこれらの土地は、人的連合を通じて、ハプスブルク家のドイツ/オーストリアの系統ではなく直接スペインの王冠に属するとみなされ始めた——1519年にカール5世が神聖ローマ皇帝に選ばれることで、この二つの身分(スペイン王とドイツ・ローマ皇帝)は同一人物に結合し、地域のスペインへの帰属は、1556年にカール5世が退位して遺産を息子フェリペ2世に残すまで続くことになる。", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["ドゥマク・スルタン国がマジャパヒトを倒し、ジャワ沿岸を支配", "7da602b5"], "d": ["TDVのDemak項によれば、ジャワ最初の独立ムスリム国家であるドゥマク・スルタン国は、15世紀の最後の四半世紀にラデン・パタにより築かれた。ジャワの史料によれば、衰退していたヒンドゥー・仏教のマジャパヒト王国は、ドゥマクの攻撃により消滅した。1527年にドゥマクは、中国の史料が11世紀からマジャパヒトの君主にとって重要な港として挙げるトゥバンを征服した——これは、マジャパヒトの最後の残党もドゥマクに結ばれた年であり、ジャワの大部分のイスラーム化の過程の転換点である。", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["ノルウェーのデンマーク王冠に属する州への格下げ", "8e2f274e"], "d": ["デンマーク王クリスチャン3世は、1536年の戴冠憲章(håndfæstning)で、ノルウェーがもはや別個の王国とはみなされず、デンマークの州として統治されること、ノルウェーの国務会議(riksråd)が廃止されることを宣言した。この決定は、1537年にデンマーク教会規則がノルウェーにも適用されて実効的となり、スコットランド・ノルウェー出身の司教オーラヴ・エンゲルブレクトソンの抵抗が砕かれた。ノルウェーは実際にはなお一時期、自らの法と制度を保ったが、政治的な地位はもはや独立した王国ではなくデンマークの王冠に属する州であった——この状態は1814年まで続くことになる。", "a8c9dee7"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["ヴィリニュス条約——リヴォニア連合の解体、クールラントとリヴォニアがポーランド・リトアニアに結ばれる(リガ市を除く)", "d1ceaad5"], "d": ["リヴォニア戦争の間にロシアの圧力のもとで解体したリヴォニア連合の最後の大総長ゴットハルト・ケトラーは、1561年11月28日にヴィリニュスで調印された条約(Pacta Subiectionis)により、リトアニア大公兼ポーランド王ジグムント2世アウグストの庇護下に入った。リガ市を除くリヴォニアの大部分がポーランド・リトアニアに結ばれ、ケトラーはクールラント公国の最初の公となった。これは、リヴォニア騎士団の中世から近世への移行における最後の幕であった。", "bcd4efe9"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["廃位布告(Plakkaat van Verlatinghe)——オランダがスペインからの独立を宣言", "a632aaee"], "d": ["八十年戦争が続くなか、ユトレヒト同盟に属するオランダの諸州の全国議会(Staten-Generaal)は、1581年7月26日に採択した廃位布告で、スペイン王フェリペ2世を「暴君」と宣言して彼への忠誠を拒んだ。この文書は、実際に独立した連合州(オランダ共和国)の設立宣言とされる。スペインの最終的な承認は1648年のヴェストファーレンを待つが、実質的な断絶はこの日である。", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["スモレンスクのポーランド・リトアニアへの陥落——20か月の包囲の終わり", "4e9678e3"], "d": ["動乱時代(スムータ)に、ポーランド王ジグムント3世の軍は、1609年9月から包囲していたスモレンスクの城壁に、1611年6月13日に坑道を爆破して突破口を開き、市を奪った。20か月の抵抗は終わった。スモレンスクは1654年までポーランド・リトアニアに残り、この陥落は、7年後に調印されるデウリノ休戦(1618年)の素地を整えた。", "25d6488d"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["ストルボヴァ条約——ロシアがバルト海沿岸(イングリア)をスウェーデンに失う", "175dc175"], "d": ["イングリア戦争を終結させたストルボヴァ条約は、1617年2月27日にラドガ湖の南のストルボヴァ村で調印された。ロシアはノヴゴロドと北のその他の土地を取り戻す一方、スウェーデンはカレリアとイングリア(エストニア-フィンランド間、イヴァンゴロド-ヤム-コポリエ-オレシェクの要塞を含む)を保持し、ロシアのバルト海への直接の沿岸が断たれた。この断絶は、1703年にピョートル大帝が同じ地方にサンクトペテルブルクを築くまで続くことになる。", "7e70e3e6"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["デウリノ休戦——スモレンスク、チェルニゴフ、ノヴゴロド・セヴェルスキーがポーランドに譲られる", "6880d2c1"], "d": ["1609-1618年のポーランド・ロシア戦争を終わらせたデウリノ休戦は、1618年12月11日に調印され、14年半の停戦をもたらした。ロシアは、スモレンスク(ヴャジマを除く)と、チェルニゴフおよびノヴゴロド・セヴェルスキーの地方の29の都市を、ポーランド・リトアニア連合に譲らざるを得なかった——これは、動乱時代(スムータ)で最も重い領土の喪失であった。地方は1667年のアンドルソヴォ休戦までポーランドに残ることになる。", "5c52de5a"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["ペレヤスラフ・ラーダ——ザポロージャ・コサックがロシアのツァーリに忠誠を誓う", "bcd8f8ef"], "d": ["1648年からポーランド・リトアニアに対して蜂起していたザポロージャ・コサックのヘトマン、ボフダン・フメリニツキーは、モスクワからヴァシーリー・ブトゥルリンを長として来た使節団が加わる、1654年1月18日(ユリウス暦1月8日)のペレヤスラフ・ラーダで、ツァーリ・アレクセイ・ミハイロヴィチへの忠誠を誓った。これは、ウクライナ・コサックのヘトマン国のロシアの庇護下への入りの始まりとされ、チェルニゴフ・セヴェルスク地方の実質的な管理をポーランドからロシアへ移した——正式な国境は1667年のアンドルソヴォ休戦で引かれることになる。", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["スモレンスクのロシアによる奪回", "bf0eca92"], "d": ["1654年に始まったポーランド・ロシア戦争の間、ロシア軍は7月から包囲していたスモレンスクを、1654年10月3日にポーランドの守備隊が降伏して奪回した。1611年にポーランドに失われた市は、43年後にロシアに戻った。これは、ロシアが動乱時代の喪失を覆す過程の最も重要な歩みの一つであり、1667年のアンドルソヴォ休戦で恒久的となった。", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["アンドルソヴォ休戦——キエフと左岸ウクライナがロシアに移る", "799be067"], "d": ["1654-1667年のポーランド・ロシア戦争を終結させたアンドルソヴォ休戦は、13年半の停戦をもたらした。ロシアは、スモレンスク、チェルニゴフ・セヴェルスク地方、ドニエプル川左岸のウクライナと、——当初は2年間、実際には恒久的に——キエフ市を得た。この条約は、ウクライナの領土がドニエプル川に沿ってポーランドとロシアの間で分割されること(そしてキエフがロシアに残ること)の法的な基礎を築いた。", "94445e3a"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["サンクトペテルブルクの創設——ロシアの西に開く窓", "ba196be0"], "d": ["大北方戦争の間にスウェーデンから取り戻したばかりのネヴァ川のデルタにあるウサギ島で、ピョートル大帝は1703年5月16日(グレゴリオ暦27日)にペトロパヴロフスク要塞(ペトロパヴロフスカヤ要塞)の礎を置いた。この日がサンクトペテルブルク市の創設の日とされる。ピョートルは、湿地のデルタを西に開く「窓」として構想し、市は1712年にロシアの新しい首都となった——地方が正式にロシアに結ばれるのは、1721年のニスタット条約によってである。", "24c24aaf"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["ラシュタット条約——スペイン継承戦争が終わり、スペイン領ネーデルラントとミラノがオーストリアに移る", "3c0e086f"], "d": ["スペイン継承戦争をフランスとオーストリアの間で終わらせたラシュタット条約は、1714年3月7日に調印された(ユトレヒト条約は1713年にイギリス・フランス間を整えていた)。条約により、オーストリアのハプスブルク家は、スペイン領ネーデルラント(今日のベルギー)と、イタリアのナポリ、ミラノ、サルデーニャを引き継いだ。これはオーストリアの歴史上最も大きな領土拡大であり、ハプスブルク家の中欧における比重に、西・南ヨーロッパの新たな戦線を加えた。", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["ニスタット条約——大北方戦争が終結し、バルト海沿岸がロシアに移る", "068ffd06"], "d": ["21年続いた大北方戦争を終わらせたニスタット条約は、1721年9月10日(ユリウス暦8月30日)にフィンランドで調印された。スウェーデンはロシアに、エストニア、リヴォニア(リガを含む)、イングリア、南東フィンランド(カレリア)の一部を譲り、その代わりにフィンランドの残りを取り戻し、賠償金が支払われた。条約は、スウェーデンの大国としての地位の終わりと、ヨーロッパの帝国としてのロシアの台頭の正式な確認とされる——ピョートル1世はこの勝利の後「皇帝」の称号を得た。", "f0c4fc4a"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["ポーランド第一次分割——ロシアとオーストリアへの領土喪失", "2c56a0d8"], "d": ["ロシア、プロイセン、オーストリアの間で1772年8月5日に調印された条約により、ポーランド・リトアニア共和国の領土の約3分の1が分割された。ロシアは今日のベラルーシとラトヴィアの一部(ドヴィンスク、ポロツク、ヴィテプスクを含む)を取り、オーストリアはガリツィア(リヴィウと西ポドリア、ヤズロヴィエツを含む)を併合し、プロイセンは沿岸地方の王領プロイセンを引き継いだ。ポーランドのセイムは、条約を1773年9月30日に、圧力のもとでようやく承認した。これは、1795年まで続く三度の分割の最初である。", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["ポーランド第二次分割——ロシアとプロイセンへの領土喪失", "31750484"], "d": ["1791年の憲法改革がロシアとプロイセンを不安にさせたため、二国は1793年1月23日にサンクトペテルブルクで調印した条約により、ポーランドを再び分割した。ロシアはリトアニア-ベラルーシの大部分と西ウクライナ(カミャネツ、バール、ミンスクを含む)を取り、プロイセンはグダンスクとポズナンを含む大ポーランドを併合した——合計30万7000平方キロ。圧力のもとにあるポーランドのセイムは、同年に条約を承認せざるを得なかった。これは、ポーランドの完全な併合を2年遅らせた短命の分割であった。この日(1793年1月23日)のポーランド第二次分割で、ベルディチェフ、ファストフ、ジトーミル、カニウ、コスチャンティニウ、ウマニ、チェルカースィを含む右岸ウクライナがロシアに移った。", "656e71c2"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["ポーランド第三次分割——国家の完全な消滅", "e3c02d6b"], "d": ["ロシア、プロイセン、オーストリアは、1795年10月24日にサンクトペテルブルクで調印した三者の協定により、ポーランド・リトアニア共和国の残りの領土を完全に分割した。ロシアはリトアニア(ヴィリニュス、カウナスを含む)とベラルーシの残りを取り、プロイセンはワルシャワを含む中部ポーランドを、オーストリアはクラクフを含む南部の地域を併合した。三国はさらに、互いの新しい領土を軍事的に保証し、ポーランドの再建の可能性に備える措置を取った。これは、ポーランド・リトアニア国家が独立国として完全に消滅した出来事であり、20世紀まで再建されることはない。", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["ヴェネツィア共和国の終わり——大評議会が自ら解散", "5efed589"], "d": ["ナポレオンのイタリア遠征軍がヴェネツィアの陸地を占領して共和国に最後通牒を突きつけると、大評議会(Maggior Consiglio)は1797年5月12日に512票対20票で自らの解散を受け入れた。最後のドージェ、ルドヴィーコ・マニンは職を退き、1100年を超えて途切れなく存在してきたヴェネツィア共和国の貴族統治は終わった。領土はまず暫定的な民主政府に、次いで1797年10月のカンポ・フォルミオ条約により正式にオーストリアに譲られた。", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["ジェノヴァ共和国の終わり——ナポレオンがリグーリア共和国を樹立", "3d3e59ee"], "d": ["イタリア遠征中のナポレオンの圧力により、1797年6月初めに暫定政府に委ねられたジェノヴァ共和国に代わって、1797年6月14日にフランス型の憲法のもとで「リグーリア共和国」が宣言された。数世紀にわたるジェノヴァ共和国は事実上、フランスの衛星国の一つに変わった。共和国は1805年に直接フランスに併合され、1815年のウィーン会議でサルデーニャ-ピエモンテ王国に譲られることになる。", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["カンポ・フォルミオ条約——ヴェネツィアのオーストリアとフランスのあいだの分割", "9f29678c"], "d": ["ナポレオン・ボナパルトとオーストリア代表コベンツル伯の間で1797年10月17日に調印されたカンポ・フォルミオ条約は、1000年の歴史をもつヴェネツィア共和国を正式に消滅させ、その領土を分割した。アディジェ川の東、イストリアとダルマチアの沿岸(スプリト、ザダル、シベニク、コトルを含む)はオーストリアに譲られ、イオニア諸島(コルフ、ケファロニア、ザキントス、レフカダ、プレヴェザとパルガを含むヴェネツィアのアルバニア-モレア沿岸の基地)はフランスに移った。オーストリアはさらに、低地諸国(今日のベルギー)の領土をフランスに譲った。", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["マルタのイギリスへの降伏——2年に及ぶフランスの包囲の終わり", "fedc2867"], "d": ["1798年のエジプト遠征の途上でナポレオンが奪ったマルタは、まもなく島民の蜂起によりイギリス艦隊の海上封鎖下に入った。2年続いた包囲と飢餓の末、フランスの司令官ヴォボワ将軍は、1800年9月5日にイギリスのピゴット将軍に降伏した。マルタはこうしてフランス共和国からイギリスの庇護下に移り、1814年のパリ条約で正式にイギリス王冠に結ばれることになる——地中海で最も重要なイギリスの海軍基地となった。", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["アミアン条約——メノルカがスペインに返還される", "f341e4b8"], "d": ["フランス、スペイン、オランダ、イギリスの間で調印されたアミアン条約(1802年3月25日)は、第二次対仏大同盟戦争を一時的に終わらせた。イギリスは、戦争中に奪ったほとんどすべての土地(セイロンとトリニダードを除く)を返還した——その一つが1798年にスペインから奪ったメノルカであった。平和は1年しか続かず、1803年5月に戦争が再び勃発したが、メノルカはこの条約の後、二度とイギリスの手に渡らなかった。", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["フレデリクスハムン(ハミナ)条約——スウェーデンのフィンランドのロシアへの割譲", "c0d407bc"], "d": ["1808-1809年の露・スウェーデン戦争を終結させたフレデリクスハムン(今日のハミナ)条約は1809年9月17日に調印され、スウェーデンはオーランド諸島を含むフィンランド全体をロシアに譲った。フィンランドは、ロシア帝国に属する広範な自治を持つ大公国の地位を得て、ルター派の信仰とスウェーデンの法を保った。これは、スウェーデンのバルト海における大国としての地位が事実上終わったことを意味した。この条約により、フィンランドの6つの州とトルネ川までのヴェステルボッテン(コッコラ、ヨエンスー、サヴォンリンナ、トルニオ、ロヴァニエミ、イナリなど)が、ロシアに属するフィンランド大公国に移った。", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["イメレティ王国の併合——ソロモン2世王が廃位", "5ad36bff"], "d": ["1804年にエラズナウリ協定でロシアの臣従を受け入れざるを得なかった西グルジアのイメレティ王国の最後の王ソロモン2世が、強まるロシアの圧力に抵抗し続けたため、ロシア軍は1810年2月20日に首都クタイシを奪い、ソロモンを廃位し、地元の貴族にツァーリ・アレクサンドル1世への忠誠を誓うよう強いた。イメレティ王国はこうして事実上終わり、直接のロシアの統治に結ばれた。ソロモンはオスマン領に逃れて亡命先で没した(1815年)。", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["キール条約——デンマークのノルウェーのスウェーデンへの割譲", "59ab1601"], "d": ["ナポレオンのライプツィヒでの敗北の後、デンマークに南から攻め込んだスウェーデンは、1814年1月14日に調印されたキール条約によってノルウェー(アイスランド、フェロー諸島、グリーンランドを除く)を譲り受けた——1380年から続いたデンマーク・ノルウェー連合はこうして正式に終わった。見返りにスウェーデンは、ポンメルンの領土をデンマークに譲り、デンマークはさらにヘルゴラント島をイギリスに譲った。ノルウェーは条約に武力で抵抗して独自の憲法を宣言し、スウェーデンはこれを認めざるを得なかった——結果は、1905年まで続く人的連合(real union)となった。スウェーデンはノルウェーを実際に引き継げなかった。条約はノルウェーで受け入れられず、統治はクリスチャン・フレデリクの手にあり、スウェーデン軍がノルウェーに入ったのは1814年7月26日であった。", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["ウィーン会議最終議定書——ナポレオン後のヨーロッパ地図の再編", "fca1c676"], "d": ["ナポレオン戦争を終わらせた大国(オーストリア、ロシア、プロイセン、イギリス、フランス)の間で調印されたウィーン会議最終議定書は、1815年6月9日(ワーテルローの9日前)に採択され、大陸の地図を一括して引き直した。旧スペイン/オーストリア領ネーデルラントと連合州は「ネーデルラント連合王国」のもとに統合され、ジェノヴァ共和国はサルデーニャ-ピエモンテ王国に加えられ、ワルシャワ公国の大部分は「会議ポーランド」の名でロシアに結ばれ、スウェーデン領ポンメルン(シュトラールズント)はプロイセンに移った。この1日は、戦後のヨーロッパの均衡(ヨーロッパ協調)の正式な始まりとされる。この議定書により、ウッチ、チェンストホヴァ、キェルツェ、ラドム、ルブリン、ヘウム、ザモシチ(ワルシャワ公国)はロシアに属するポーランド王国に、ポズナン(ポーゼン大公国)はプロイセンに、マーストリヒトとルールモントはオランダ王国に移った。", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["一般海洋条約——カワーシムとその他の湾岸の首長国がイギリスとの条約に結ばれる", "fc499e19"], "d": ["イギリスは、1819年にラス・アル=ハイマを砲撃して「海賊」のカワーシム艦隊を壊滅させた後、1820年1月8日に始まり、地域の首長国と一つずつ調印されて3月までに完了した一般海洋条約を押しつけた。条約は海賊行為と奴隷制を禁じ、船がイギリス旗に似た赤と白の旗を掲げることを義務づけた。この条約により「海賊海岸」は時を経て「休戦海岸(Trucial Coast)」に変わった。1853年の恒久的な海上休戦と1892年の排他条約で深まったイギリスの覇権は、1971年まで続く関係の始まりであった。", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["ガエータ包囲の終わり——両シチリア王国の崩壊", "121ae580"], "d": ["ガリバルディの1860年5月のシチリア上陸に始まった崩壊の後、ナポリから逃れたブルボン家の王フランチェスコ2世は、最後の要塞ガエータで1860年11月3日から包囲された。フランス艦隊が1861年1月に地域から撤退したことでイタリアの海上封鎖が強まり、1861年2月13日にガエータは降伏した。フランチェスコ2世は王位を放棄して亡命した。両シチリア王国の最後の抵抗地点チヴィテッラ・デル・トロントは、1861年3月20日にようやく陥落することになる。王国の崩壊により、シチリア(パレルモ、メッシーナ、シラクーザ、トラーパニ、ミズィルメーリ)とカンパーニア(ノーラを含む)の土地はもはやブルボン家の統治下になかった。", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["イタリア王国の宣言——サルデーニャ、トスカーナ、南イタリアの統合", "12e52f70"], "d": ["イタリア議会がトリノで開いた最初の会期で、1861年3月17日にイタリア王国が正式に宣言され、サルデーニャ-ピエモンテ王ヴィットーリオ・エマヌエーレ2世が統一イタリアの最初の王となった。新王国は、前年に住民投票で加わったトスカーナ、エミリア-ロマーニャ、ナポリとシチリア(両シチリア)の土地をサルデーニャ王国と統合した。ローマ(教皇領)とヴェネツィア(オーストリア)はまだ外に残っていた——それぞれ1870年と1866年に加わることになる。", "d044a9c0"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["イギリスの北ソマリ沿岸での保護の確立——ソマリランドの始まり", "f301ea94"], "d": ["TDVのSomali項によれば、ゼイラ、ベルベラ、タージューラは1884年にイギリス人によってソマリランドの名で植民地化された。標準的な学術史料によれば、この過程はベルベラでヒジュラ暦1301年ラマダーン月21日(1884年7月14日)にあたる日にハバル・アワル部族と調印された条約で始まり、1884-1886年にガダブルシ、ハバル・トルジャアラ、ハバル・ゲルハジス、イーサ、ワルサンゲリの諸部族と同様の条約が結ばれて拡大した。イギリスは見返りに軍事的な保護を約束した。この一連の条約は、1887年に正式なイギリス領ソマリランド保護領が宣言される素地を整えた。", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["ムライダーの戦い——第二次サウード国の終わり、ナジュドがラシード家に移る", "1cd3b213"], "d": ["ザカートの紛争とラシード家の使者の逮捕により悪化した関係はついに、ジャバル・シャンマルのアミール、ムハンマド・ブン・ラシードの軍が、1891年1月21日にカスィーム地方のムライダーで、アブドゥッラフマーン・ブン・ファイサル率いるサウード軍とその同盟軍に大敗を与えるに至った。これは第二次サウード国の事実上の終わりとなり、アール・サウード家はクウェートに亡命し、ナジュドの全体がラシード家の支配に入った。南のディラム(ハルジュ)、ハウタ(ハウタト・バニー・タミーム)、ライラー(アフラージュ)の地域もその内にあった。支配は、1902年に若きアブドゥルアズィーズ・ブン・サウードがリヤドを取り戻すまで(リヤド急襲、1902年1月16日)続くことになる。", "b77d8161"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["イタリア領ソマリランドの国家の直接統治への移行——ベナディール会社の清算", "8c7d085b"], "d": ["TDVのSomali項によれば、イタリアは、南ソマリの沿岸(ベナーディル)における支配を1889-1891年にザンジバル・スルタン国とイギリスとの協定で築き、統治を当初は特許を持つ貿易会社(ベナディール会社)に委ねていた。標準的な学術史料によれば、この会社の特許は1905年1月24日に終わり、イタリア国家はベナーディル沿岸(モガディシュ、メルカ、バラウェを含む)の直接の主権を買い取って正式な植民地統治を築いた。植民地の内陸(バルデーラ、バイドア)に向けた実際の拡大は、1908年の設置勅令とその後の年に完成することになる。", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["ノルウェー・スウェーデン連合の解消——ストーティングの一方的独立宣言", "aaba2935"], "d": ["ノルウェー政府の別個の領事館設置の要求を国王オスカル2世が拒否し、新しい政府を組織できないと表明したことを受け、ノルウェーのストーティング(議会)は1905年6月7日に満場一致で、国王がもはや実際にノルウェー王として職務を果たしていないこと、1814年のキール条約以来続いた連合が解消されたことを決めた。1905年8月13日の国民投票で、有権者のほぼ全員(37万1000票対184票)が解消を承認した。スウェーデンは、カールスタード交渉の後、1905年10月26日に独立を正式に承認した。", "94eda38c"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["最初のオスマン朝のアクチェの鋳造", "38d2d638"], "d": ["オルハン・ガーズィーの名で鋳造された最初の銀のアクチェは、侯国の独立した主権の貨幣上の宣言である。アクチェは5世紀にわたり基本の貨幣単位であり続けた。", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["ルメリア・ベイレルベイリクの設立", "ffa16089"], "d": ["ヨーロッパ側の征服地が一つの軍事・行政の傘の下にまとめられた。ベイレルベイリクの体制は、帝国の地方組織の背骨となった。", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["イルドゥルム・バヤジトとデスピナ・ハトゥンの婚姻", "4b10dc6c"], "d": ["コソヴォの後にセルビア専制公国との間で築かれた従属関係は、ラザルの娘オリヴェラとバヤジトの婚姻によって固められた — 初期の婚姻外交の典型的な例である。", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["アナトリア・ベイレルベイリクの設立", "5ef8d3a7"], "d": ["併合された侯国の領土の統治のために、アナトリア・ベイレルベイリクが組織された。ルメリアとアナトリアの双翼の行政体制が完成した。", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["ブルサのウル・ジャーミィの完成", "27bcc4a5"], "d": ["ニコポリスの戦利品で建てさせた二十のドームを持つウル・ジャーミィは、初期オスマン建築の記念碑的な例であり、書道の野外博物館である。", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["チャンダルル・ハリル・パシャの罷免と処刑", "5e19438f"], "d": ["征服の後、包囲に距離を置いていた名門チャンダルル家出身の大宰相が処刑された。大宰相が初めてスルタンの命令で殺され、デヴシルメ出身の宰相の時代が開かれつつあった。", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["モルダヴィアの貢納化", "25bd3693"], "d": ["モルダヴィアのヴォイヴォダ領は貢納の支払いを受け入れた。ワラキア、トランシルヴァニアとともに、ドナウ北方の三重の従属地帯は、帝国の北の緩衝地帯となった。同じ日に加わったその他の地：Yaş。", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["ドゥブロヴニク（ラグーザ）の貢納", "d127c78a"], "d": ["商人共和国ラグーザは、貢納と引き換えに自治と通商特権を確保した。オスマン朝のアドリア海への窓として豊かになった。共和国の領土であるムリェト（Mljet）島も、この地位を共有した。", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["ワラキア遠征：串刺し公", "fd4530bb"], "d": ["貢納の支払いを拒み使者を殺したヴラド・ツェペシュに対して行われた遠征により、ワラキアは従属に戻された。夜襲と串刺しの恐怖の場面は、ヨーロッパで伝説となった。同じ日に加わったその他の地：Bükreş。", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["ファーティフ複合施設の開設", "a150ea55"], "d": ["八つのマドラサ（Sahn-ı Semân）を持つこの複合施設は、イスタンブルをイスラーム世界の学問の中心に変える計画の最初の大きな一歩であった。", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["アリー・クシュチュ、イスタンブルに", "8508229d"], "d": ["サマルカンド天文台の最後の大きな代表者アリー・クシュチュは、ファーティフの招きでアヤソフィア・マドラサの教授となった。イスタンブルに数学・天文学の伝統を築いた。", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["ファーティフ・カーヌーン・ナーメ", "b08944c9"], "d": ["国家の機構、儀礼、刑罰をまとめた最初の包括的な慣習法典。「世界の秩序のために」兄弟殺しを許可する有名な条項をめぐって、議論が続けられてきた。", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["最初のオスマン朝の金貨（スルターニー）の鋳造", "2fd5c0dd"], "d": ["ヴェネツィアのドゥカートに相当する最初のオスマン朝の金貨が鋳造された。帝国の財政は国際的な貨幣秩序に加わった。", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["トプカプ宮殿への移転", "b9cd6a5e"], "d": ["新宮殿（トプカプ）の完成により、国政の中心はここに移った。宮殿は4世紀にわたり帝国の頭脳であり続けた。", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["フィレンツェ共和国が公国に転換 — アレッサンドロ・デ・メディチ", "c08764e1"], "d": ["教皇クレメンス7世の圧力により、フィレンツェの統治委員会（バリーア）は新しい憲法を採択した。5世紀続いた共和政体は廃され、アレッサンドロ・デ・メディチが世襲の公と宣言され、5月1日に事実上即位した。フィレンツェはこうして、独立した都市共和国からメディチ家の世襲の公国に転換した。", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["カーヌーニーとヒュッレム・スルタンの婚姻", "abc05f26"], "d": ["カーヌーニーがヒュッレムと正式な婚礼を挙げたことは、宮廷の慣習を根本から変えた。「ハセキ・スルタン」の制度が生まれ、王朝政治における女性の時代の扉が開かれた。", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["フランスへの最初の包括的なカピチュレーション", "e2264e48"], "d": ["ハプスブルクの挟撃に対するフランスとの同盟の一環として、ジャン・ド・ラ・フォレとマクブル・イブラヒム・パシャの間で通商上の特権が調印された。その日には外交の手段であったカピチュレーションは、世紀を重ねるうちに財政的従属への扉となることになった。", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["インド洋遠征：ディウ包囲", "fcd1217a"], "d": ["スエズから出た艦隊は紅海を越えてグジャラートのディウを包囲した。城塞は取れなかったが、オスマン朝の力は初めてインド洋に及び、ポルトガルの独占は揺らいだ。", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["スィーディー・アリー・レイスのインドへの旅", "e5da3b2c"], "d": ["バスラの艦隊をエジプトに連れ帰る任務を負ったスィーディー・アリー・レイスは、嵐によりインドに流された。帰途の冒険を語った『諸国の鏡（Mir'âtü'l-memâlik）』は、最初のオスマン朝の旅行記の一つである。", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["ピーリー・レイスの処刑", "63026444"], "d": ["ホルムズ遠征から艦隊をバスラに残して戻った大航海者・地図製作者は、84歳で処刑された — わが国の科学史における最も議論のある決定の一つである。", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["スレイマニエ複合施設の開設", "1c6458b2"], "d": ["建築家シナンが「見習い（カルファ）の作品」と呼んだこの複合施設は、マドラサ、病院（ダールッシファー）、図書館を備え、古典期最大の教育・慈善の複合体となった。", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["マルタ包囲", "f57f6a85"], "d": ["地中海の鍵であるマルタは四か月包囲された。トゥルグト・レイスは戦死し、包囲は解かれた。カーヌーニー時代の海軍にとって最初の大きな後退となった。", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["セリミエ・モスクの完成", "3b0484e1"], "d": ["シナンが「親方の作品」と呼んだ、単一のドームが空間を支配するセリミエは、オスマン古典建築の頂点とみなされる（ユネスコ世界遺産）。", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["イスタンブル天文台の設立", "169bdf5d"], "d": ["タキユッディーンの、当時最も設備の整った観測所の一つであった天文台は、1577年の彗星の後に起きた論争により1580年に破壊させられた。制度としての天文学は3世紀遅れた。", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["チュルドゥルの勝利 — 東方戦争の開始", "13125a54"], "d": ["サファヴィー朝の軍がチュルドゥル（Çıldır）で敗れたことで、カフカースの門が開かれた。トビリシが取られ、ジョージアはオスマン朝の支配下に入った。", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["松明の戦い — シルヴァンが決定的にオスマン朝に", "3bbc23bc"], "d": ["夜の松明の灯りの下でも続けられたためこの名で呼ばれる戦いで、サファヴィー朝は決定的に敗れた。シルヴァンとバクーにおけるオスマン朝の支配は固められた。", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["大悪貨改鋳 — アクチェの危機", "9205c3d4"], "d": ["長期の戦争とアメリカ大陸の銀の圧力により、アクチェの銀の含有量は半分に引き下げられた。価格革命は、シパーヒー制の解体とジェラーリーの混乱を助長した。", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["タブリーズの征服", "6506bdb9"], "d": ["セルダール・オズデミロウル・オスマン・パシャはタブリーズに入った。サファヴィー朝の旧都はオスマン朝の統治下に置かれた。オスマン・パシャは数週間後に陣営で崩御した。", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["フェルハド・パシャ条約 — 東方における最大の国境", "c429972f"], "d": ["シャー・アッバースの使節ハイダル・ミールザーのイスタンブル到着（1590年1月18日）の後、征服した地がオスマン朝に残ることを条件に結ばれ、12年に及んだ戦争を終結させた条約により、タブリーズ、カラバフ、シルヴァン、ジョージア、ルリスタンがオスマン朝に残った。帝国は東方で、歴史上最大の国境に達した。", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["オスマン＝サファヴィー戦争（1603〜1612年）の開始 — シャー・アッバースの反攻、タブリーズの喪失", "abf27dd8"], "d": ["軍を再編したシャー・アッバースは、ジェラーリーの混乱に乗じて攻勢に転じた。タブリーズは陥落し、カフカースでの獲得地は数年のうちに失われた。同じ遠征とその後に失われたその他の集落：Nahçıvan, Hoy, Merend, Selmâs。Karacadağ (Ahar) とムクリーの諸侯もサファヴィー側に戻った。", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["エヴリヤ・チェレビーの誕生", "2b6051ff"], "d": ["五十年を超える旅を十巻の『旅行記（セヤハトナーメ）』にまとめたエヴリヤ・チェレビーは、17世紀のオスマン世界の比類のないパノラマを残した。", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["ナスーフ・パシャ条約", "bb69e388"], "d": ["1603年から続いた戦争を終結させた条約により、1590年の獲得地は放棄され、1555年のアマスヤの国境に戻った。東方戦線で均衡が再び築かれた。", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["スルタンアフメト・モスクの開堂", "e39dfd43"], "d": ["六本のミナレットと青いイズニクのタイルをもつ「ブルーモスク」は、古典期最後の大きなスルタンの複合施設である。", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["スルタン・イブラヒムの殺害", "bc4eb452"], "d": ["浪費と統治の行き詰まりを理由に、軍団とウラマーの同盟はイブラヒムを廃位した。十日後にファトワーにより絞殺された。七歳のメフメト4世が即位し、権力は事実上、大母后キョセム・スルタンの手に移った。", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["キャーティブ・チェレビーの死", "e167e89d"], "d": ["書誌『諸学の疑念の解明（Keşfü'z-zunûn）』と地理書『ジハーンヌマー』でオスマンの学問史の頂点に立つ人物。ヨーロッパの文献を用いる先駆的な手法で知られる。", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["エディルネ事件 — ムスタファ2世の廃位", "0291c1cd"], "d": ["スルタンがエディルネに居住したことと、フェイズッラー・エフェンディの権勢への怒りが、軍と商工業者の大蜂起に発展した。シェイヒュルイスラームはリンチされ、スルタンは廃位され、宮廷はイスタンブルに戻った。", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["パリへの大使：ユルミセキズ・メフメト・チェレビー", "26312a3f"], "d": ["フランスに送られた大使節は、西欧を現地で調べた最初の体系的な観察となった。その『使節記（Sefâretnâme）』はチューリップ時代の刷新に着想を与えた。", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["最初のオスマン朝の印刷所の設立", "4943f7e5"], "d": ["トルコ語の書物を印刷する許可が与えられた。最初の著作『ヴァンクル辞典』は1729年に印刷された。印刷所は、チューリップ時代の刷新の最も永続的な遺産である。", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["カピチュレーションの恒久化", "d044a79e"], "d": ["フランスに与えられた特権はスルタン一代に限られるものではなくなり、恒久的な条約に結びつけられた。一方的に廃棄できなくなったカピチュレーション体制は、ローザンヌでようやく廃止された。", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["帝国海軍工学校の設立", "9bf3f439"], "d": ["チェシュメの惨事の後に近代的な海軍士官を養成するために設立された工学校は、西洋式の技術教育の最初の恒久的な機関である。陸軍の工学校は1795年に続いた。", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["ロンドンの最初の常駐大使館", "6b5630eb"], "d": ["ニザーム・ジェディード計画の一環として、ヨーロッパの首都に常駐大使館が開かれた。オスマン外交は相互主義の原則に移った。", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["アレムダル・ムスタファ・パシャの死", "4426534e"], "d": ["1808年11月15日の夜に始まったイェニチェリの蜂起で、バーブ・アーリーで包囲された改革派の大宰相は、期待した援軍が来なかったため、翌日に火薬庫に火をつけ、数百人の攻撃者とともに死んだ。同盟の誓約書（セネディ・イッティファーク）の体制と最初の改革の試みは、彼とともに葬られた。", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["最初の官報：Takvîm-i Vekāyi", "c637f623"], "d": ["国家の官報の発行が始まった。近代的な世論と公式の通達の伝統の始まりである。", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["バルタ・リマヌ通商条約", "e790b383"], "d": ["イギリスには国内取引においてさえ最も特権的な地位が認められ、専売（イェド・イ・ヴァーヒド）の制度は廃止された。国産の生産が無防備となる中で、この条約はオスマン市場が自由貿易に完全に開かれた文書となった。", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["レバノン首長国の終わり — ベシール・シハーブ3世の解任", "f85ae454"], "d": ["キリスト教徒とドルーズ派の対立とシューフ地方の内部の均衡を制御できなかった首長ベシール2世（3世）は、1842年1月に解任された。1516年から（マアン家、続いてシハーブ家の手によって）続いた地方の首長国の体制は終わり、地域は直接のオスマン朝の統治に、続いて二重のカイマカム制に移った。", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["貨幣改革（Tashîh-i sikke）：メジディイェ体制", "c77be809"], "d": ["貨幣改革により品位の悪化した貨幣が回収され、金リラ（メジディイェ）を基礎とする安定した金銀複本位制が確立された。", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["バールベックにおけるハルフーシュ家の地方支配の終わり", "8438f4ae"], "d": ["1521年から（ジャンビルディー・ガザーリーの反乱の後）バールベックで小さな地方王朝として支配してきたハルフーシュ家の勢力は、バーブ・アーリーの新しい行政の整備によって終わった。都市はダマスクス州に属する平凡な郡の中心とされた。", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["シルケティ・ハイリイェ（Şirket-i Hayriyye）の設立", "462830e7"], "d": ["ボスポラス海峡で蒸気船を運航するために設立された会社は、最初のオスマン朝の株式会社とみなされる。都市の生活には蒸気船の桟橋が刻印された。", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["最初の対外債務契約", "9017c579"], "d": ["クリミア戦争の資金のために、ロンドン市場から最初の対外借款が受けられた。21年間で15回の借入を重ねて至った地点は、1875年のモラトリアムとデュユーン・ウムーミイェであった。", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["電信線のイスタンブルへの到達", "d320f39f"], "d": ["クリミア戦争の必要から敷設された最初の電信線が運用に開かれた。帝国は数十年のうちに、世界で最も広い電信網の一つを手にした。", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["土地法（アラズィ・カーヌーン・ナーメ）", "6bae243a"], "d": ["土地法を近代化した法典は、国有地（ミーリー）における事実上の処分権を地券に結びつけた。今日の中東の所有秩序の基礎文書の一つである。", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["ダールルフュヌーン（Dârülfünun）での最初の講義", "08f74066"], "d": ["大学レベルの教育を行うダールルフュヌーンが、公開講義で活動を始めた。中断を挟みつつ続いた機関は1900年に恒久的に開設され、イスタンブル大学の核となった。", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["州制規則（ヴィラーイェト・ニザームナーメ）", "ad20853b"], "d": ["エヤレット制に代えて、フランスの模範に基づく州（ヴィラーイェト）の組織が築かれた。ミドハト・パシャのドナウ州での実施を手本として、全国に広められた。", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["アブデュルアジズのヨーロッパ旅行", "9ff0fa1e"], "d": ["オスマン朝のスルタンによる、平和を目的とした最初のヨーロッパ旅行。パリ万博とロンドン訪問は、外交と近代化の両方の陳列窓の役割を果たした。", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["ガラタサライ帝国学院の開設", "f9688524"], "d": ["フランス語で教育を行う高等学校は、宗教や民族の区別をしない学生構成によって、タンジマートの教育における平等の理想の象徴となった。", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["メジェッレ（Mecelle）の最初の巻の施行", "6475461c"], "d": ["イスラーム法の債務・物権の分野を近代的な法典の技法でまとめたメジェッレは、最初のイスラーム民法典とみなされる。ジェヴデト・パシャを長とする委員会は、16巻を1876年に完成させた。", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["アブデュルアジズの廃位", "eb7397ea"], "d": ["立憲派の政治家と軍の高官たちは、静かなクーデターでアブデュルアジズを廃位した。五日後の不審な死と、続いて起きたチュラーン事件は、数年続く清算を生んだ。", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["チュラーン襲撃（アリ・スアヴィ事件）", "d2a9ac87"], "d": ["ジャーナリストのアリ・スアヴィは、ムラト5世を再び即位させるためにチュラーンを襲撃した。襲撃は血なまぐさく鎮圧され、アブデュルハミト体制は警備の環を恒久的に強化した。", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["レジ管理局の設立（煙草専売）", "bad9b030"], "d": ["煙草の収入は、デュユーン・ウムーミイェの下にある外国資本のレジ会社に譲渡された。農民と監視人（コルジュ）の間の「レジ密輸」をめぐる衝突は数十年続いた。同じ日に失われたその他の集落：Zeyla。", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["皇帝ヴィルヘルム2世のイスタンブルとエルサレムの訪問", "2988cd06"], "d": ["ドイツ皇帝の二度目の訪問は、オスマン＝ドイツの接近を固めた。バグダード鉄道の利権への道が開かれ、ダマスクスで「三億人のムスリムの友」の演説が行われた。", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["ヒジャーズ鉄道のメディナへの到達", "95009b9c"], "d": ["ムスリムの寄付と国内の工学のみで築かれた1464 kmの路線がメディナに達した。巡礼の旅は数週間から数日に短縮された。アブデュルハミト2世の時代の最大のインフラの事業である。", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["3月31日事件", "1d7c2bb2"], "d": ["立憲政に反対する大規模な蜂起はイスタンブルを掌握した。テッサロニキから来た行動軍が反乱を鎮圧し、アブデュルハミト2世は廃位された。", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["エディルネ包囲の開始", "234d9b28"], "d": ["シュクリュ・パシャの五か月に及ぶ防衛は、バルカンの破局の中の抵抗の叙事詩となった。都市は飢えにより陥落し、1913年7月に取り戻された。", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["バーブ・アーリー襲撃", "b304d02d"], "d": ["エディルネの引き渡しの準備をしていた政府は、統一派の武装襲撃により倒された。陸軍大臣ナーズム・パシャは殺された。統一と進歩委員会の完全な支配の時代が始まった。", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["レバノン山ムタサッルフ領の廃止", "b5639051"], "d": ["1861年の組織規程（Reglement Organique）によって設けられ、1864年に更新された国際的な議定書に基づく自治のムタサッルフ領の体制は、第一次世界大戦中にオスマン国家によって一方的に破棄された。内務省は地域に直接ムスリムのムタサッルフを任命し始めた。1861〜1915年の間に八人のムタサッルフが務めた自治の時代は、こうして閉じた。", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["王子たちの間での国の分割", "82f26bfb"], "d": ["アンカラの敗走の後、スレイマン・チェレビはルメリアに渡ってエディルネでスルタン位を宣言した。イーサー・チェレビはブルサを、チェレビ・メフメトはアマスヤ＝トカト＝シヴァスの地域を保った。地図ではこの三つの分け前は別々の色で示される。", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["ゲリボル協定：ミシヴリまでの黒海沿岸がビザンツに譲られる", "a4164eca"], "d": ["アンカラの敗走の後ルメリアで持ちこたえようとしたエミール・スレイマンは、ゲリボルでビザンツ皇帝マヌエルと協定に調印した。Kartal、Pendik、Gebze といくつかの島、ルメリアのテッサロニキとテッサリア、黒海ではミシヴリ（Misivri）まで延びる沿岸の帯をビザンツに譲り、ビザンツがオスマン朝に支払っていた税も廃止された。ストランジャ沿岸の Ahtapolu、İğneada、Rezve はこうして二十一年間ビザンツの統治下に残った。ムラト2世は1424年の和平でこれらの地の多くを取り戻した。", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["イルドゥルム・バヤジトの捕囚中の死", "7e968d83"], "d": ["ティムールの手で捕らわれていたスルタンはアクシェヒルで崩御した。遺体はブルサに運ばれて埋葬された。その死は、王子たちの間の王位争いを後戻りできないものとした。", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["ゲリボル協定 — ビザンツへの譲歩", "dfacbd00"], "d": ["ルメリアでの立場を確保しようとしたスレイマン・チェレビは、ビザンツとラテン人の諸国と協定を結んで、テッサロニキ、マルマラ沿岸、いくつかの島を返還し、貢納の支払いさえ受け入れた。", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["ウルバトの衝突 — イーサー・チェレビの敗北", "500c5d24"], "d": ["ブルサを保持していたイーサー・チェレビは、弟メフメトにウルバトで敗れた。何度かの立て直しの試みも成果を挙げなかった。", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["イーサー・チェレビの消滅", "0effa11e"], "d": ["スレイマン・チェレビの支援で何度かアナトリアに戻ったイーサー・チェレビは、最後の敗北の後に姿を消した。その分け前はチェレビ・メフメトに移り、地図ではメフメトの領域が西に広がった。", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["ムーサー・チェレビがワラキアに渡る", "8441267a"], "d": ["スレイマン・チェレビに対してブルサとアンカラを失いトカト＝アマスヤに退いたチェレビ・メフメトは、弟ムーサーにルメリアへ行くよう促した。ムーサーはワラキアのヴォイヴォダ、ミルチャの招きを受け入れて海路でワラキアに達した。ここからスレイマンを二つの戦線の間に挟む闘争に踏み出すことになる。", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["チェレビ・メフメトがブルサとアンカラを再び取る — アナトリアの分け前がスレイマン・チェレビから離れる", "bfb69f12"], "d": ["ムーサー・チェレビのルメリアでの成功（ヤンボル、1410年2月13日）を受けて、アナトリアにいたエミール・スレイマン・チェレビはルメリアに渡った。スレイマンのアナトリアからの離脱の後、メフメト・チェレビはアンカラを含むブルサ周辺を再び掌握し、即位の印としてヒジュラ暦813年の貨幣を鋳造させた。地図ではマルマラのアナトリア側は、エミール・スレイマンの分け前からチェレビ・メフメトの色に移る。", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["コスミディオンの戦い", "0efc2caa"], "d": ["ビザンツの支援を得てイスタンブルの城壁の前で行われた戦いで、スレイマン・チェレビは弟ムーサーを破った。しかしルメリアでの彼の支持は急速に崩れ始めていた。", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["ムーサー・チェレビのコンスタンティノープル包囲", "4932f586"], "d": ["スレイマンを支援したビザンツを罰しようとしたムーサー・チェレビは、コンスタンティノープルを包囲した。この包囲はビザンツをチェレビ・メフメトとの同盟へと押しやった。", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["エミール・スレイマンの死 — ムーサーがルメリアを支配", "325c1549"], "d": ["エディルネから逃げる途中で捕らえられたスレイマン・チェレビは殺された。ルメリアの全体はムーサー・チェレビの手に渡った。地図ではルメリアは青色から紫色に変わる。", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["チャムルルの戦い — 統一の再建", "0b23173e"], "d": ["ビザンツ、セルビア専制公国、ルメリアの諸侯の支援を得たチェレビ・メフメトは、弟ムーサーをチャムルルで決定的に破った。ムーサーは逃走中に殺された。ムーサーの手にあったルメリアはエディルネとともにメフメトに移り、メフメト・チェレビはエディルネで自らをオスマン国家の唯一の君主と宣言した。十一年続いた空位時代は終わり、地図上の王子たちの分け前は一つの体に統合された。", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["ウィーン遠征の決定 — ヴァシュヴァール和約は更新されず、目標はジェールからウィーンに変更された", "1bf278f2"], "d": ["皇帝レオポルト1世はまだ期限の切れていないヴァシュヴァール条約の更新を望み、メフメト4世も和平に傾いているように見えた。しかし大宰相メルズィフォンル・カラ・ムスタファ・パシャは、中部ハンガリー王に宣言させたテケリ・イムレの不満を理由に和約を更新させなかった。ヴァーニー・メフメト・エフェンディをはじめとする説教師を動かして、スルタンを戦争に説得した。行われた協議で、スルタンはベオグラードに留まり、総司令官はジェール（Yanıkkale）を取るべく進むことが決められた。しかしベオグラードでの協議で、クリミア・ハンのムラト・ギレイとブダ総督ウズン・イブラヒム・パシャの反対にもかかわらず、目標はウィーンの包囲に変更された。", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["第2次ウィーン包囲の開始 — 軍がウィーンの前に", "bb542e49"], "d": ["大宰相カラ・ムスタファ・パシャの指揮するオスマン軍は、1683年7月14日にウィーンの前に到着した。皇帝レオポルト1世は都市の守備をシュターレンベルクに任せてオーストリアの内地に退いた。最初のものとは異なり、直接ウィーンを標的として準備されたこの二度目の包囲は、9月12日まで続くことになった。", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["パルカーニの敗走とエステルゴムの喪失", "a7366740"], "d": ["ウィーンから退いた軍はパルカーニ（Parkan）で二度目の敗走を喫した。続いてハンガリーの要衝の城塞エステルゴムが陥落した。撤退は崩壊へと変わり始めた。", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["メルズィフォンル・カラ・ムスタファ・パシャの処刑", "ce8b10ac"], "d": ["ウィーンの敗走の責任者とされた大宰相はベオグラードで絞殺された。しかしその処刑は戦線を立て直しもせず、揺らいだ国家の威信を取り戻しもしなかった。", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["神聖同盟の結成", "060280d0"], "d": ["教皇庁の主導で、オーストリア、ポーランド、ヴェネツィアの間でオスマン朝に対する神聖同盟（ムカッデス・イッティファーク）が結成された。1686年にはロシアも加わった。こうして帝国は十六年続く多戦線の戦争に入った。", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["第1次ブダ防衛", "ccc43630"], "d": ["神聖同盟軍の最初のブダ包囲は、四か月続いた城塞の粘り強い防衛によって退けられた。しかしハンガリーの城塞は一つまた一つと落ち続けていた。", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["ノヴェー・ザームキの喪失", "689ab78c"], "d": ["二十二年間オスマン朝の手にあり、ヨーロッパで諺となったノヴェー・ザームキ城塞が陥落した。上ハンガリーにおけるオスマン朝の存在は解体した。", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["テケリのヴァラドでの逮捕 — 中部ハンガリー王国は解体、上ハンガリーの城塞は降伏", "1741aaaf"], "d": ["ウィーンの敗走の後、オスマン朝はテケリも戦争と敗北をもたらした者の一人とみなし始めていた。1685年10月15日、総司令官メレク・イブラヒム・パシャの命令によりヴァラドのベイレルベイ、アフメト・パシャは、援軍に来たテケリを捕らえさせた。彼をハプスブルクに引き渡すことでより良い和平の条件を得られると期待された。逮捕の知らせが広がると、妻ズリーニ・イロナが守るムンカーチを除き、中部ハンガリー王国のすべての城塞と都市がハプスブルクに降伏した。クルツ（反ハプスブルク）兵の多くはハプスブルク軍に移った。テケリが1686年1月2日にベオグラードで釈放されたとき、王国はもはや消滅していた。", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["ブダの喪失 — 145年続いたハンガリーの首都", "70800e2b"], "d": ["七十八日間続いた包囲の末にブダは陥落し、最後のベイレルベイ、アブドゥッラフマーン・アブディー・パシャは城壁で殉教した。1541年からオスマン朝の統治下にあった都市の喪失は、ハンガリーの喪失の象徴とされる。同じ日に失われたその他の集落：Peşte。", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["第2次モハーチ（ハルシャーニ）の敗走 — トランシルヴァニアとモハーチの喪失", "a7922681"], "d": ["1526年に大勝利を収めた平野で、今度は大敗を喫した。軍は崩れ、反乱した兵士たちは大宰相を罷免させた。敗北はトランシルヴァニアの喪失をも招いた。", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["アテネの喪失とパルテノンの爆発", "b6691730"], "d": ["ヴェネツィアの砲兵が放った榴弾が、オスマン朝が火薬庫として用いていたパルテノンを爆破した。二千年の神殿は廃墟となった。都市はヴェネツィアの手に渡った（1688年に取り戻されることになる）。", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["メフメト4世の廃位とスレイマン2世の即位", "9f53037c"], "d": ["戦線の惨事と軍の反乱を受け、39年の治世の末にメフメト4世は廃位された。代わりに四十年間籠（カフェス）に置かれていた弟のスレイマン2世が据えられた。", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["ベオグラードの最初の喪失 — 神聖同盟の包囲", "c6b9b19a"], "d": ["1521年からオスマン朝の手にあったベオグラードは神聖同盟軍に降伏した。セルビアの門は敵に開かれ、危険はニシュ＝ソフィアの線に迫った。同じ日にアトラスでオスマン朝からハプスブルクに移ったその他の集落：Hisarcık (Grocka) — ベオグラードの兄貴分中心地の連鎖に従う（TDV belgrad；申告付きの近似）。", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["バーデンがポジャレヴァツの前でモラヴァ川を渡る — ポジャレヴァツがオーストリアの手に落ちる", "bcf3fc59"], "d": ["辺境伯ルートヴィヒ・フォン・バーデンは1689年8月にポジャレヴァツでモラヴァ川を渡ってニシュの方向へ進んだ。都市は1690年の夏までオーストリアの手に残った（TDV suleyman-ii は1690年にポジャレヴァツが取り戻されたと述べる）。日付と Röder の読みは、この作業では再確認されていない。", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["ニシュの喪失 — ハプスブルク（ハンガリー王冠）の進出、最も危機的な年", "c5e27b3f"], "d": ["ハプスブルク（ハンガリー王冠）の進出はニシュもオスマン朝の統治から奪った。襲撃はスコピエとプリシュティナにまで及んだ。ヴィディンはこの後、1689年10月に陥落した（別項）。戦争の最も暗い年に、国家は首都さえ脅威にさらされていると感じた。", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["オルショヴァとフェトヒュルイスラームがオーストリアの守備隊に入る", "ee8dd875"], "d": ["ヴィディンが戦わずして取られた（1689年10月、TDV vidin）後、バーデンは1689年10月25日にオルショヴァとフェトヒュルイスラームを修復して守備隊を置いた。オルショヴァは1690年の秋までオーストリアに残った。日付は Bánlaky/Röder に基づき、この作業では再確認されていない。", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["ニシュが再びオスマン朝に", "0c4f44eb"], "d": ["ファーズル・ムスタファ・パシャは1690年7月に遠征に出た。Şehirköy、ポジャレヴァツ、Güvercinlik が取られた後、包囲されたニシュは1690年9月27日にオスマン朝の手に渡った（TDV semendire）。同じころヴィディンも取り戻されていた。同じ日にアトラスでハプスブルクからオスマン朝に戻ったその他の集落：Yagodina (Jagodina) と Ürküp (Prokuplje) — 地点ごとの日が見つからないため、ニシュの日が取られた（TDV semendire；申告付きの近似；Röder 1842 は宰相が9月8日〜24日にヤゴディナを通過したと記すが、矛盾は解消されていない）。", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["スメデレヴォでオーストリア軍が降伏", "90da20c4"], "d": ["ニシュが1690年9月27日に取られた後、四日間の包囲でスメデレヴォのオーストリア軍が降伏した（TDV semendire）。Bánlaky/Röder は9月24日とするが、史料は矛盾しており、TDVが採られた。", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["ベオグラードの奪回", "ab435838"], "d": ["大宰相キョプリュリュザーデ・ファーズル・ムスタファ・パシャは1690年10月8日にベオグラードをオーストリアから取り戻した。1688年に失われた都市はこうしてオスマン朝に戻った（TDV suleyman-ii）。同じ日にアトラスでハプスブルクからオスマン朝に戻ったその他の集落：Hisarcık (Grocka) — ベオグラードの兄貴分中心地の連鎖に従う（TDV suleyman-ii；申告付きの近似）。", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["スランカメンの敗走 — ファーズル・ムスタファ・パシャの殉教", "10d626f1"], "d": ["世紀で最も血なまぐさい会戦の一つで、大宰相は額を撃ち抜かれて殉教した。軍は崩れた。立て直しの望みはこの戦いとともに消えた。", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["キオス島の喪失", "07c084f8"], "d": ["ヴェネツィア艦隊はキオスを占領した。エーゲ海におけるオスマン朝の支配は脅威にさらされた。島は翌年に取り戻されることになる。", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["ムスタファ2世の自ら出征する決定", "61c3ba9c"], "d": ["新しいスルタンは、祖先の道を歩んで軍の先頭に立って出征すると宣言した。この決定は軍の士気を生み、二年続く親征の時代を始めた。", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["キオスの奪回", "6b496fca"], "d": ["オイヌセス諸島の海戦でヴェネツィア艦隊を破ったメゾモルト・ホセイン・パシャは、キオスを取り戻した。オスマン海軍における短い復活の兆しとなった。", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["ルゴイの勝利 — ムスタファ2世の最初のオーストリア遠征", "d5ee9b34"], "d": ["スルタンが自ら参加した最初の遠征で、リポヴァが取り戻され、ルゴイでオーストリア軍が敗れた。長年続いた敗北の連鎖で、最初の切れ目が生じた。アトラスは Karánşebeş (Caransebeş) もこの遠征でハプスブルクからオスマン朝に戻ったものとみなす。史料は1695年9月とだけ記し（TDV mustafa-ii）、アトラスの日はルゴイの記録から取られた（申告付きの近似）。", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["アゾフ城塞の喪失", "2b78b5cd"], "d": ["黒海への進出を目指すピョートル1世は、二度目の包囲でアゾフを取った。ロシアは初めてオスマン朝の城塞に恒久的に定着し、海軍力となる道への最初の一歩を踏み出した。", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["ウラシュ（Olaşin）の勝利", "02ac9ca8"], "d": ["スルタンの二度目の遠征でドナウ河畔で収められた勝利は、オーストリアのティミショアラ奪取の計画を挫いた。しかし戦争の全体的な均衡は変えなかった。", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["ゼンタの敗走 — 戦争の行方が決まる", "475c4a7b"], "d": ["軍はティサ川を渡る途中でオイゲン公の急襲を受けた。川の両岸に分断された部隊は数時間で壊滅し、大宰相エルマス・メフメト・パシャをはじめ数千の兵と政治家が死んだ。オスマン史上最も重い敗走の一つであるゼンタは、和平の席を避けられないものとした。", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["カルロヴィッツ和平交渉の開始", "1f395cf3"], "d": ["イギリスとオランダの仲介で始まった交渉で、オスマン朝の代表団は初めて「uti possidetis」（保有しているものは保持される）の原則を受け入れざるを得なかった。七十二回の会議に及んだ交渉は、近代オスマン外交の誕生とみなされる。", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["カヴァラのメフメト・アリーがエジプトに上陸", "514c943f"], "d": ["フランスの占領下にあるエジプトを取り戻すために派遣されたオスマン軍の中には、カヴァラで集められた志願兵の部隊もあった。三十代のメフメト・アリーはこの部隊の副指揮官であった。エジプトには総督としてではなく、一中隊の将校として足を踏み入れた。", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["アルバニア兵がエジプト総督を倒す", "c76a0ec2"], "d": ["俸給の支払われなかったアルバニア人の部隊が蜂起し、総督フスレヴ・パシャを城塞から逃げざるを得なくさせた。フランス軍の撤退で生じた空白の中で、キョレメンの諸侯、アルバニア人の軍団、バーブ・アーリーの任命する総督たちは三つ巴の闘争に入った。メフメト・アリーはこの三角の中で均衡を取って頭角を現した。同じ日に失われたその他の集落：Tâif。", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["カイロのウラマーがメフメト・アリーを総督と宣言", "a16752f2"], "d": ["税の圧力に苦しんだカイロの商工業者とウラマーは、ナキーブ・ル・アシュラーフのウマル・マクラムの指導のもとで蜂起し、総督フルシド・パシャを認めないと表明して、メフメト・アリーを総督の座に就けた。オスマン史において総督が民衆によって選ばれたことは、まれな出来事である。", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["バーブ・アーリーが既成事実を受け入れる：エジプト総督の勅令", "b86736a3"], "d": ["エジプトで自らの候補を押し立てる力のなかったバーブ・アーリーは、メフメト・アリーに宰相の位とともにエジプト総督の勅令を送った。地図ではエジプトはこの日付から従属（薄い色調）の層に移る。法的にはオスマン領だが、事実上はカヴァラ王朝の国である。同じ日に従属の層に移ったその他の集落：Kahire, İskenderiye, Dimyat, Asyut, Asvan, İbrim, Süveyş, Reşîd (Rosetta)。", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["イギリスのフレイザー遠征軍がアレクサンドリアに上陸", "4d6c31be"], "d": ["オスマン朝がフランスに接近したことへの報復として、イギリスはエジプトに上陸部隊を送った。メフメト・アリーはそのとき上エジプトでキョレメンと争っていたが、急ぎ戻って防衛を組織した。", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["ロゼッタ（Reşid）の敗走 — イギリス軍の撃退", "3636004c"], "d": ["レシド（ロゼッタ）の町に入ったイギリス軍の部隊は、市街戦で大きな損害を出した。9月には部隊がエジプトから完全に撤退した。この勝利は、メフメト・アリーのエジプトとイスタンブルの両方での威信を固めた。", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["カラ事件：キョレメンの諸侯の一掃", "84030b97"], "d": ["ヒジャーズ遠征のために催された式典の行列に招かれたキョレメンの諸侯は、カイロ城塞の狭い通路で閉じ込められて排除された。5世紀続いたキョレメンの勢力はこうして終わり、エジプトでメフメト・アリーの前に競争相手はいなくなった。", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["ヒジャーズ遠征の開始 — 軍はスエズから海路で、巡礼路から陸路でヤンブーへ進んだ", "1c05c159"], "d": ["1803年からサウード＝ワッハーブ派の支配下にあった両聖都を取り戻すことは、マフムト2世にとって最大の正統性の問題であった。バーブ・アーリーの力が及ばなかったため、任務はエジプト総督に与えられた。メフメト・アリーは十六歳の息子トスンを軍の先頭に立てて送った。", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["ヤンブーの占領 — ヒジャーズ遠征の最初の沿岸拠点", "179bc78d"], "d": ["スエズから新造の船で出発した二千人ほどのアルバニア歩兵は、1811年10月にヤンブー近くに上陸した。町は二日間の弱い抵抗の後に降伏した。トスンの指揮する騎兵は巡礼路を陸路でたどり、アカバとワジュフ経由で二週間後になってようやくヤンブーに達した。ヤンブーは、メディナとメッカへ進軍するエジプト軍のヒジャーズでの最初の拠点となった。", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["サフラ・ジェディーダの隘路での最初の敗走", "99ef804d"], "d": ["狭い山の隘路で待ち伏せされたエジプトの先鋒部隊は壊滅した。この敗北は遠征の戦術上の教訓となった。ベドウィンの部族の支持を得ずにヒジャーズを進むことは不可能であると分かった。", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["メディナの奪回", "6f6a5d55"], "d": ["長い包囲の後、メディナは降伏した。預言者の都市の奪回はイスタンブルで礼砲の祝賀で祝われ、メフメト・アリーには褒賞としてジェッダ総督の地位も与えられた。", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["メッカの奪回 — 巡礼路の開通", "3d6d66a0"], "d": ["メッカに入ったエジプト軍は、カアバで再びオスマン朝のスルタンの名でフトバを読ませた。十年間途絶えていた巡礼団が再び出発できるようになった。地図ではヒジャーズはオスマン朝の支配に戻るが、統治がカイロにあるため従属の色調で示される。同じ日に従属の統治に移ったその他の地：Cidde。", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["ターイフの奪回 — ヒジャーズ遠征の完了", "6315fb31"], "d": ["メディナ（1812年12月）とメッカ（1813年1月）の後、トスン・パシャの指揮するエジプト軍は最後にターイフをワッハーブ派から取り戻した。十年続いたサウード家の支配は終わり、ヒジャーズの三つの聖なる中心も再びオスマン＝エジプトの管理下に入った。", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["メフメト・アリー自らがヒジャーズに渡る", "fda0ea2d"], "d": ["遠征がゆっくり進んでいるのを見た総督は、統治を直接自らの手に取った。部族の長たちと交渉して、サウード側の戦線を内側から崩そうと努めた。エジプトの紅海貿易における取り分も、この遠征で増えた。", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["ビセルの戦い：サウード側の軍が敗走", "9c9ab91f"], "d": ["会戦で大敗を喫したサウード家は内陸に退いた。結ばれた休戦は長続きしなかった。二年後に作戦はネジドの中心に移されることになった。アトラスはこの勝利の後、ターイフ東方のTurabeとHurmaをサウード家の手から離れたものとみなす（出来事の出典はLorimer, Gazetteer。地点ごとの証言と1月13日の日付は申告付きの近似である）。", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["イブラヒム・パシャのネジド遠征の出発", "d5ed80d1"], "d": ["弟トスンの死により指揮を受け継いだイブラヒム・パシャは、砂漠で二年続く過酷な行軍に乗り出した。井戸から井戸へと進む軍は、部族を一つずつ排除して、サウード家の首都に迫った。", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["ディルイーヤの陥落 — 第一次サウード国家の終わり", "aa96206d"], "d": ["六か月続いた包囲の後、ディルイーヤは降伏して破壊された。首長アブドゥッラー・ブン・サウードはイスタンブルに送られて処刑された。オスマン朝の旗は、アラビアの内陸にこれほど深く及んだのは初めてであった。ネジドの守備隊は1824年まで残った。同じ日に加わったその他の地：Dir'iye (Necid)。", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["スーダン遠征の開始", "b1fc6905"], "d": ["メフメト・アリーの目的は三重であった。軍に兵を集めること、センナールの金に到達すること、逃れたキョレメンの残党を滅ぼすことである。息子イスマーイール・パシャの指揮する部隊はナイル川をたどって南に下った。", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["ドンゴラの占領 — キョレメンの残党の解体", "ba6bc24b"], "d": ["ナイル川の大きな湾曲部のドンゴラに入った軍は、ここに逃げ込んでいた最後のキョレメンの集団を一掃した。地図ではスーダンはこの日付から従属の層に現れる。征服したのはカイロであり、統治するのもカイロとなる。", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["センナール（フンジュ）王国の降伏", "3cac7dd2"], "d": ["3世紀続いたフンジュ朝は戦わずして降伏した。同じ年にナイル川の二つの支流の合流点に築かれた陣営は、短期間のうちにスーダンの行政の中心ハルツームに変わった。同じ日に加わったその他の地：Sennar。", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["コルドファンの占領", "06440602"], "d": ["西に送られた第二の部隊は、バーラ（Bâra）でダルフールの軍を破り、ヌフードの周辺とともにコルドファンを取った。エジプトのスーダン支配は、こうしてナイル渓谷から西の草原に広がった。", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["クレタにエジプト軍が上陸", "835aee90"], "d": ["ギリシア人の蜂起がクレタに波及すると、バーブ・アーリーは島にエジプト軍が送られることを求めた。メフメト・アリーの島での影響力はこの介入によって始まり、八年後にクレタ総督の地位が彼に与えられることで結実した。", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["シェンディでのイスマーイール・パシャの殺害", "223860c9"], "d": ["重い税と兵の要求に憤った地方の首長ニミルは、宿営していた家に火を放ってイスマーイール・パシャとその随行者を焼いた。報復の遠征は地域を血の海に変え、スーダンの統治はこの後、厳しさの上に築かれた。", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["マフムト2世がモレアのためメフメト・アリーに支援を要請", "03594a42"], "d": ["イェニチェリの軍が三年かけても鎮圧できなかったモレアの蜂起のために、スルタンはヨーロッパ式に訓練されたエジプト軍に頼った。見返りにモレア総督の地位とクレタが約束された。この要請は、帝国が自らの州に頼らざるを得なくなった最初の公然たる告白であった。", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["イブラヒム・パシャがモドンに上陸", "9c993dba"], "d": ["エジプト艦隊に護られた上陸部隊は、モレアの南西端に足を踏み入れた。正規歩兵と野砲を備えたこの軍は、蜂起した武装集団に対して短期間のうちに優位を確立した。", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["トリポリツァの奪回 — モレアの中心が陥落", "8a478c11"], "d": ["蜂起の統治の中心トリポリツァの陥落により、モレアの大部分は再び管理下に入った。地図では半島は、エジプト軍の手にあるため従属の色調で現れる。", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["ミソロンギ（Mesolongi）の陥落", "07257f87"], "d": ["一年続いた包囲の後、都市は取られた。しかし防衛がヨーロッパの新聞に生んだ反響は、ギリシアの大義への共感を頂点に押し上げ、列強の介入の土壌を整えた。", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["アテネのアクロポリスの降伏", "3b19f946"], "d": ["アクロポリスの陥落により、ギリシアの蜂起は軍事的にはほぼ終わっていた。まさにこの時点で、問題は内乱ではなくなり、ヨーロッパ外交の主題となった。", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["ロンドン条約：三国がギリシアの自治を強要", "7ce46fd8"], "d": ["イギリス、フランス、ロシアは、オスマン朝とギリシア人の間に休戦と自治の条件を受け入れさせるため共同で行動することを決め、拒まれた場合は艦隊が介入すると通告した。バーブ・アーリーは提案を拒んだ。", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["アレクサンドリア協定：エジプトのモレアからの撤退の決定", "cc978f37"], "d": ["ナヴァリノで艦隊を失ったメフメト・アリーは、イスタンブルに諮らずイギリスの提督と直接合意して、軍をモレアから撤退させることを受け入れた。総督が列強と単独で協定を結ぶことは、将来の危機の前触れであった。", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["エジプト軍がモレアから撤退", "8fb742dd"], "d": ["最後の部隊が船に乗せられた。半島は事実上失われ、1830年のロンドン議定書により独立ギリシアの核となった。メフメト・アリーは約束されたモレア総督の地位を得られず、その代わりに大艦隊と軍を失っていた。同じ日に失われたその他の集落：Modon, Koron。", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["クレタの統治がメフメト・アリーに委ねられる", "7f76396d"], "d": ["モレアの喪失の埋め合わせとして、クレタ総督の地位がメフメト・アリーに与えられた。島は十年間カイロから統治された。地図ではその間、従属の色調で現れる。同じ日に加わったその他の地：Kandiye (Girit)。", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["イブラヒム・パシャがシリアに入る — 第一次危機の開始", "1a5cc386"], "d": ["口実は、エジプトから逃れた農民を引き渡さないアッコの総督であった。真の理由は、メフメト・アリーがシリアの木材、港、人的資源を必要としたことである。軍はシナイを越えて、パレスチナ沿岸を急速に掌握した。", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["アッコ包囲の開始", "b211d96d"], "d": ["1799年にナポレオンを止めた城塞は、六か月抵抗した。包囲は、エジプト軍の近代的な砲兵の最初の大きな試練であった。", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["アッコの陥落", "0f47917b"], "d": ["城壁を砕く砲台が突破口を開くと、城塞は取られた。シリアの門は開かれた。バーブ・アーリーは同じころ、メフメト・アリーを反逆者と宣言し、総督の地位を廃した。", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["ダマスクスの降伏", "48da3b62"], "d": ["都市は戦闘なく降伏した。イブラヒム・パシャは税制と非ムスリムに認められる平等を宣言して、地元の支持を得ようとした。同じ政策が数年後に彼に対する反乱の原因にもなった。同じころに加わったその他の地：Beyrut, Trablusşam, Sayda。", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["ホムスの戦い", "867810ee"], "d": ["シリアを救うために送られたオスマン軍は、開けた地で敗走した。イェニチェリの廃止から六年後に創られた新しい軍が、まだ準備できていなかったことが分かった。", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["アレッポの占領", "9c0ead76"], "d": ["北シリアの通商・統治の中心も陥落した。こうしてエジプト軍はトロス山脈の麓に迫り、アナトリアの門にある隘路へ向かった。", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["ベレン（Beylan）の隘路の敗走 — チュクロヴァの開放", "4bae872b"], "d": ["アマヌス山脈の狭い隘路で防衛線が破られた。アンタキヤ、アダナ、タルススがエジプト軍に移った（マラシュの占領はTDVによれば1833年であり、別項）。地図ではチュクロヴァは従属の色調に変わる。アナトリアの内陸に至る道はもはや無防備であった。", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["ギュレク隘路の陥落 — イチェルの沿岸（メルスィン、シリフケ）がエジプトの管理下に", "d9049b5b"], "d": ["トロス山脈のチュクロヴァの門であるギュレク隘路は、エジプト軍の手に渡った。イブラヒム・パシャはイチェル・サンジャクに自らのミュテセッリムを任命し、沿岸のすべての桟橋はエジプトの管理下に入った。地図ではメルスィンとシリフケはこの日から（下限。任命の日は史料にない）エジプトに属するものとして示される。キュタヒヤの決定ではアダナのムハッスルルクのみが言及されるため、この管理はアナトリアからの撤退とともに終わる。", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["コンヤ・エレーリがエジプトの占領下に — コンヤ＝アダナの道のトロスの入口", "fb908900"], "d": ["ギュレク隘路を越えたエジプト軍のコンヤに至る道上のエレーリは、1832年にイブラヒム・パシャの占領下に入り、1833年のキュタヒヤの取り決めで撤退されると再びカラマン州に結びつけられた。地図ではアダナとコンヤの間の占領線の、史料に基づく中間点である。Ulukışla と Karapınar については都市レベルの証言が見つからなかった。", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["エジプト軍がコンヤに入る", "13952a2d"], "d": ["トロス山脈を越えた軍は中央アナトリアに達した。オスマン朝の総督の軍が、初めて帝国の中核の地を進んでいた。同じ日に加わったその他の地：Karaman。", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["コンヤの会戦：大宰相が捕虜に", "ec82cc9a"], "d": ["霧の中で崩れたオスマン軍は大敗を喫し、大宰相レシト・メフメト・パシャは捕らえられた。国家の中央軍はもはやなく、イスタンブルとエジプト軍の間に立ちはだかる力は残っていなかった。", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["マラシュがエジプトの占領を受ける", "f558e383"], "d": ["TDVによれば、マラシュは1833年にカヴァラのイブラヒム・パシャの占領を受け、十九か月近く彼の統治下に残った。マラシュはキュタヒヤの取り決めの州境の外に残ったため、この統治は法的なものではなく事実上のものである。", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["カラヒサル・サーヒブ（アフヨン）がエジプトの占領を受ける — コンヤ＝キュタヒヤの道", "ae0c2c78"], "d": ["コンヤの会戦の後キュタヒヤに進んだエジプト軍の進路上にあるカラヒサル・サーヒブは、1833年にしばらくイブラヒム・パシャの手に残った。地図ではコンヤとキュタヒヤの間の占領線の、史料に基づく中間点である。Akşehir、Ilgın、İshaklı については都市レベルの証言が見つからなかったため、これらはオスマン朝の色のままである。", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["エジプト軍がキュタヒヤに到達", "214f8df6"], "d": ["イブラヒム・パシャはイスタンブルから三日の道のりのキュタヒヤで止まった。それ以上進まなかったのは軍事的ではなく政治的な理由であった。ロシアの介入とヨーロッパの反応が計算に入れられていた。", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["ロシア艦隊がビュユクデレの前に", "6f836d61"], "d": ["イギリスとフランスから支援を得られなかったマフムト2世は、昨日までの敵ロシアに頼った。スルタンの「溺れる者は蛇にもすがる」という言葉で語られるこの決定は、ロシア兵が海峡に現れることに終わり、ヨーロッパに警鐘を鳴らさせた。", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["キュタヒヤの合意（口頭）— シリアとアダナがカヴァラの者に", "25fe9985"], "d": ["バーブ・アーリーはエジプト、クレタ、ヒジャーズに加えて、ダマスクス、アレッポ、トリポリ・シャーム、サイダの総督の地位をメフメト・アリーに、アダナのムハッスルルクをイブラヒム・パシャに委ねた。見返りに軍はトロス山脈の南に退いた。これは条約ではなく、スルタンが一人の総督に与える勅令の形であった — 問題は解決されず、先送りされたのである。", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["エジプト軍のアナトリアからの撤退がギュレクで完了", "a53ac2a3"], "d": ["キュタヒヤの取り決めの後、エジプト軍はアナトリアを引き払った。6月中旬ごろに軍の全体がギュレク隘路からチュクロヴァに渡った。イチェルの沿岸（メルスィン、シリフケ）は再びオスマン朝の統治に戻る。アダナのムハッスルルクとシリアはエジプトに残る。", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["ヒュンキャール・イスケレスィ条約", "da741d5c"], "d": ["ロシアと八年間の相互防衛同盟が調印された。秘密条項によれば、ロシアが攻撃された場合、オスマン朝は海峡を軍艦に対して閉ざすこととされた。これはオスマン外交の最も議論のある決定の一つとなり、イギリスをエジプト問題で積極的にさせた。", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["パレスチナ＝ナーブルスの反乱、エジプトの統治に対して", "4fe43e27"], "d": ["徴兵、武器の収集、新税は、パレスチナで広範な蜂起を招いた。反乱は厳しく鎮圧された。エジプトの統治の地元住民の間での支持は急速に失われた。", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["マラシュのエジプト統治の終わり（おおよそ）", "bb46ca42"], "d": ["TDVの「十九か月近く」という期間を1833年の占領から数えると、エジプトの統治は1834年の夏ごろに終わる。キュチュカリオウル家のムスタファ・ベイが1834年にエジプト軍に抗し切れずマラシュの方面に退いたことも、マラシュがそのときエジプトの管理外の避難所であったことを示している。", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["ドルーズ山の蜂起", "12e74626"], "d": ["ドルーズ派の地域で起きた抵抗は二年続いた。シリアに積もった不満は、1840年に連合艦隊が沿岸に上陸したとき、エジプト軍の背後を空にすることになる。", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["メフメト・アリーが独立の意図を表明", "48633bbd"], "d": ["総督は列強の領事に、エジプトとシリアの独立を宣言することを考えていると明らかにした。イギリスはこれに断固として反対した。地中海に強力でフランスに近い国家が生まれることは、インドへの道を脅かすからである。", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["オスマン軍がユーフラテス川を渡る", "9af1ea69"], "d": ["マフムト2世は、キュタヒヤで失ったものを取り戻すため、軍をシリア国境に向けた。軍に顧問として加わっていたプロイセンの将校モルトケは、陣地の選択と早期の攻勢に異議を唱えたが、その異議は聞き入れられなかった。", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["ニジプの戦い — オスマン軍の壊滅", "156b3cdf"], "d": ["配置の悪いオスマン軍は、数時間のうちに敗走した。敗北の知らせがイスタンブルに届く前にスルタンは死んだ。国家は数日のうちに軍を、君主を、続いて艦隊を失うことになる。", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["マフムト2世の死", "07eccfff"], "d": ["三十一年の治世のあいだにイェニチェリを廃し、中央の統治を再建したスルタンは、最大の敵を破ることなく崩御した。病気には的確な診断が下されなかった。その死は、イェニチェリの精神が動き出すことへの恐れから、都市で軍事上の措置が取られるまで、6月30日まで伏せられた。", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["アブデュルメジトの即位とマフムト2世の葬儀", "d0f3d2cc"], "d": ["父の死により十六歳のアブデュルメジトが即位した。同じ日にマフムト2世の遺体はトプカプ宮殿に運ばれた。恐れられた混乱は起きず、ムスリムと非ムスリムの広範な民衆が葬列に加わった。", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["艦隊のアレクサンドリアへの引き渡し", "a53e6103"], "d": ["海軍総督アフメト・フェヴズィ・パシャは、大宰相コジャ・フスレヴ・パシャが艦隊をロシアに与えるのではないかと疑い、艦隊をアレクサンドリアに連れて行ってメフメト・アリーに引き渡した。オスマン国家は同じ月のうちに、軍もスルタンも艦隊もない状態になった。", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["列強の共同覚書", "2a3b8316"], "d": ["五か国はバーブ・アーリーに覚書を渡し、エジプト問題で単独で合意しないよう求めた。内政問題はこうして正式に「ヨーロッパの問題」となった。オスマン国家は自らの州について決定する権限を事実上失った。", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["ロンドン条約：四か国がオスマン朝の側に", "a517f775"], "d": ["フランスを除外して調印された条約は、メフメト・アリーに最後通牒を突きつけた。十日以内に受け入れれば、エジプトの世襲の総督の地位と、終身の条件でアッコ、二十日以内に受け入れればエジプトのみ、拒めば何もなし。総督は拒んだ。", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["ベイルート砲撃と連合軍の上陸", "0905ce92"], "d": ["英墺艦隊はベイルートを砲撃した。レバノン山地ではエジプトの統治に対して蜂起した住民に武器が配られた。イブラヒム・パシャのシリアでの支配は、内乱と外部の介入の間で崩れた。", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["ベイルートと沿岸の都市の喪失", "09bdaf23"], "d": ["バールベック方面での戦闘の後、エジプト軍は沿岸から退いた。地図ではレバノンの沿岸は従属の色調から外れて、直接オスマン朝の統治に戻る。", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["アッコが二時間で陥落", "5aec21f0"], "d": ["連合艦隊の砲撃で城塞の火薬庫が爆発し、アッコは数時間のうちに降伏した。八年前にイブラヒム・パシャが六か月かけてしか取れなかった城塞は、海軍砲兵の優位を示した。", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["アレクサンドリア協約", "85cb47b0"], "d": ["メフメト・アリーはシリア、アダナ、クレタ、ヒジャーズを放棄すること、オスマン艦隊を返還すること、スルタンの宗主権を認めることを受け入れた。見返りに、エジプトの世襲の総督の地位が保証された。", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["エジプト軍がシリアとチュクロヴァから撤退", "719a28dc"], "d": ["九年の占領は終わった。イブラヒム・パシャの軍はシナイ経由でエジプトに戻った。地図ではアレッポからガザまで、アダナからクレタまで広がる帯が再び直接オスマン朝の統治に移る。同じ日に失われたその他の集落：Urfa, Maraş, Tarsus, Antakya, Kandiye (Girit), Hama, Şam, Kudüs, Yafa, Nablus。", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["勅令：エジプト総督位がカヴァラ家の世襲に", "87b89ff8"], "d": ["スルタンの勅令は、総督位が王朝の中で父から子へ受け継がれることを認めた。その代わり軍の定員は一万八千に引き下げられ、税はイスタンブルに結びつけられ、貨幣鋳造と条約締結の権限は廃された。エジプトは州のまま残ったが、もはや別の王朝の国であった。ヒジャーズと両聖都の統治はバーブ・アーリーに戻った。同じ日に従属の層から直接の層に戻ったその他の集落：Mekke, Medine, Cidde, Yenbu。", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["ロンドン海峡条約", "0e95a1ea"], "d": ["ヒュンキャール・イスケレスィ条約に代わった条約は、平時には海峡がすべての軍艦に対して閉ざされることを定めた。ロシアが単独で得た特権は、こうしてヨーロッパの共同の保証に変わった。海峡問題は国際的な地位を得た。", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["イブラヒム・パシャが事実上のエジプト総督に", "9e14f5d9"], "d": ["老いて精神の能力を失ったメフメト・アリーに代わって、息子のイブラヒム・パシャが総督の座に就けられた。しかし数か月後の1848年11月に、父より先に死んだ。", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["カヴァラのメフメト・アリー・パシャの死", "871310e0"], "d": ["カヴァラで生まれ、エジプトで王朝を築き、帝国を二度深淵の縁まで追いつめた総督は八十歳で死んだ。彼が築いた王朝は1953年までエジプトを支配した。国家は彼が開けた傷をヨーロッパの介入によって閉じることができたと見て、タンジマートの道を進んだ。", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["エルトゥールル・ガーズィーの死とオスマン・ベイの侯国継承 — ソユトとドマニチの遺産", "395fb9fa"], "d": ["TDVによれば、エルトゥールル・ガーズィーはヒジュラ暦680年（1281〜82年）に没した。項は1288年と1289年の日付も与えられていることを記す。オスマン・ベイは、父から征服された都市ではなく、セルジューク朝のスルタンが辺境地帯の最前線に置いたエルトゥールルに与えた二つの割り当てを継承した。ソユトでの冬営地（ユルトルク）とドマニチでの夏営地（ヤイラク）である。つまり侯国は征服の遺産ではなく、二つの牧地の割り当てで事業を始めたのである。地図ではこの二つの地は「征服」ではなく「継承」として示される。", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["シチリアの晩祷 - アンジュー家、シチリア島を失う", "547db635"], "d": ["パレルモで復活祭の月曜日の晩課の時刻に、アンジュー家のシャルル1世の統治に対して勃発した蜂起は、シチリア島をアンジュー家から切り離した。シチリア王国は二つに分かれ、島はアラゴンに向かい、アンジュー家はナポリを中心とする大陸の王国に留まった。同家のアドリア海および地中海の海外領もこの王国に属したままであった。1267年から手中にあったコルフと、1270年代から保持していたドゥラスはナポリ王国の一部として存続し、アルバニア沿岸のヴロラ(アヴロニャ)、カニナ、ヒマラの城塞もナポリ中心の王国に残った(ヴロラの指揮官ジョン・オブ・タクシスは1282年を通じてビザンツに抵抗した。ドゥラス、ヴロラ、カニナはおそらく1285年初めにビザンツに渡った)。一方マルタは、1284年になってようやくアラゴン人の手に落ちた。", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["クラジャヒサル襲撃 — オスマン・ベイの最初の軍事行動", "79b00b14"], "d": ["TDVのオスマン1世の項：「イネギョルの近くの小さなクラジャ城塞を略奪して火を放った（ヒジュラ暦684年／1285年）。」これは、史料で年代を特定できるオスマン・ベイの最初の軍事行動である。恒久的な集落は取られず、城塞は略奪されて焼かれた。したがって征服というより古典的な辺境の襲撃である。侯国の軍事活動の起点とされる。", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["カラジャヒサルの征服 — 最初の都市の獲得とエスキシェヒルの掌握", "178ae619"], "d": ["TDVのオスマン1世の項：オスマン・ベイはヒジュラ暦687年（1288年）に「カラジャヒサルを征服してエスキシェヒルを領有した」。これは侯国の最初の真の都市の獲得であり、伝承によれば、オスマン・ベイはこの成功により辺境のサンジャク・ベイに昇ったという。彼の名による最初の金曜のフトバはカラジャヒサルで読まれ、ここに最初のカーディーが任命されたと伝えられる。TDVのエスキシェヒルの項は、オスマンの伝承が1291年の日付を与えるが、その正確さは疑わしいと述べる。", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["アッカのマムルーク朝への陥落 - 十字軍勢力のシリア沿岸からの一掃:サイダとベイルート", "3ca7a464"], "d": ["長らくエルサレム十字軍王国の中心であったアッカは、マムルーク朝のスルタン、アル=マリク・アル=アシュラフ・ハリールに征服され、十字軍のパレスチナにおける支配は終わった。アッカから退いたテンプル騎士団はサイダに逃れたが、マムルーク軍が近づくと海上の城を捨ててキプロスへ逃れ、同市はその夏のうちにマムルーク朝の手に渡った。1197年から十字軍の手にあったベイルートも、1291年にダマスクス総督サンジャル・アッ=シュジャーイーに奪われた。こうして2世紀にわたる十字軍の存在はシリア・パレスチナ沿岸から消えた。", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["ビレジクとヤルヒサルの夜襲による征服", "f461b0af"], "d": ["TDVのビレジクの項：「ビレジクのテクフルを含む地域の他のテクフルたちはオスマン・ガーズィーに対する暗殺を企てたが、その企てが察知されると、オスマン朝の軍は急襲でヤルヒサルとビレジクを征服した（1299年）。」二つの城塞は一つの作戦で、同じ夜の襲撃で取られた。この年代は、オスマン国家の建国の年とされる転換点である。同じ日に加わったその他の地：İnegöl。", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["コユンヒサル（バフェウス）の戦い — ビザンツ軍に対する最初の大きな勝利", "584a9512"], "d": ["TDVのオスマン1世の項：オスマン・ベイは1302年7月27日にバフェウス（コユンヒサル）でビザンツ軍と戦ってこれを破った。この勝利は、オスマン・ベイを地域の辺境の君主から王朝の創始者の地位に引き上げた転換点である。戦いの後、ブルサ平野はオスマン朝の管理下に入り、イズニクの封鎖が始まった。", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["ディンボスの勝利と続くキテとウルバトの占領", "e168ab64"], "d": ["TDVのオスマン1世の項：ヒジュラ暦702年（1303年）に、ブルサ、ケステル、キテ、アドラノスのテクフルたちが結んだ同盟は、ディンボス隘路で敗走させられた。敵は戦いながら狭い隘路まで引きずられ、ケステルのテクフルは戦場で死んだ。勝利の直後にキテとウルバトの城塞が占領され、ブルサの陸上の連絡が断たれ、封鎖が強化された。若いオルハンもこの戦いに加わった。", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["サカリヤ遠征：レブレビジヒサル、レフケ、メケジェ、ゲイヴェの占領", "a51ba4d3"], "d": ["TDVのオスマン1世の項は、ヒジュラ暦704年（1304年）のサカリヤ遠征の順序を伝える。「レブレビジ城塞に来ると、テクフルは服従した…レフケに達した…メケジェに着いた…ゲイヴェに行き、空であった城塞を取った。」レフケは、サカリヤ渓谷のビレジクに開く門である。この一度の遠征は、渓谷沿いに延びる城塞の連鎖をオスマン朝の管理下に移し、イズニク盆地の東翼を閉ざした。", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["ゲイヴェ隘路の城塞の征服：カラチェピュシュ、カラティギン、アプス", "76907c78"], "d": ["TDVのオルハンの項：オルハンはヒジュラ暦705年（1305年）のサカリヤ遠征で「カラチェピュシュ（カトイキア）、イズニクの前のカラティギン、アプス（ヒプスー：ゲイヴェ隘路にある）の城塞を征服した」。この三つの城塞は、サカリヤ渓谷とイズニク盆地の間の通路を閉ざして、イズニクの陸上の援助を完全に断った。ゲイヴェの隘路にあるカラチェピュシュとアプスにはガーズィー・アブドゥッラフマーンが置かれた。都市はもはや飢えによってのみ陥落させられる状態となった。", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["アドラノス（オルハネリ）遠征 — オスマン・ベイの最後の遠征", "4811546c"], "d": ["TDVのオルハンの項は、1323年の秋のアドラノス城塞の遠征をオスマン・ベイの最後の遠征として記す。アドラノスのテクフルは、二十年前にディンボスでオスマン朝に対して結ばれたテクフルたちの同盟の一員であった。この遠征はその清算の意味を持っていた。城塞の決定的な征服の日は知られていない。作戦はオルハン・ベイによって続けられた。", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["オスマン・ガーズィーの死去とオルハン・ベイの侯位継承", "021487cd"], "d": ["侯国にその名を与えたオスマン・ガーズィーは、Asporça HatunおよびMekeceの寄進文書の証言により、724年(1324年)に没した。1305年から遠征で軍の先頭に立っていた子オルハンは、父の死に際し王位争いを経験することなく侯国の長に就いた。創設世代が旗を揺らぐことなく引き継いだことは、辺境侯国から国家への道において、一族が最初の大きな試練を静かに乗り越えたことを示している。", "6f95e64a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["ペレカノン（マルテペ）の戦いとコジャエリ全域の占領", "389e7bd4"], "d": ["TDVのオルハンの項：戦いの初日、オルハン・ガーズィーはビザンツ軍を引きつけるため三百人の部隊を送った。二日目にパザルル指揮下の部隊が平地に下りると戦いは拡大し、皇帝が矢で傷つくとビザンツ軍にパニックが起きた。結果は決定的である。「オルハンはコジャエリの全体を掌握した。勝利の後、イズニクの人々にはいかなる望みも残らなかった。」ヘレケからユスキュダルまでの沿岸の町がオスマン朝の支配に入り、ゲブゼは地域の中心とされた。これは、イスタンブルを救うために来た最後のビザンツ帝国の軍であった。", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["イズニクに最初のオスマン・メドレセが設立される", "c85fb625"], "d": ["オルハン・ベイはイズニクを奪った直後、チャンダルル・カラ・ハリルを同地のカーディーに任じ、バシリカをモスクに改め、その傍らにイマーレトとメドレセを建てさせて都市の整備を始めた。TDVの「ダーヴド・エル・カイセリー」の項によれば、メドレセの建設は1336年に完成し、オルハン・ガーズィーは日給30アクチェの教授職にダーヴド・エル・カイセリーを迎えた。このメドレセはオスマンの学問生活における最初の制度的な一歩であり、侯国は征服の力に加えて学問の伝統も備えることになった。征服したビザンツの都がイスラームの学問の中心に変わったことは、オスマンが定住国家たろうとする志向の最初の具体的な徴であった。", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["ビザンツの貢納化 — イズミット包囲と条約", "0c1ec8d3"], "d": ["TDVのオルハンの項：オルハンはヒジュラ暦733年（1333年）の夏に、イズミットを大軍と投石機で包囲し、皇帝は条約に同意した。包囲を断念することの見返りに、ビザンツはオルハンに毎年12.000枚の金（ヒュペルピュロン）を支払うことを受け入れた。「こうしてオスマンの首長の目には、ビザンツは貢納国の状態に陥った。」見返りに、オルハンは皇帝の友となり、ビザンツに従属する都市を攻撃しないこととされた。辺境の侯国が東ローマを課税下に置いたことは、力の均衡がどれほど転じたかの宣言であった。", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["カレスィ侯国の併合：バルケシル、ベルガマ、ビガ、エドレミト、エルデク", "c7cb0511"], "d": ["TDVのオルハンの項（イナルジュク）は併合をヒジュラ暦735年（1334〜35年）に置く。デミルハン・ベイの死を受けて、カレスィのガーズィーたちとハジ・イルベイは、ドゥルスン・ベイを王位に招き、オルハンに助けを求めた。オルハンはまずバルケシルに進軍した。和平の交渉に向かったドゥルスン・ベイがベルガマの城塞から放たれた矢で死ぬと、侯国は全面的にオスマン領に編入された。同じ作戦でKirmastiとMihaliçが服従し、ギョルヤズ（Gölyazı）が取られ、以前に安全保障を与えて残されていたウルバトが決定的に占領された。オルハンはカレスィ・サンジャクにスレイマン・パシャを任命し、ビガを辺境の中心とした — ルメリアへの渡海のための海事の人材はこうして得られた。注：TDVのカレスィオウル家の項は同じ出来事にヒジュラ暦746年（1345年）の日付を与える。百科事典は内部で矛盾している。同じ日に加わったその他の地：Çanakkale。", "f5ed82c2"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["オルハン・ガーズィーとジェノヴァ人との最初のカピチュレーション", "e64cb196"], "d": ["ヴェネツィア-ジェノヴァ戦争の間にジェノヴァ人と手を結んだオルハン・ガーズィーは、1352年2月の海峡の海戦の後、ペラの防衛に弓兵1000人を送り、兵員輸送のために6万金貨を用立てた。その見返りにジェノヴァ人に最初のカピチュレーションを与えた。協定の全文は現存しない。これはオスマンがヨーロッパの海洋勢力と結んだ最初の公式な協定であり、35年後の1387年に更新されることになる。", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["ゲリボルの奪取 - ルメリアにおける恒久的な橋頭堡", "ba51a160"], "d": ["1349-1352年の間にカンタクジノスの同盟者として周辺を知っていたゲリボルを、オスマンは1354年に占領した。都市の城壁を崩した大地震が好機をもたらした。チンペの狭い橋頭堡はこうして海峡のルメリア側における本当の拠点となり、トラキアへの門は大きく開かれた。ゲリボルは1366年のサヴォイア十字軍により失われるが、1376年の二度目の征服で最終的にオスマンの支配下に入ることになる。同日に編入されたその他の地:キリトバヒル。", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["ルメリアの征服者スレイマン・パシャの死", "2dc98228"], "d": ["オルハン・ベイの長子でルメリア征服の立役者であったスレイマン・パシャは、史料に758年(1357年)、759年、760年(1359年)として挙げられる年のうち最も受け入れられている1357年の秋に、狩りの最中に落馬して死んだ。1352-1354年の渡海でルメリアにおけるオスマンの恒久的な存在を築いた王子の死により、世継ぎの順は弟ムラトに移った。ボラユルに葬られたスレイマン・パシャの廟は、オスマンのヨーロッパにおける最古の王家の記念建造物として残った。", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["ペンチク法 - イェニチェリ軍団の礎", "e5877c2d"], "d": ["ルメリア征服の後、ウラマーのカラマンル・カラ・ルステムの勧めにより、戦争捕虜の5分の1、またはそれに相当する金銭を国家に割り当てるペンチク制度が施行された。これらの捕虜から選ばれた者をトルコ人の家庭で育てて兵とすることで、スルタン直属の常備歩兵部隊、すなわちイェニチェリ軍団の核が形成された。部族騎兵に依拠した辺境侯国が、中央軍を持つ国家へと変わることは、この制度から始まった。", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["西トラキアへの進出:ギュミュルジネの征服", "9ef69221"], "d": ["エディルネの奪取後、マリツァ川の西へ向かった辺境部隊は、ガーズィー・エヴレノス・ベイの指揮下で西トラキアの中心ギュミュルジネを占領した。同市は、エヴレノス・ベイの襲撃をマケドニアへ広げるための前進司令部となった。こうしてエーゲ海岸に達するトラキアの部分がオスマンの支配下に入り、テッサロニキへの道が開かれた。", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["ヴァルナ、ドブルジャ侯国に移り首都となる", "2bfe73f9"], "d": ["ブルガリア帝国の解体過程で、黒海沿岸のヴァルナはドブロティツァが築いたドブルジャ侯国に編入され、この小国の首都とされた。", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["フィリベの西:タタルパザルジュクとイフティマンの併合", "1664d0e1"], "d": ["1372年のフィリベ(プロヴディフ)奪取の後、マリツァ川上流端のタタルパザルジュクと、ソフィアへの隘路を押さえるイフティマンがオスマンの統治下に組み込まれた。チルメンの戦いの後に臣従した地方ベイたちの手にあったこの線は直接統治に移され、フィリベ-ソフィア間の経路が途切れなくつながった。この進出は、12年後のソフィア征服への道を準備するものである。", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["サヴジュ・ベイの反乱 - 王子とビザンツ皇太子の共同の叛旗", "75198c33"], "d": ["ムラト1世の子サヴジュ・ベイと、ビザンツ皇帝ヨハネス5世の子アンドロニコス・パライオロゴスは、1373年5月の初めにブルサとコンスタンティノープルで同時に、それぞれの父に対して蜂起した。二つの王朝の世継ぎを結んだこの同盟は速やかに鎮圧され、サヴジュ・ベイは捕らえられて目をつぶされ、処刑された。オスマンの伝承が反乱の年として挙げる787年(1385年)は誤りである。この事件はビザンツがオスマンの臣従に入った年月の直後にあたり、二つの宮廷がいかに絡み合っていたかを示している。", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["ストルマ川・メスタ川流域:キュステンディル、ペトリチ、ネヴロコプ、ドラマの併合", "8c0980c4"], "d": ["チルメンの勝利の後オスマンに貢納を始めたセルビア・ブルガリアの地方ベイたちの手にあったストルマ川とメスタ川の流域は、辺境ベイたちの進出により直接オスマンの統治下に置かれた。キュステンディル、ペトリチ、ネヴロコプ、ドラマの併合によってマケドニアの東半分が開け、テッサロニキとセレスは包囲網に入った。地図上でのルメリアの南西への拡大は、この作戦の結果である。", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["ティムールがヘラートを取る：カルト朝の終わりとホラーサーンのティムール朝への移行", "15f6019e"], "d": ["ホラーサーンは1380年にサルバダール朝、カルト朝、ムザッファル朝の間の争いで分裂していた。ティムールは息子ミーラーンシャーを地域に送った後、自らヘラートに進み、しばらく包囲した後、都市をカルト朝のマリク、ギヤースッディーン・ピール・アリーから受け取った。彼の出発の後に起きた反乱はミーラーンシャーによって血で鎮圧され、1255年からヘラートを支配してきたカルト朝は終わった。マシュハドからニーシャープールまで、ホラーサーンの全体がこの日付でティムール朝の統治に入った。", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["エレトナ侯国の終焉とカーディー・ブルハーネッディーン国の成立", "60dcaf57"], "d": ["1335年にイル・ハン朝の総督職から生まれ、スィヴァスとカイセリを中心に中央アナトリアを46年間統治したエレトナ家は、宮廷内の争いで解体した。1378年5月に宰相となったカーディー・ブルハーネッディーンは、ライバルのクルチャルスラーンとハジ・シャドゲルディを排除した後、1381年秋にスルタン位を宣言して侯国を終わらせ、自らの名で呼ばれる国家を樹立した。こうしてオスマンの東の隣国が入れ替わり、スィヴァス-カイセリ線はこれ以後17年間カーディー・ブルハーネッディーンの手に留まることになる。", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["マケドニア内陸への進出:マナストゥルとオフリドの征服", "63bb7838"], "d": ["エグナティア街道上のマナストゥル(ビトラ)と湖畔のオフリドは、アルバニア方面への襲撃の際にオスマンの統治下に入った。いずれもアドリア海に至る道の要衝であり、オフリドはバルカン最古の正教大主教座の所在地でもあった。TDVはオフリドの征服年について確かな情報はなく、787年(1385年)とクラリェヴィチ・マルコの死後の797年(1395年)が挙げられていると記しており、ここでは1385年を採った。マナストゥルは以後の世紀にルメリア最重要の軍事拠点の一つとなる。", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["サヴラの戦い - アルバニアの扉が開く", "dda6671b"], "d": ["バルシャ家に対して追い詰められたアルバニアの領主カルロ・トピアの救援要請を受け、オスマン軍はサヴラ平原でバルシャ2世の軍を破り、バルシャは戦場で命を落とした。現地の領主の招きで入ったこの戦いは、オスマンにアドリア海岸まで広がるアルバニアの地における最初の恒久的な影響力をもたらした。地域の領主たちの反目を好機とするこの政策は、次の1世紀のバルカン征服の変わらぬ方法となった。", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["ティムールの「三年遠征」：アゼルバイジャンと北イランの征服", "2a98ec51"], "d": ["ホラーサーン遠征のあいだにイランの分裂した状態を間近に見たティムールは、ヒジュラ暦788年（1386年）に西に進んだ。「三年遠征」と呼ばれる1386〜1388年の作戦で、マーザンダラーン、ルリスタン、ジョージアを経てアゼルバイジャンに入り、カラバフに達した。タブリーズ、アルダビール、ウルミア、ナヒチェヴァンがティムール朝の統治に入った。北イランとアゼルバイジャンの掌握は、かつてジョチ・ウルスとイルハン朝の間であったように、キプチャク・ハン国との長い争いの始まりともなった。", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["フレンクヤズュスュの戦いとコンヤ包囲 - 最初のカラマン遠征", "af4e5d77"], "d": ["娘婿でありながらオスマンの西アナトリアでの拡大を快く思わなかったカラマン侯アラーッディーン・アリ・ベイに対し、ムラト1世は自ら出征した。フレンク・ヤズュスュと呼ばれる地で行われた戦いで、訓練され経験を積んだオスマン軍はカラマン軍を破った。続いてコンヤ城が包囲されたが、アラーッディーン・ベイが赦されたため侯国は完全には廃されなかった。この遠征は、オスマンとカラマンの間で1世紀続き、1468年の最終的な併合で終わる長い対決の幕開けである。", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["ゲリボル造船所の設立 - オスマン海軍の誕生", "47546241"], "d": ["オスマン国家の最初の組織的な造船所は、1390年にユルドゥルム・バヤジトによってゲリボルに、ビザンツから残った造船所の跡地に設けられた。西アナトリアの諸侯国の海の遺産を受け継いだオスマンは、こうして初めて自ら船を建造する海軍力となった。ダーダネルス海峡の要衝に位置する造船所は、コンスタンティノープルの包囲からエーゲ海遠征に至るまで、1世紀半にわたりオスマン海軍の主要基地として機能した。", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["ハミド・イリ、オスマンに編入:ウスパルタ、ブルドゥル、ウルボル、エイルディル", "e3da7de5"], "d": ["カラマン侯アラーッディーン・ベイがハミド・イリを攻撃し、民衆が訴えたことを受けて出征したユルドゥルム・バヤジトは、ハミド侯国の残りの領土をすべて掌握し、その統治を息子イサ・チェレビに与えた。", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["ムザッファル朝の終わり：シャー・マンスールのシーラーズ前での敗北", "5fd14eb8"], "d": ["1318年からヤズド、ファールス、イスファハーン、ケルマーンを支配してきたムザッファル朝の最後の有力な君主シャー・マンスールは、親族と結束してティムールに対して行動を起こした。シーラーズ近郊の戦いで、将の一人が敵側に移ったことにより兵力の多くを失い、敗れて殺された。ティムールが続けて王朝のすべての成員をも殺させたことで、ムザッファル朝の支配は終わり、ファールスとケルマーンはティムール朝の統治に加わった。", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["アマスヤのオスマン領への編入", "fe2860cf"], "d": ["ユルドゥルム・バヤジトの中央アナトリア作戦の際に包囲されたアマスヤのエミールは都市をオスマンに引き渡し、バヤジトは1393年に同市に入った。スルタンはその統治を子メフメト・チェレビに委ね、王子のサンジャクとなったアマスヤは以後オスマン王家で最も重要な教育の場の一つとなった。この選択は後の空位時代に決定的な意味を持ち、チェレビ・メフメトは国家再統一の戦いをまさにこのアマスヤを基盤に進めることになる。", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["ティムールがバグダードを占領 — ジャライル朝がアナトリアに逃れる", "4d5602b3"], "d": ["ティムールは長い包囲の後にバグダードを取った。都市の主ジャライル朝のスルタン・アフマドは西に逃れ、まずマムルーク朝に、次いでオスマン朝の宮廷に身を寄せた。ティムールの西方への拡大は、こうして初めてオスマン朝の勢力圏と直接接した。二人の君主の間の敵意の最初の環は、ここから始まる。", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["黒海沿岸のヴァルナの奪取", "a84b2abf"], "d": ["ドナウ川と黒海の間のブルガリア帝国領が圧迫される中で、沿岸最大の港ヴァルナがオスマンの統治下に入った。港の奪取はドブルジャ方面への進出の道を開き、オスマンに黒海西岸の最初の大きな船着き場をもたらした。ヴァルナは51年後、十字軍軍が殲滅される1444年の勝利の舞台ともなる。", "2e425501"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["カーディー・ブルハーネッディーン国の滅亡", "b13391e3"], "d": ["アク・コユンルの君主カラ・ユルク・オスマン・ベイの捕虜となったカーディー・ブルハーネッディーンは、スィヴァスの引き渡しと引き換えに解放されると申し出たが、市民は抵抗し、スルタンは城壁の前で処刑された。スィヴァスの有力者たちは息子アラーッディーン・アリ・チェレビを擁立したが、アク・コユンルの圧力のもとでユルドゥルム・バヤジトに援助を求め、スレイマン・チェレビ指揮下のオスマン軍がカラ・ユルクを破って同市を掌握した。こうしてカーディー・ブルハーネッディーン国は歴史から消え、スィヴァス、トカト、ニクサル、カイセリはオスマン領に編入された。同日に編入されたその他の地:クルシェヒル、チョルム。", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["ティムールとの対立：逃亡者の引き渡しの拒否", "33790bc8"], "d": ["ティムールの圧力により、ジャライル朝のスルタン・アフマドとカラ・コユンルの指導者カラ・ユースフはオスマン領に逃げ込んだ。ティムールはこの二人の逃亡者の引き渡しを求め、イルドゥルム・バヤジトは拒んだ。これを受けて、二人の君主の間で相互の激しい侮辱を含む書簡の応酬が始まった。戦争の思想的な土台は、まだ一人の兵も動かないうちに、これらの書簡によって築かれた。", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["ブルサのユルドゥルム施療院 - 最初のオスマン病院", "5f0dc59a"], "d": ["ユルドゥルム・バヤジトはブルサに壮麗なウル・ジャーミィを建てさせた年月に、都市に施療院も贈った。イマーレト、メドレセ、ハン、橋からなる大規模な慈善事業計画のうち、医療にあてられた環がこれであった。国家が設立した最初の病院であるこの建物は、医師を養成する医学校の役割も果たし、オスマンの保健施設の模範を定めた。アンカラの惨事のわずか2年前に完成したこの建造物は、ユルドゥルムがブルサを帝国の首都に変えようとした構想の最後の環の一つである。", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["ティムールがシヴァスを破壊", "f4d79de6"], "d": ["アク・コユンルのカラ・ユリュク・オスマン・ベイとエルズィンジャンの首長ムタハルテンの案内でシヴァスに進んだティムールは、都市を十八日間包囲し、誰の血も流さないという約束で受け取った後、大虐殺を行った。守備兵を堀に入れて生きたまま上を覆わせた。城壁をはじめ都市の重要な建造物は破壊され、シヴァスは人口の面で崩壊した。これは、アンカラの戦いの二年前にティムールがオスマン領に加えた最初の大きな打撃である。", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["イルドゥルム・バヤジトがエルズィンジャンとケマフを奪回", "7047ca08"], "d": ["ティムールがシリア遠征に出たことを好機とみたイルドゥルム・バヤジトは、ティムールに従属するエルズィンジャンの首長ムタハルテンの手からエルズィンジャンとケマフを取った。シヴァスの破壊に介入しなかったにもかかわらず、この動きは、ティムールの東アナトリアにおける勢力圏への直接の挑戦を意味した。二人の君主の仲は、この後、修復できないものとなった。", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["ティムールがタブリーズから送った最後通牒 — 四つの条件", "3e1ac50e"], "d": ["ティムールはタブリーズから送った使者を通じて四つの条件を伝えた。ケマフのムタハルテンへの返還、アナトリアの諸侯から取った領土の持ち主への返還、オスマン朝の王子の人質としての派遣とカラパク（külâh）と帯の服属の印としての受容、そしてカラ・ユースフの引き渡しである。バヤジトはこれらのどれも受け入れなかった。政治家たちの求めとムタハルテンの仲介にもかかわらず、交渉は決裂した。ティムールは、中国遠征に出る前にアナトリア問題を決定的に片づける決意であった。", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["サルハン侯国の再興 — マニサがオスマン朝から離れる", "ac747b05"], "d": ["アンカラの敗走の三週間後、ティムールの支援でオルハン・ベイが侯国の長となり、サルハン地方は再び独立した。マニサを中心とする地域は、1390年のオスマン朝の併合から十二年後に地図から消えた。これは、ティムールの侯国を復活させる政策の、日付が確実に知られる最初の実施の一つである。", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["エミール・スレイマンが国庫とともにルメリアに逃れる", "0a2b7363"], "d": ["ブルサにあった国庫、文書、家族、兄弟たちを連れたエミール・スレイマンは、ゲムリクから船でギュゼルジェヒサル（アナドル・ヒサル）に渡り、そこからゲリボルに達して、エディルネで君主位を宣言した。国家の文書と国庫がルメリアに運ばれたことは、オスマン朝の重心が一世代のあいだバルカンに移ることの始まりである。地図ではルメリアはこの日付からエミール・スレイマン自身の色で描かれる。", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["ティムールがアナトリアの侯国を再興 — トルコの統一が解体", "15187774"], "d": ["ティムールは、アンカラの勝利の後、同行していた諸侯を旧領に戻した。カラマンオウルのメフメト・ベイとアリー・ベイにはカラマン地方とカイセリ、クルシェヒル、スィヴリヒサル、ベイシェヒル、ゲルミヤンオウルのヤークブ・ベイ2世にはキュタヒヤとゲルミヤン地方、ジャンダルオウルのイスフェンディヤル・ベイにはカスタモヌ＝シノプの線に加えてチャンクル（Çankırı）とカレジク（Kalecik）が与えられた。アイドゥン、メンテシェ、テケ地方も旧王朝に戻った。イルドゥルム・バヤジトが十年で築いたアナトリアのトルコ人の統一は、たった一夏で解体した。地図ではこれらの侯国が再びそれぞれの色で現れる。", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["ティムールがイズミルを聖ヨハネ騎士団から奪取", "66dd1dd4"], "d": ["キュタヒヤ、デニズリ、アイドゥン、アヤスルク、ティレ経由で西に下ったティムールは、1344年からキリスト教徒の手にあった沿岸のイズミルを包囲して取った。イルドゥルム・バヤジトが長年取れなかったこの城塞を短期間で占領したティムールは、周辺の城塞も取った後、アイドゥン地方を旧来の持ち主に残して東に戻った。都市はこの後、アイドゥンオウルのジュネイド・ベイの統治に入った。", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["イーサー・チェレビがブルサを掌握 — アナトリアの分け前が生まれる", "955128c1"], "d": ["アンカラの敗走の後カレスィの方面に退いていたイーサー・チェレビは、ティムールがイズミルにいる間にブルサを掌握した。ティムールの兵に略奪され焼かれた旧都で君主位を宣言し、自らの名で貨幣を鋳造させた。1403年1月にはアナトリアで「トルコ人の君主」の称号で認められていた。地図ではマルマラのアジア側沿岸に延びるこの分け前は、イーサー・チェレビ自身の色で現れる。", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["ティムールのアナトリアからの撤退", "93a98839"], "d": ["イルドゥルム・バヤジトがアクシェヒルで崩御した知らせを受けたティムールは、アナトリアでの仕事は終わったとみなして東に向かった。後には、彼への忠誠を表明した侯国と、互いに対立したオスマン朝の王子たちが残された。シヴァスなどいくつかの都市は、ティムールに従属するメズィド・ベイのような首長の手に残された。ティムールは二度とアナトリアに戻らなかったが、彼が築いたこの分裂した秩序は十年続いた。", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["エミール・スレイマンがアナトリアに渡る：ブルサが彼の手に渡る", "9b27aa5f"], "d": ["イーサー・チェレビの敗北を聞いたエミール・スレイマンは、チャンダルル・アリ・パシャとともに強力な軍でアナトリアに渡り、ブルサを掌握した。1404年3月の記録は、Karadeniz Ereğlisi も彼の統治下にあったことを示す。短期間のうちにルメリアにもアナトリアの大部分にも支配を及ぼしたスレイマンに対して、チェレビ・メフメトは抵抗できなかった。地図ではこの日付からチェレビ・メフメトによるブルサの奪回（1410年）まで、両岸が一つの色、エミール・スレイマンの分け前として示される。", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["イェニシェヒル平野の戦い — チェレビ・メフメトがアマスヤに退く", "f1568288"], "d": ["ブルサとアンカラを失ったチェレビ・メフメトは、イェニシェヒル平野でエミール・スレイマンに敗れて西アナトリアのすべての獲得地を失い、トカト＝アマスヤの拠点に退いた。この敗北の後、直接の衝突を避けてアナトリアの内陸で権威を固める方向に向かった。空位時代の最も長い静かな局面は、このように始まった。", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["エミール・スレイマン、チェレビ・メフメトからアンカラを奪う", "d6a2acd6"], "d": ["ティムールのアナトリア撤退後もチェレビ・メフメトの手に残っていたアンカラを、1406年にエミール・スレイマンが包囲した。城の守将Yâkub Beyはしばらく持ちこたえたが、大宰相チャンダルル・アリ・パシャの策略によって城をスレイマンに明け渡した。これを受けてチェレビ・メフメトはカラマン侯メフメト・ベイと協定を結び、スレイマンに対して行動を起こした。", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["チェレビ・メフメト、スィヴァスをティムール朝のMezid Beyから奪還", "90079b0c"], "d": ["ティムールの侵攻後、スィヴァスの統治はティムールに臣従するMezid Beyに委ねられていた。アマスヤにいたチェレビ・メフメトは部将バヤジト・パシャを派遣して同市を奪取させ、激しい抵抗の末にスィヴァスは二度目のオスマン家の手に渡った。こうしてメフメトの領分は、アンカラの戦いから6年後に東方で旧来の国境に達した。", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["アルトゥク家の終焉:マルディンのカラ・コユンルへの引き渡し", "15b06f33"], "d": ["1106年からマルディンに君臨し、一族の中で最も長く続いた系統であったアルトゥク家は、アク・コユンルの圧力に耐えられなかった。都市を守れないと悟ったマリク・アフメトは、カラ・コユンルの君主カラ・ユースフと協定を結んでマルディンを引き渡した。3世紀を超えるアルトゥク家の支配はこうして終わった。マルディンとその周辺は、1世紀後にオスマンに移るまで、カラ・コユンルとアク・コユンルの争いの舞台となった。", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["ヤンボルの戦い - ムーサー・チェレビ、エディルネに入城", "8f978408"], "d": ["ワラキア経由でルメリアに渡ったムーサー・チェレビは、ワラキアとセルビアの支援を得てヤンボルでエミール・スレイマンの軍を破り、エディルネに入城した。空位時代においてルメリアがエミール・スレイマンの手を離れたのはこれが初めてであった。しかしその支配は長続きせず、4か月後にコスミディオンで敗れてバルカン内陸へ退くことになる。", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["インジェイズの戦い - チェレビ・メフメトのルメリアでの最初の敗北", "3c35cd43"], "d": ["ビザンツの船でルメリアに渡ったチェレビ・メフメトはインジェイズでムーサー・チェレビと交戦したが、ムーサーは配下のイェニチェリ7千人でメフメトを破り、メフメトはアナトリアへ戻らざるを得なかった。この敗北はメフメトを、直接の戦闘ではなくルメリアのウチ・ベイたちとセルビア専制公国を味方につける戦略へと向かわせた。9か月後のチャムルルの勝利の下地は、この外交によって整えられた。", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["コンヤ包囲とカラマン侯国との協定 - ハミド・イリ、サイド・イリ、ベイシェヒル、セイディシェヒル、アクシェヒルの奪還", "0996257e"], "d": ["空位時代にオスマン領を攻撃してブルサを包囲し焼いたカラマン侯国に対し、チェレビ・メフメトは大規模な遠征を組織し、ムハッラム月818年にコンヤを包囲した。カラマン侯メフメト2世・ベイは和を乞わざるを得なかった。協定の結果、ハミド・イリ(ウスパルタ周辺)とサイド・イリが再びオスマン領に編入され、ベイシェヒル、セイディシェヒル、アクシェヒルも返還された。ティムールが1402年にカラマン侯国に与えたスィヴリヒサルもオスマンに戻った。アンカラの戦いで崩れたアナトリアの統一が繕われ始めたこの遠征は、チェレビ・メフメトが「第二の創建者」とされる具体的な根拠の一つである。", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["アイドゥン侯ジュネイド・ベイからのイズミル奪取", "2377ca51"], "d": ["空位時代を通じて諸王子の間で絶えず陣営を替えたアイドゥン侯ジュネイド・ベイの本拠イズミルは、10日間の包囲の末にチェレビ・メフメトによって奪われた。ジュネイドは赦されてニグボル(ニコポル)のサンジャク・ベイに送られた。1402年にティムールがアイドゥン侯国に返還した同市は、こうして13年後にオスマン領へ戻った。ジュネイドは1422年に同市を再び奪うが、問題が決着するのは1424-1426年のムラト2世の時代である。", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["トルラク・ケマルの処刑 - サルハンは最終的にオスマン領に", "8a09dbf1"], "d": ["シェイフ・ベドレッディン運動の西アナトリア側を担ったトルラク・ケマルは、マニサ周辺で敗れて処刑された。この日以降サルハン地方は最終的にオスマンの支配下に入り、1402年にティムールが復活させた侯国は歴史から消えた。空位時代の西アナトリアにおける最後の政治的残滓はこうして一掃された。", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["ヴロラ(アヴロニャ)、ベラト、カニナの征服", "1e1949b8"], "d": ["オスマンは1417年に、アドリア海岸のヴロラを、内陸のベラトの町とカニナ城とともに支配下に収めた。1年後、ヴェネツィアが同市の奪還を試みて失敗し、ここにサンジャク制が敷かれてオスマンの権威は恒久化した。ヴロラの奪取により、オスマンは初めてアドリア海に直接の港を持つことになり、イタリアに対する海を越えた足がかりを得た。", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["中央アナトリアの奪還:カイセリとクルシェヒル", "204eacb3"], "d": ["空位時代にカラマン侯国の手に渡った中央アナトリアの諸都市は、チェレビ・メフメトが国家を再建する遠征の間にオスマンの統治に戻った。カイセリとクルシェヒルの編入によって、アンカラの戦いで失ったクズルウルマク流域はおおむね取り戻された。この進出は、4年前のコンヤ包囲に始まる東方への政策の継続である。", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["マムルーク朝、カイセリをドゥルカディル家のナースィルッディーン・ムハンマドに与える", "aad4b00c"], "d": ["カラマン侯メフメト・ベイに対して出征したマムルーク軍はカイセリを占領した。マムルーク軍の司令官は同市とその周辺をドゥルカディル家のナースィルッディーン・ムハンマドに委ねて自国へ帰った。", "8cd84dc4"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["テケ侯国の最終的な解体:アンタルヤの奪取", "e65565b2"], "d": ["アンカラの戦いの後、ティムールの復活によって再建されたテケ侯国は、ハムザ・ベイ指揮下のオスマン軍がアンタルヤを包囲して終焉した。侯国最後の有力者オスマン・チェレビは排除された。これで地中海岸のテケ地方は、21年にわたる分離の後に最終的にオスマンに編入された。同侯国はハミド侯国から分かれた一派として、1321年からアンタルヤに君臨していた。", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["トゥラハン・ベイのモレア遠征とヘクサミリオン城壁の破壊", "c6c2706d"], "d": ["ビザンツが対立する王位請求者ムスタファ・チェレビを支持したことを受け、ムラト2世はトゥラハン・ベイをモレアに派遣した。トゥラハン・ベイはコリント地峡を端から端まで塞ぐヘクサミリオンの城壁を壊して半島に入り、大きな破壊を引き起こした。和平は、城壁を二度と築かないことと年貢を納めることを条件に結ばれた。モレア専制公国はこうして軍事的に無防備にされ、1460年の最終的な征服の下地は37年前に準備された。", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["アトス山(アイナロズ)の修道院群、オスマンの保護下に入る", "562de5ea"], "d": ["テッサロニキが包囲下に置かれていた年月に、ハルキディキ半島東端のアトス山修道院共和国はムラト2世に庇護を求め、オスマンの宗主権を受け入れた。修道士たちの所有権と礼拝の権利は保障され、修道院群は納税と引き換えに内政で自由を認められた。この制度はオスマンが正教の諸機関と結んだ保護関係の最も長続きした例となり、5世紀続いた。", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["タージェッディン侯国の併合:ニクサル", "370ffd47"], "d": ["アマスヤ総督ヨルギュチ・パシャの圧力を受け、タージェッディン家のヒュサーメッディーン・ハサン・ベイは、ニクサルを中心とする領国の鍵を830年(1427年)に引き渡し、ルメリアにサンジャクを与えられた。14世紀後半に成立し、境界がときにケルキト、アマスヤ、サムスン、オルドゥ、ギレスンにまで及んだこの侯国はこうして終わった。同年、ハジェミール家に属する土地も検地されてジャニクのサンジャクに編入され、中部黒海の侯国の時代は閉じた。", "06fa8222"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["マルディン、カラ・コユンルの守将からアク・コユンルのカラ・ユルク・オスマン・ベイへ", "d82bc97f"], "d": ["カラ・ユースフが1409年に奪ったマルディンはカラ・コユンルが総督を置いて統治していたが、守備を任されたエミール・ナーシルが、835年(1432年)に同市をアク・コユンルのカラ・ユルク・オスマン・ベイに引き渡した。アク・コユンルの統治は16世紀初めまで続いた。", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["カラマン侯国、カイセリをドゥルカディル家から奪う", "2b09e8e8"], "d": ["カラマン侯はドゥルカディル家に対して収めた勝利により、カイセリ、ユルギュップ、デヴェリ・カラヒサル、ウチヒサルを自国に加えた。", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["ブチュクテペ事件 - 最初のイェニチェリの蜂起とムラト2世の復位", "6388dda1"], "d": ["エディルネで起きた、歴史上知られる最初のイェニチェリの蜂起であるブチュクテペ事件は、俸給(ウルーフェ)を半アクチェ引き上げよという要求から始まり、若いメフメト2世の廃位に終わった。ムラト2世は850年サファル月8日にマニサから急ぎ出立し、第二の治世を始めた。この事件は、カプクル軍団がもはや王位に発言権を持つ力となったことを示す最初の徴候であり、ファーティフの生涯にわたるイェニチェリへの警戒を形作った。", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["エピロス沿岸の併合:アルタとプレヴェザ", "796f7ecf"], "d": ["ヤニナが1430年に降伏してから19年後、エピロス専制公国の沿岸部のアルタとプレヴェザもオスマンの統治下に入った。これによりイオニア海に開くアンブラキア湾が掌握され、ヤニナの海への連絡路が完成した。プレヴェザは、90年後にバルバロスの歴史的勝利にその名を与えることになる湾の要衝である。", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["ムラト2世の死去とメフメト2世の二度目の即位", "8f8256ad"], "d": ["息子の婚礼の後に病に倒れたムラト2世は、855年ムハッラム月1日(1451年2月3日)にエディルネで死去した。19歳のメフメト2世は、855年ムハッラム月16日(1451年2月18日)に二度目のオスマン王位に就いた - 今度は恒久的に。5年前にブチュクテペで退位させられた若い君主の復帰は、2年後のコンスタンティノープル征服で頂点に達し、オスマン侯国を世界帝国に変える治世の始まりである。", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["オスマン-クリム合同軍による最初のカッファ攻囲", "e346d163"], "d": ["1454年6月にファーティフ・スルタン・メフメトと協定を結んだクリム・ハン国のハジ・ギレイは、7千騎でカッファを陸から包囲し、50〜60隻のガレー船からなるオスマン艦隊も沖に陣取った。ジェノヴァ領のカッファは貢納を払って包囲を解かせ、最終的な征服は21年後の1475年に持ち越された。この最初の共同作戦は、オスマン-クリムの軍事協力が後にカッファの最終的な征服で繰り返される最初の例であった。", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["北エーゲ海の島々の奪取:ボズジャアダ、イムロズ、タソス", "76575895"], "d": ["コンスタンティノープル征服の直後、ファーティフ・スルタン・メフメトは新首都の海路を確保するため、ダーダネルス海峡のエーゲ海側の島々に向かった。ボズジャアダ(テネドス)とイムロズ(インブロス)はビザンツから、タソスはジェノヴァ系のガッティルージオ家から取られた。海峡の両岸を封じるこれらの島々は、以後コンスタンティノープルの糧食と防衛線の最初の環となった。教皇とヴェネツィアの艦隊の介入により支配はしばらく行き来し、1459年になってようやく確定した。", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["コソヴォの征服:プリシュティナとイェニパザルの奪取", "d7ed2345"], "d": ["セルビア専制公国に進軍したオスマン軍は、コソヴォ平原のプリシュティナとラシュカ地方の中心イェニパザルを占領した。同じ作戦で銀鉱山で名高いノヴォ・ブルドも奪われた。これでセルビアの南半分が直接オスマンの統治下に入り、スメデレヴォの専制公国はその中核の領土から切り離された。この征服は、4年後のセルビアの完全な併合に至る道の決定的な一歩であった。", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["イペク(ペチ)、オスマンの統治下に入る - ドゥカキン・サンジャクの中心の一つ", "19511588"], "d": ["1455年のファーティフ・スルタン・メフメトのセルビア遠征の直後に、セルビア総主教座の所在地イペクがオスマンの統治に移った。オスマンの史料にはこの移行に関する記録はない。町は時とともに小さなムスリムの町となり、ドゥカキン・サンジャクでサンジャク・ベイの居所の一つとなった。", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["エネズとサモトラキ島の征服 - 西トラキア沿岸の完成", "106e723b"], "d": ["マリツァ川が海に注ぐ地点のエネズは、80年間そこを保持していたジェノヴァ系のガッティルージオ家から奪われ、同市に属するサモトラキ島も同じ作戦で占領された。エネズの陥落により、西トラキアの沿岸帯はテッサロニキからゲリボルまで途切れないオスマン領となった。ガッティルージオ家の手にはミディッリ(レスボス)だけが残り、それも6年後に奪われることになる。", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["ベオグラード攻囲の失敗", "3d53a604"], "d": ["ファーティフ・メフメトは、コンスタンティノープル征服後、中欧の鍵とされるベオグラードを包囲した。しかしヤーノシュ・フニャディがドナウ川から連れてきた増援と、十字軍の説教師カピストラーノが集めた義勇兵が城の陥落を防いだ。スルタンは攻囲の前で見せた個人的な勇猛にもかかわらず、負傷して撤退せざるを得なかった。この失敗は、ハンガリー国境を65年間オスマンの進出に対して閉ざし、ベオグラードは1521年にカーヌーニーによってようやく奪われることになる。", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["北モレアの征服:バリャバドラ(パトラ)", "c08a8509"], "d": ["セルビアの併合と同じ年に、モレア専制公国に向かったファーティフ・スルタン・メフメトの軍は、半島北西部のバリャバドラを占領した。コリント湾の入口を押さえるこの港はモレアへの陸路からの入口の鍵であり、その奪取は2年後の最終的な征服の下地を整えた。同市はビザンツ専制公たちがラテン世界と連絡を取る最後の大きな船着き場であった。", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["黒海西岸の奪取:アマスラ", "f43608fc"], "d": ["ジェノヴァの黒海西部における城塞植民市アマスラは、ファーティフ・スルタン・メフメトの海軍と陸軍の共同圧力により、抵抗せずに降伏した。バルトゥン-ゾングルダク沿岸のこの港は、カンダル侯国とオスマン領との間のラテン人の飛び地として存在していた。その奪取によって沿岸は一体化した。アマスラの陥落は、2年後(1461年)のシノプとトレビゾンドへの大黒海遠征の第一歩である。", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["ミディッリ島(レスボス島)の征服", "fe17aeba"], "d": ["ファーティフ・スルタン・メフメト率いるオスマン軍は、866年ズルヒッジャ月に、短くも激しい包囲の末にミディッリをジェノヴァ系ガッティルージオ家の手から奪い、併合した。北エーゲ海最大の島の陥落は、ジェノヴァ人の同地域における最後の重要拠点も一掃した。島はアナトリア沿岸に近いことから、以後オスマン海軍の前哨として働き、またバルバロス兄弟が育った地として海事史に名を残すことになる。", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["16年に及ぶオスマン-ヴェネツィア戦争の開始", "563ddb68"], "d": ["ヴェネツィア人は、オスマンのモレアとエーゲ海での進出を止めるため、カラマンおよびアク・コユンルの統治者たちと同盟し、1463年に戦争を始めた。東にウズン・ハサン、西にヴェネツィア、その間にカラマンという包囲戦略は、ファーティフを同時に複数の戦線で戦わせることを強いた。16年続いた戦いは、オトゥルクベリからアルバニア遠征まで当時のあらゆる大きな作戦を含み、1479年のイスタンブル条約でようやく終わることになる。", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["ヘルツェゴヴィナの大部分の征服:トレビニェとモスタル", "f54c0100"], "d": ["ボスニアから分かれた統治を築いたヘルツェゴヴィナ公ステファン・ヴクチッチ・コサチャの領土は、ボスニア王国の滅亡から3年後に大部分がオスマンの統治に移った。南部のトレビニェは1466年に「ほぼヘルツェゴヴィナ全域とともに」奪われた。ネレトヴァ橋の二つの小さな城の周りに築かれたモスタルも、ヘルツェゴヴィナの中心ブラガイの1466-1468年の征服の少し前に奪われたに違いない。1468-1469年のボスニア総括検地簿には「キョプリュリュ・ヒサル」の名で記録されている。公国の残りの城とともにヘルツェゴヴィナの征服が完了するのは1483年である。", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["第2次アルバニア遠征 - ファーティフ自らのスカンデルベグへの進軍", "9cdd2bfa"], "d": ["スカンデルベグの四半世紀を超える抵抗を砕くため、ファーティフ・スルタン・メフメトは1466-1467年に自ら指揮する大規模な遠征を行った。オスマン軍はアクチャヒサル(クルヤ)を包囲し、地域を押さえるためイルバサン(エルバサン)城を築いた。遠征はアルバニアの抵抗の背骨を折ったが、城を落とすことはできなかった。地域の完全な服属は、スカンデルベグの死後10年を要することになる。", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["カラ・コユンル国の崩壊:ジハーン・シャーの殺害", "30bc6358"], "d": ["ウズン・ハサンに向けた遠征から冬の到来で引き返す途中に奇襲を受けたカラ・コユンルの君主ジハーン・シャーは、ビンギョルとクウの間を逃走中に殺された。この打撃の後、国家は立ち直れず、最後の君主ハサン・アリは1469年にウズン・ハサンの子ウウルル・メフメトに捕らえられて殺された。東アナトリア、アゼルバイジャン、イラクで1世紀近く君臨したカラ・コユンルの支配は、こうしてアク・コユンルに移った。", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["スカンデルベグの死 - アルバニアの抵抗の鎮静", "9158c35f"], "d": ["オスマンの宮廷で育ちながら、1444年のイズラディの敗北の後に反乱を起こし、四半世紀を超えてアルバニアで抵抗したスカンデルベグは、身を寄せていたレジェで死んだ。ムラト2世とファーティフの時代にオスマン軍を幾度となく足止めしたこの抵抗は、彼の死により中心的な指導者を失った。教皇とヴェネツィアが支えたアルバニア戦線の崩壊により、オスマンは10年以内にアクチャヒサルとシュコドラを奪い、地域を最終的に領土に加えた。", "5c7cffad"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["モルダヴィアのラコヴァ(ヴァスルイ)の敗北", "a1a74bf7"], "d": ["モルダヴィア公ステファン・チェル・マレは、ルメリア総督ハドゥム・スレイマン・パシャ率いるオスマン軍を沼沢地に誘い込んで大敗させた。ファーティフ時代で最も重い陸戦の敗北の一つであるこの敗北はヨーロッパで大きな反響を呼び、ステファンに十字軍世界での名声をもたらした。スルタンは翌年、報復のため自ら出征することになる。", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["アクデレ(ヴァレア・アルバ)の勝利 - モルダヴィア遠征", "45a66791"], "d": ["1年前のラコヴァの敗北の報復のため自ら出征したファーティフ・スルタン・メフメトは、オスマン軍とともにモルダヴィア軍をアクデレの地で大敗させ、侯国の中心スチャヴァに入った。しかし城は奪えず、食糧難、イェニチェリの間に広がった疫病、ハンガリーの準備のために軍は撤退を余儀なくされた。モルダヴィアの最終的な服属は、その後の年月と、1484年のキリアとアッケルマンの奪取によってようやく達成されることになる。", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["アクチャヒサル(クルヤ)の征服とアルバニアの完了", "559a79b4"], "d": ["スカンデルベグの死から10年後の1478年に、アクチャヒサル、ドリヴァスト、レジェ、ヤブヤクが占領されて、アルバニアの征服はおおむね完了した。長年オスマン軍に抵抗し、スカンデルベグの抵抗の象徴であったクルヤ城の陥落は、地域におけるヴェネツィア-アルバニア同盟の終わりを意味した。残るシュコドラは翌年に結ばれるイスタンブル条約でオスマンに譲渡されることになる。", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["タマン半島の編入", "4ef917b8"], "d": ["1475年のカッファ(ケフェ)とケルチの奪取の後、ファーティフ・メフメトがカフカス沿岸に送った艦隊は、アナパおよびコパとともに、タマン半島のジェノヴァ領マトレガ(タマタルハン)を占領した。これで海峡の両岸が掌握され、アゾフ海への入口が完全に管理下に入った。タマンは北カフカスへの門として、ケフェ・サンジャクに編入された。", "74a0de9f"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["ロドス攻囲の失敗", "35a85c28"], "d": ["ファーティフ・スルタン・メフメトの命により、メスィフ・パシャ指揮下の160隻の艦隊が885年(1480年)の春にロドスを包囲し、島は3か月にわたり封鎖された。総長ピエール・ドービュッソン率いる聖ヨハネ騎士団は大きな損害にもかかわらず激しく抵抗した。885年ジュマーダー・アル=ウーラー月20日の最後の大攻撃も撃退されたため、艦隊は8月3日に撤退した。この失敗の後、都市の城壁は一から改築されてヨーロッパ最強の要塞となり、島はようやく1522年にカーヌーニーによって奪われることになる。", "23334bd0"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["イェニシェヒルの戦い - ジェム・スルタンの敗北", "c35abee2"], "d": ["ファーティフの死の後、王位を求めて動いた二人の兄弟はイェニシェヒル平原で対峙し、ジェム・スルタンは決定的な敗北を喫した。ブルサで18日間統治して自分の名で説教(フトバ)を読ませた王子は、敗北後、まずコンヤへ、次いでマムルーク朝領へ逃れざるを得なかった。イェニシェヒルはオスマン史上最も長引いた王家の危機を引き起こした。ジェム問題は14年間、オスマンの対ヨーロッパ外交を麻痺させることになる。", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["ヘルツェゴヴィナの併合", "bf247891"], "d": ["1463年のボスニアの征服の後も残っていたヘルツェゴヴィナ公国の領土は、段階的にオスマンの統治に移った。トレビニェとモスタルは1466年に奪われ、ヘルツェゴヴィナ・サンジャクは1470年に編成され、公国のアドリア海岸の最後の領土もヘルツェグ・ノヴィとともに1482年初めに征服されてサンジャクに加えられた。こうしてアドリア海の背後の山岳地帯はすべてオスマンのものとなり、ボスニアとヘルツェゴヴィナは一つの行政地理にまとまった。最後の公の子でオスマン宮廷に入り、のちに大宰相にまで昇ったのがヘルセクザーデ・アフメト・パシャである。", "0522e47f"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["ジェム・スルタンのロドスへの避難", "2228d6da"], "d": ["コンヤ包囲の試みも不調に終わったジェム・スルタンは、30人ほどの従者とともにアナトリアから逃れてロドスに着き、聖ヨハネ騎士団に儀礼をもって迎えられた。しかし客人としての待遇は間もなく虜囚に変わった。王子はまずフランスに、次いで教皇庁に引き渡され、ヨーロッパの政治の手中の切り札となった。バヤジト2世は兄弟の身柄の拘束の見返りに毎年の支払いを強いられ、オスマンの西方への軍事行動はジェムの死まで停止された。", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["オスマン-マムルーク戦争の開始(チュクロヴァ戦線)", "3fe3f0c7"], "d": ["ドゥルカディル家をめぐる影響力争いと、ジェム・スルタンがマムルーク朝領に避難したことが残した敵意により、1485年に二つのスンナ派大国の間で6年続く戦争が始まった。チュクロヴァのアダナとタルスス周辺で行われた戦闘で、両者は互いに優位に立てず、オスマン軍はいくつかの重い打撃を受けた。この戦争はオスマン-マムルーク関係における亀裂の最初の局面であり、30年後のヤヴズによるマルジュ・ダービクとリダニーヤの遠征で決着する過程の始まりである。", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["オスマン-マムルーク和平 - チュニスの仲介", "60dd6719"], "d": ["1485年に始まったオスマン-マムルーク戦争で両者は決定的な勝利を得られず、チュニス君主ウスマーン・ハフス朝の仲介により1491年に合意に達した。条約は国境をほぼ戦前の状態に戻し、二つのイスラーム国家の間の決着は一世代の間延期された。6年にわたる消耗戦は、バヤジト2世の慎重な外交政策と、東方への進出よりも内政の整備に重きを置いた主な理由の一つである。", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["スペインから追放されたセファルディムのユダヤ人のオスマンへの受け入れ", "5c2b5c24"], "d": ["グラナダの陥落の後、スペインで異端審問の迫害を逃れたユダヤ人の一部はオスマン領に避難し、さまざまな都市に入植させられた。オスマンの統治下でこのセファルディムの共同体は、望む場所に定住し、信仰を実践し、教育機関を開き、新しいシナゴーグを建てるという、それまで経験しなかった自由を得た。印刷、医学、財政の知識を携えてテッサロニキとイスタンブルの経済生活を変えたこの移住は、オスマンの寛容の秩序がヨーロッパで最も語られる例となった。", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["ジェム・スルタンの死 - 14年に及ぶ人質の終わり", "f6588b70"], "d": ["教皇庁からフランス王シャルル8世に引き渡されたジェム・スルタンは、1495年1月27日にローマを出発した後、カステル・カプアーナと呼ばれる地で死んだ。史料は教皇庁筋によって毒殺された可能性を記している。14年間、ヨーロッパ諸国の手にオスマンに対する脅しの切り札として置かれていた王子の死は、バヤジト2世の手をついに自由にした。実際スルタンはこれ以後ヴェネツィアに宣戦し、艦隊を最初の大きな勝利に導くことになる。", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["サピエンツァ(ゾンキオ)の海戦 - 地中海における最初の大規模な海軍の成功", "9754aaef"], "d": ["ジェム問題の終結で手が自由になったバヤジト2世は1499年にヴェネツィアに宣戦した。オスマン艦隊はサピエンツァ(ゾンキオ)沖でヴェネツィア艦隊を破り、地中海における最初の大きな海戦の勝利を収めた。この勝利により艦隊は、もはやヴェネツィアに海で対抗できることを宣言した。", "5fa6989c"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["ジョチ・ウルス(金帳汗国)の滅亡とクリムの台頭", "0d1dc515"], "d": ["最後の君主シェイフ・アフメト・ハン(1481-1502年)は、国が陥った混乱から救い出すことができず、金帳汗国は1502年にクリム・ハンのメングリ・ギレイの一撃によって歴史から消えた。王位争いと分裂の結果、旧金帳汗国領にはクリム、カザン、ノガイ、アストラハン、シビルの諸ハン国が現れた。オスマンの保護下にあるクリムのこの勝利は黒海北方でのオスマンの影響を疑いないものにしたが、地域に生じた空白は次の世紀にモスクワが埋めることになる。", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["オスマン-ヴェネツィア戦争の終結と和平", "125b1526"], "d": ["1499年に始まり、サピエンツァ、レパント、モドン、コロンの喪失でヴェネツィアを揺るがした戦争は、1502年に和平で終わった。ヴェネツィアはモレアで最も重要な基地を失い、東地中海における通商特権を守る代わりにオスマンの優位を認めざるを得なかった。慎重とされたバヤジト2世の治世は、この戦争によってオスマンを地中海で初めて本格的な海軍国の地位に引き上げた。", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["シャーフクルの乱 - テケ地方からスィヴァスに及ぶキズルバシュの蜂起", "3beadca7"], "d": ["サファヴィー朝のプロパガンダのアナトリアへの影響で1510年に反乱を公然と起こしたシャーフクル・ババ・テケリは、1511年3月にアンタルヤの市場を襲い、4月にはキュタヒヤとその周辺でオスマン軍を破っていた。スィヴァス近郊で大宰相ハドゥム・アリ・パシャと交えた最後の戦闘で双方とも大きな損害を出し、大宰相も反乱の指導者も命を落とした。国家のアナトリアにおける権威を揺るがしたこの蜂起は、バヤジト2世の晩年の権力の空白をあらわにし、シェフザーデ・セリムの即位への進軍の最も強い根拠となった。", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["バヤジト2世の退位とヤヴズ・スルタン・セリムの即位", "c4cfab69"], "d": ["兄弟たちとの王位争いでイェニチェリの支持を背にしたシェフザーデ・セリムの圧力により、バヤジト2世は1512年4月24日に退位し、セリム1世が同日、9代目のオスマン君主として即位した。老スルタンは、生まれ故郷のディメトカへ向かう途中、チョルル近郊のアバラル村で918年ラビーウ・アル=アウワル月25日(1512年6月10日)に死去した。31年に及ぶ慎重で内向きの治世に代わって、8年で帝国の版図を倍にするヤヴズの時代が来た。", "7194b8c2"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["イェニシェヒルの戦いとシェフザーデ・アフメトの排除", "e2ed15dd"], "d": ["ヤヴズ・スルタン・セリムは、王位の最強のライバルである兄シェフザーデ・アフメトを、ブルサ近郊のイェニシェヒル平原で破り、捕らえて排除した。これにより1511年から続いた兄弟の争いは終わり、アナトリアの内部分裂は終息した。セリムは背後を固め、サファヴィー問題に向かう自由を得た。", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["ヤヴズ・スルタン・セリムのタブリーズ入城", "dad2e227"], "d": ["チャルディランの勝利の後、オスマン軍はサファヴィー朝の首都タブリーズに入り、都市でスルタンの名でフトバが読まれた。セリムはここに1週間滞在し、タブリーズの芸術家とウラマーの一部をイスタンブルへ移住させた。この移住はオスマンの宮廷美術に深い影響を与えることになる。冬の接近とイェニチェリの不満により都市は放棄されたが、東方でのサファヴィーの優位は砕かれていた。地図上でこの日にオスマンに移った地が互いに隣接していないのは正しい:タブリーズは9日間の軍事占領である。エルズィンジャン平原は遠征中に無血で降伏し、その中央のケマフ城は1515年5月19日までサファヴィー側で抵抗した。スィイルトは、タブリーズでシャー・イスマーイールの獄から解放されたハサンケイフの領主ハリル・ベイがオスマンに服従してサファヴィー朝から取り戻した - その周辺のディヤルバクルは1515年まで、ハサンケイフは1517年までサファヴィーのままであった。", "3f65211e"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["ケマフ城のサファヴィー朝からの征服", "73fd8671"], "d": ["チャルディランからの帰途に冬をアマスヤで過ごしたヤヴズ・スルタン・セリムは、ユーフラテスの渡河点を押さえる堅固なケマフ城の征服をビユクル・メフメト・パシャに命じた。スルタンも自ら加わった包囲の末に城はサファヴィー朝の手から奪われ、東アナトリアの門が開かれた。この征服は、チャルディランの勝利を恒久的な領土の獲得に変える最初の具体的な一歩である。", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["トゥルナダー(Turnadağ)の勝利 - ドゥルカディル侯国、オスマンに服属", "fd879145"], "d": ["オスマン軍は、チャルディラン遠征の際に態度を曖昧にしたドゥルカディル侯アラーッデヴレ・ボズクルトを、ギョクスンとアンドゥルンの間のオルデクリの地で破り、アラーッデヴレはこの戦いで殺された。侯国はこの日には併合されなかった。アラーッデヴレの後、ドゥルカディル侯国の長にはヤヴズ・スルタン・セリムによってシェフスヴァルオウル・アリ・ベイが就けられ、マラシュ-エルビスタンを中心とする国はオスマンに服属する侯国として続いた。マムルーク朝との国境の緩衝地はこうしてオスマンの管理下に入り、2年後のエジプト遠征への道が開かれた。併合はアリ・ベイの殺害の後に行われることになる。", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["アーミド(ディヤルベクル)の征服とディヤルベクル総督領の設置", "a6867d5b"], "d": ["イドリース・ビトリースィーが地域のスンナ派クルド人ベイたちをオスマンの側につけた後、サファヴィー軍は長い包囲に耐えられず、アーミドの鍵はビユクル・メフメト・パシャに引き渡された。都市は新設のディヤルベクル総督領の中心とされた。こうして上メソポタミアの行政の核がオスマンの手に渡った。", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["ハルプトの征服 - ディヤルベクルへの道の開通", "564eb269"], "d": ["チャルディランの後に奪ったディヤルベクルをサファヴィーの包囲から救うため出発したカラマン総督ヒュスレヴ・パシャは、周辺を先にチェルケス・ヒュセイン・ベイが占領していたハルプト城を3日間の包囲の末に奪った。ユーフラテスの東でディヤルベクルへ至る道はこうして確保された。", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["コチヒサル(クズルテペ)の戦い - カラ・ハンの敗北", "9ea9e843"], "d": ["ビユクル・メフメト・パシャ率いるオスマン軍は、コチヒサル近くのデデ・ガルクン平原のコルク地で、サファヴィーの総督カラ・ハンを終日続いた野戦で破った。カラ・ハンの首は、スルタンの陣営に送られた。続いてオスマン軍はマルディン市に入ったが、数日で去った。サファヴィーの守備兵が守るマルディン城は1年後にようやく接収された。この勝利は、ヤヴズが南の国境を確保してエジプト遠征に向かうことを可能にした。同日に編入されたその他の地:パル、チェミシュゲゼク、シヴェレク。", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["ヤヴズ・スルタン・セリムのエジプト遠征のためのイスタンブル出発", "ac258b4b"], "d": ["ヤヴズ・スルタン・セリムは、表向きはサファヴィー朝に対する新たな東方遠征の準備として、イスタンブルを出発し、アクシェヒルを経て南に向かった。マムルーク朝のスルタン、カンスー・ガウリーがシャー・イスマーイールと接触してオスマンの東翼を脅かしたことが、目標をまもなく変えさせることになる。遠征は2年続き、オスマンを中東の帝国に変える大作戦の始まりである。", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["ザビードの奪取:オスマンの海の者たちの紅海への最初の進出", "38740e0c"], "d": ["ポルトガルのインド洋での圧力に対し、マムルーク朝のスルタン、カンスー・ガウリーの要請で紅海に派遣されたオスマン出身の海の者フサイン・ベイとサルマン・レイスは、艦隊でザビードを占領した。なおマムルーク朝の下で行われたこの作戦は、オスマン海軍の紅海-インド線における最初の事実上の存在である。1年後にエジプトがオスマンに移ると、この艦隊は直接イスタンブルに属することになる。", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["遠征の目標がマムルーク朝とアレッポであることの正式な宣言", "689e310d"], "d": ["ヤヴズ・スルタン・セリムは、カンスー・ガウリーがサファヴィー朝と協定して軍をアレッポに進めたことを受け、遠征の目標をマムルーク朝のスルタンとアレッポであると公然と宣言した。こうして二つのスンナ派国家の間で長年続いた隠れた競争は、公然たる戦争に変わった。この宣言は、マルジュ・ダービクへの4週間のカウントダウンを始めた。", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["アデン攻囲の失敗:ポルトガルに対する最初の紅海での試み", "8ffd46f2"], "d": ["サルマン・レイスとフサイン・ベイは、紅海のインド洋への門であるアデンを奪うため8日間にわたる攻囲を行ったが、都市の強力な防備の前に撤退せざるを得なかった。アデンを奪えなかったことは、ポルトガルに対する南方戦略を長年妨げることになる。この試みは、オスマンの海洋政策における最初の試練である。", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["ラマザン侯国のオスマンへの帰属", "cfaa3754"], "d": ["マルジュ・ダービクの勝利の後に行われた任命の際、アダナを中心とするラマザン侯国はマフムト・ベイに与えられ、オスマンの宗主権下に置かれた。マムルーク朝への臣従を離れた侯国は、廃止されるのではなく「オジャクルク」の地位で一族に委ねられた。ラマザン家はチュクロヴァの統治を、オスマンのサンジャク・ベイとして続けた。この特権的な制度は、ピール・マンスールが侯位を離れた1608年まで続いた。同日に編入されたその他の地:マラティヤ、タルスス、モスル、アンテプ。", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["アレッポ、ラッカ、デイルッゾールのオスマン支配への編入", "2088eb6a"], "d": ["マルジュ・ダービクの4日後、ヤヴズ・スルタン・セリムは抵抗を受けずにアレッポに入り、都市のモスクでは彼の名でフトバが読まれた。シリアの商業と行政の首都とされるアレッポがこれほど早く陥落したことは、地域でマムルーク朝の権威が崩れていたことを示す。都市の奪取により、ダマスクスへ、そしてそこからエジプトへ至る道が一気に開かれた。同日に編入されたその他の地:アンタキヤ、ラッカ、デイルッゾール。", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["アレッポのギョクメイダンでアッバース朝カリフ、ムタワッキル3世との会見", "22979f42"], "d": ["マルジュ・ダービクでマムルーク軍とともに捕虜となったカイロのアッバース朝カリフ、ムタワッキル3世は、アレッポのギョクメイダンでスルタンの御前に引き出され、ヤヴズ・スルタン・セリムは彼に大きな敬意を示した。1261年からマムルーク朝のスルタンの影で象徴的な地位にあったカイロのカリフ位は、この会見で事実上オスマンの保護下に移った。カリフはのちにスルタンとともにイスタンブルへ連れて行かれることになる。", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["トリポリ(トラブルスシャーム)とハマー、オスマンの統治下に入る", "a1e19a79"], "d": ["アレッポとハマーに続き、シリア沿岸のトリポリも抵抗せずにオスマンの統治に移った。東地中海で最も繁華な港の一つであった同市はダマスクスの海への門であり、絹と砂糖の交易の中心であった。その奪取により、ビラード・アッシャームの沿岸帯はすべて手を替えた。", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["ダマスクスのオスマン支配への編入", "2b844d91"], "d": ["アレッポの後、ハマーとホムスが降伏して前途が開けたヤヴズ・スルタン・セリムは、9月27日にダマスクスの前に達した。都市にはすぐに入らず外のマスタバの地に幕営を張り、到着の12日目に盛大な儀礼とともに入城した。ダマスクスに長く滞在してシリアの行政秩序を整え、ムヒッディーン・イブン・アラビーの墓廟を建てさせた。こうしてビラード・アッシャームの全域がマムルーク朝の統治を離れた。同日に編入されたその他の地:ベイルート。", "7cd1cd2b"]}
});
